# ---------------------------------------------------------------------------
# CAFLS — Complex-Anchored Filterbank Logarithmic Scaling
# Lower scale bound for CWT: seismic floor (~0.01 Hz).
# log2(cafls_anchor / CAFLS_SEISMIC_FLOOR) ≈ 11.6 octaves of scale range.
CAFLS_SEISMIC_FLOOR: float = 0.01  # Hz

# Filter bank decomposition — arbitrary crossover with perfect reconstruction
# ---------------------------------------------------------------------------

_FILTER_TYPES = ["Linkwitz-Riley 4", "Butterworth 4", "Butterworth 8"]
_CQT_ALGORITHMS = ["librosa", "nsgt", "stft"]
_CQT_ALGORITHM_LABELS = ["CQT", "CQ-NSGT", "STFT"]
_CQT_WINDOWS = ["hann", "hamming", "blackman", "blackmanharris"]
_FB_CONFIG_MODES = ["Manual", "Auto (log)"]


def hybrid_crossover_freq(bpo: int, hop: int, sr: int) -> float:
    """Return the frequency below which filterbank Hilbert envelopes
    provide tighter time resolution than the CQT at the given settings.

    CQT bin bandwidth at frequency *f* is ``f * (2^(1/bpo) - 1)``.
    The CQT hop adequately samples the envelope when
    ``hop <= sr / (2 * bandwidth)``, i.e. above::

        f_cross = sr / (2 * hop * (2^(1/bpo) - 1))
    """
    ratio = 2.0 ** (1.0 / bpo) - 1.0
    if ratio <= 0:
        return float(sr / 2)
    return sr / (2.0 * hop * ratio)

_RESAMPLE_ENGINES = ["scipy", "soxr"]
_RESAMPLE_INTERPS = ["sinc", "linear", "nearest", "cubic"]
_RESAMPLE_TAPS = ["8", "16", "32", "64", "128", "256"]
_RESAMPLE_PRECISIONS = ["16-bit", "24-bit", "32-bit float", "64-bit float"]
_ANALYSIS_COMPUTE_PRECISIONS = ["32-bit", "64-bit"]
_ANALYSIS_SAVE_PRECISIONS = ["16-bit", "32-bit", "64-bit"]

# Signal-engine output sample-rate options.  0 = native (no resample).
_SIGNAL_OUT_SR_OPTIONS: list[int] = [0, 8000, 11025, 16000, 22050, 44100, 48000, 88200, 96000]
_SIGNAL_OUT_SR_LABELS: list[str] = ["native", "8k", "11k", "16k", "22k", "44.1k", "48k", "88.2k", "96k"]

# Signal-engine save-precision options → (soundfile subtype, numpy write dtype)
_SIGNAL_SAVE_PRECISIONS: list[str] = ["16-bit int", "24-bit int", "32-bit float", "64-bit float"]
_SIGNAL_SAVE_SF_SUBTYPE: list[str] = ["PCM_16", "PCM_24", "FLOAT", "DOUBLE"]
