def _precision_label_to_np_dtype(label: str) -> np.dtype:
    return {
        "16-bit": np.float16,
        "32-bit": np.float32,
        "64-bit": np.float64,
    }[label]


def _precision_label_to_bits(label: str) -> str:
    return label.split("-", 1)[0]


def _precision_label_to_real_dtype(label: str) -> np.dtype:
    bits = _precision_label_to_bits(label)
    return np.float64 if bits == "64" else np.float32


def _encode_scaled_float_arrays(
    arrays: list[np.ndarray], save_dtype: np.dtype,
) -> tuple[list[np.ndarray], float | None]:
    """Encode float arrays for NPZ storage.

    For float16, arrays are scaled by a shared max-abs factor before casting so
    large coefficients do not overflow and quiet structure keeps usable range.
    """
    if save_dtype == np.float16:
        max_abs = 0.0
        for arr in arrays:
            if arr.size:
                max_abs = max(max_abs, float(np.abs(arr).max()))
        scale = max_abs or 1.0
        return [np.asarray(arr / scale, dtype=np.float16) for arr in arrays], scale
    return [np.asarray(arr, dtype=save_dtype) for arr in arrays], None


def _decode_scaled_float_array(arr: np.ndarray, scale: float | None) -> np.ndarray:
    if scale is None:
        return arr
    return np.asarray(arr, dtype=np.float32) * float(scale)

# Musically meaningful BPO values (all multiples of 12)
_BPO_SNAPS = [12, 24, 36, 48, 60, 72, 96, 120, 240, 360, 600, 1200]

_NOTE_NAMES = ["C", "C#", "D", "D#", "E", "F",
               "F#", "G", "G#", "A", "A#", "B"]


def _midi_to_freq(midi: int) -> float:
    """MIDI note number → frequency (A4 = 440 Hz, MIDI 69)."""
    return 440.0 * (2.0 ** ((midi - 69) / 12.0))


def _freq_to_note_name(freq: float) -> str:
    """Return the nearest Western note name + octave for *freq* Hz."""
    if freq <= 0:
        return "—"
    midi = 69 + 12 * math.log2(freq / 440.0)
    midi_r = round(midi)
    name = _NOTE_NAMES[midi_r % 12]
    octave = (midi_r // 12) - 1
    return f"{name}{octave}"


def _snap_to_note(freq: float) -> float:
    """Snap *freq* to the nearest equal-temperament semitone (A440)."""
    if freq <= 0:
        return freq
    midi = 69 + 12 * math.log2(freq / 440.0)
    return _midi_to_freq(round(midi))


def _snap_to_note_up(freq: float) -> float:
    """Snap *freq* UP to the nearest semitone >= freq."""
    if freq <= 0:
        return freq
    midi = 69 + 12 * math.log2(freq / 440.0)
    return _midi_to_freq(math.ceil(midi - 1e-9))


def _snap_to_note_down(freq: float) -> float:
    """Snap *freq* DOWN to the nearest semitone <= freq."""
    if freq <= 0:
        return freq
    midi = 69 + 12 * math.log2(freq / 440.0)
    return _midi_to_freq(math.floor(midi + 1e-9))


def _freq_fmt(val: float) -> str:
    """Return a format string with appropriate decimal precision for *val* Hz."""
    av = abs(val)
    if av >= 100:
        return "{:.0f}"
    if av >= 10:
        return "{:.1f}"
    if av >= 1:
        return "{:.2f}"
    if av >= 0.01:
        return "{:.4f}"
    return "{:.6f}"


def _snap_bpo(val: float) -> int:
    """Snap a raw BPO value to the nearest entry in _BPO_SNAPS."""
    best = _BPO_SNAPS[0]
    best_dist = abs(val - best)
    for s in _BPO_SNAPS[1:]:
        d = abs(val - s)
        if d < best_dist:
            best, best_dist = s, d
    return best


_FB_LABEL_MODES = ["Range", "Mid+BW"]


@dataclass
class BandDef:
    """One band in a crossover filter bank."""
    fmin: float    # 0.0 means from DC
    fmax: float    # >= Nyquist means to Nyquist
    label: str = ""
    enabled: bool = True

    @property
    def centre(self) -> float:
        """Geometric centre frequency of the band."""
        lo = max(self.fmin, 1e-3)
        return math.sqrt(lo * self.fmax)

    def auto_label(self, sr: int) -> str:
        nyq = sr / 2.0
        lo = "DC" if self.fmin <= 0.0 else f"{self.fmin:.0f}"
        hi = "Nyq" if self.fmax >= nyq else f"{self.fmax:.0f}"
        return f"{lo}-{hi} Hz"

    def mid_label(self, sr: int) -> str:
        """Label showing middle frequency and bandwidth."""
        nyq = sr / 2.0
        fc = self.centre
        bw = min(self.fmax, nyq) - max(self.fmin, 0.0)
        note = _freq_to_note_name(fc)
        if fc >= 1000:
            mid_str = f"{fc / 1000:.2f}k"
        else:
            mid_str = f"{fc:.1f}"
        if bw >= 1000:
            bw_str = f"{bw / 1000:.1f}k"
        else:
            bw_str = f"{bw:.0f}"
        return f"{mid_str}Hz {note} bw{bw_str}"


_CAFLS_CENTER_LABEL = "f\u2090"


def _infer_fb_center_hz_from_bands(bands: list[BandDef]) -> float | None:
    """Infer the geometric FB inflection point from stored band edges.

    Prefer the explicit CAFLS center label when present. For older or
    relabeled analyses, fall back to detecting an odd-length geometric
    progression of interior crossovers and take the middle band's centre.
    """
    for band in bands:
        if band.label == _CAFLS_CENTER_LABEL and band.fmin > 0.0 and band.fmax > 0.0:
            return math.sqrt(float(band.fmin) * float(band.fmax))

    core = list(bands)
    if core and (core[0].fmin <= 0.0 or core[0].label.strip().upper() in ("LP", "LOWPASS")):
        core = core[1:]
    if core and core[-1].label.strip().upper() in ("HP", "HIGHPASS"):
        core = core[:-1]
    if len(core) < 3 or (len(core) % 2) == 0:
        return None

    edges = [float(core[0].fmin)] + [float(b.fmax) for b in core]
    if any(edge <= 0.0 for edge in edges):
        return None
    log_steps = np.diff(np.log(np.asarray(edges, dtype=np.float64)))
    if log_steps.size == 0 or not np.all(np.isfinite(log_steps)):
        return None
    if float(np.max(np.abs(log_steps - np.median(log_steps)))) > 1e-3:
        return None

    mid_band = core[len(core) // 2]
    if mid_band.fmin <= 0.0 or mid_band.fmax <= 0.0:
        return None
    return math.sqrt(float(mid_band.fmin) * float(mid_band.fmax))


def _is_cuda_oom(e: Exception) -> bool:
    """Return True if *e* is a CUDA out-of-memory condition.

    PyTorch raises torch.cuda.OutOfMemoryError for tensor allocations but
    uses plain RuntimeError for cuFFT workspace allocations and other driver-
    level memory failures.  Both must be treated as OOM for retry logic.
    """
    import torch
    if isinstance(e, torch.cuda.OutOfMemoryError):
        return True
    msg = str(e).lower()
    return any(k in msg for k in (
        "out of memory", "cuda error", "cufft", "cublas",
        "cudnn", "cuda: device-side assert", "cudamallocasync",
    ))


class FilterBankDecomposition:
    """Apply a set of crossover filters to a mono signal, producing
    perfectly-reconstructing subbands.

    Crossover frequencies define the splits; adjacent bands share a
    crossover point.  Linkwitz-Riley 4th-order crossovers sum flat.
    """

    def __init__(self, sr: int, filter_type: str = "Linkwitz-Riley 4",
                 filter_mode: str = "fir") -> None:
        self.sr: int = sr
        self.filter_type: str = filter_type
        self.filter_mode: str = filter_mode   # "fir" or "iir"
        self.bands: list[BandDef] = []
        self.subbands: list[np.ndarray | None] = []    # filtered signal per band
        self._subband_files: list[str | None] = []
        self._subband_file_meta: list[dict[str, Any] | None] = []
        self._subband_real_dt: np.dtype = np.float32
        self._source_signal: np.ndarray | None = None

    @staticmethod
    def bands_from_crossovers(crossovers: list[float], sr: int) -> list[BandDef]:
        """Build band definitions from sorted crossover frequencies."""
        xo = sorted(set(crossovers))
        bands: list[BandDef] = []
        prev = 0.0
        for freq in xo:
            bands.append(BandDef(fmin=prev, fmax=freq))
            prev = freq
        bands.append(BandDef(fmin=prev, fmax=float(sr / 2)))
        for b in bands:
            b.label = b.auto_label(sr)
        return bands

    @staticmethod
    def bands_from_log_spacing(
        bands_per_octave: int,
        fmin: float,
        fmax: float,
        sr: int,
        ceiling: float | None = None,
    ) -> list[BandDef]:
        """Generate log-spaced crossover bands analogous to CQT bins.

        *bands_per_octave* bands are placed per octave between *fmin*
        and *fmax*.  Each crossover sits at the geometric midpoint
        between adjacent band centres, so the resulting bands tile the
        frequency axis without gaps or overlaps.

        If *ceiling* is given, the last band's upper edge is clamped to
        *ceiling* instead of extending to Nyquist.
        """
        nyq = sr / 2.0
        fmin = max(fmin, 1.0)
        fmax = min(fmax, nyq)
        top = ceiling if ceiling is not None else nyq
        top = min(top, nyq)
        # When ceiling is set, also limit which centres are generated
        centre_limit = min(fmax, top) if ceiling is not None else fmax
        if centre_limit <= fmin or bands_per_octave < 1:
            return [BandDef(fmin=0.0, fmax=top,
                            label=BandDef(0.0, top).auto_label(sr))]
        # Band centres snapped to the nearest equal-temperament semitone
        # so that every band is musically meaningful regardless of BPO.
        # Start from the semitone nearest to fmin and step by
        # 12/bpo semitones (so bpo=12 → 1 semitone, bpo=6 → 2, etc.).
        step_semitones = 12.0 / bands_per_octave
        # Nearest semitone index to fmin (relative to A4=440)
        midi_start = round(69 + 12 * math.log2(fmin / 440.0))
        centres: list[float] = []
        k = 0
        while True:
            midi = midi_start + k * step_semitones
            fc = 440.0 * (2.0 ** ((midi - 69) / 12.0))
            if fc > centre_limit:
                break
            if fc >= fmin * 0.99:  # allow tiny undershoot from rounding
                centres.append(fc)
            k += 1
        if not centres:
            centres = [_snap_to_note(fmin)]
        # Crossovers at geometric midpoints between consecutive centres
        crossovers: list[float] = []
        for i in range(len(centres) - 1):
            crossovers.append(math.sqrt(centres[i] * centres[i + 1]))
        # Build bands: DC→first_xo, xo_i→xo_{i+1}, …, last_xo→ceiling/Nyq
        bands: list[BandDef] = []
        prev = 0.0
        for xf in crossovers:
            bands.append(BandDef(fmin=prev, fmax=xf))
            prev = xf
        bands.append(BandDef(fmin=prev, fmax=top))
        for b in bands:
            b.label = b.auto_label(sr)
        return bands

    @staticmethod
    def bands_from_cafls(
        anchor: float,
        bpo: int,
        banded_width: int,
        sr: int,
    ) -> list[BandDef]:
        """Generate CAFLS-anchored filterbank bands.

        One center band is placed at *anchor* (f_a).  Striated bands
        extend *banded_width* octaves each side of the anchor, following
        the scale law  f_n = anchor * 2^(n/bpo).  Beyond the striated
        zone: one solid lowpass (below) down to DC, and one solid
        highpass (above) up to Nyquist.

        All crossovers sit at the geometric midpoint between adjacent
        band centres (scale law: anchor * 2^((n+0.5)/bpo)).
        """
        import math as _math
        nyq = sr / 2.0
        bpo = max(1, bpo)
        banded_width = max(0, banded_width)

        # Band centres: n = -banded_width*bpo … +banded_width*bpo
        # (bpo subdivisions per octave, banded_width octaves each side)
        n_steps = banded_width * bpo          # steps each side
        def ctr(n: int) -> float:
            return anchor * (2.0 ** (n / bpo))

        # Crossover between step n and step n+1
        def xo(n: int) -> float:
            return anchor * (2.0 ** ((n + 0.5) / bpo))

        # Outer crossovers (striated ↔ solid)
        lp_hi  = anchor * (2.0 ** ((-n_steps - 0.5) / bpo))  # LP→striated
        hp_lo  = anchor * (2.0 ** (( n_steps + 0.5) / bpo))  # striated→HP

        bands: list[BandDef] = []

        # Solid lowpass
        bands.append(BandDef(fmin=0.0, fmax=lp_hi, label="LP"))

        # Striated bands: from -n_steps to +n_steps inclusive
        prev = lp_hi
        for n in range(-n_steps, n_steps):
            hi = xo(n)
            centre = ctr(n)
            label = (f"f\u2090" if n == 0
                     else f"f\u2090\u00b72^({n}/{bpo})")
            bands.append(BandDef(fmin=prev, fmax=hi, label=label))
            prev = hi
        # Last striated band: n = +n_steps
        bands.append(BandDef(fmin=prev, fmax=hp_lo,
                             label=f"f\u2090\u00b72^({n_steps}/{bpo})"))

        # Solid highpass
        bands.append(BandDef(fmin=hp_lo, fmax=nyq, label="HP"))

        return bands

    def compute(self, signal: np.ndarray, bands: list[BandDef]) -> None:
        """Apply crossover filters and store subbands."""
        from filter_engine import decompose_bands, FIR, IIR

        self._source_signal = signal.copy()
        self.bands = list(bands)
        self.subbands = []
        nyq = self.sr / 2.0

        order = int(self.filter_type.split()[-1])
        # LR uses half-order for IIR cascade; FIR uses full order directly
        iir_order = order // 2 if self.filter_type.startswith("Linkwitz-Riley") else order
        mode = IIR if self.filter_mode == "iir" else FIR

        crossovers = []
        for b in bands[:-1]:  # all but last band supply their upper edge
            crossovers.append(float(b.fmax))
        crossovers = [xo for xo in crossovers if 0 < xo < nyq]

        # Disabled bands: compute with all crossovers then zero out
        subbands = decompose_bands(
            signal, self.sr, crossovers,
            filter_mode=mode,
            order=order if mode == FIR else iir_order,
        )
        for i, band in enumerate(bands):
            sub = subbands[i] if i < len(subbands) else np.zeros_like(signal)
            if not band.enabled:
                sub = np.zeros_like(sub)
            self.subbands.append(np.asarray(sub, dtype=np.result_type(signal.dtype, np.float32)))

    def _compute_lr(self, signal: np.ndarray, nyq: float,
                    half_order: int) -> None:
        """Legacy IIR Linkwitz-Riley cascade (called only when filter_mode=="iir").

        Kept for reference; compute() now routes through filter_engine.
        """
        from filter_engine import decompose_bands, IIR
        real_dt = np.result_type(signal.dtype, np.float32)
        crossovers = [min(float(b.fmax), nyq * 0.9999)
                      for b in self.bands[:-1] if b.fmax < nyq]
        subbands = decompose_bands(signal, self.sr, crossovers,
                                   filter_mode=IIR, order=half_order)
        for i, band in enumerate(self.bands):
            sub = subbands[i] if i < len(subbands) else np.zeros_like(signal)
            if not band.enabled:
                sub = np.zeros_like(sub)
            self.subbands.append(np.asarray(sub, dtype=real_dt))

    def _compute_butterworth(self, signal: np.ndarray, nyq: float,
                             order: int) -> None:
        """Legacy IIR Butterworth per-band (called only when filter_mode=="iir").

        Kept for reference; compute() now routes through filter_engine.
        """
        from filter_engine import apply_bandpass, IIR
        real_dt = np.result_type(signal.dtype, np.float32)
        for band in self.bands:
            if not band.enabled:
                self.subbands.append(np.zeros_like(signal))
                continue
            flo = band.fmin if band.fmin > 0 else None
            fhi = band.fmax if band.fmax < nyq else None
            if flo is None and fhi is None:
                self.subbands.append(signal.copy())
                continue
            sub = apply_bandpass(signal, self.sr, flo, fhi,
                                 filter_mode=IIR, order=order)
            self.subbands.append(np.asarray(sub, dtype=real_dt))

    def reconstruction_error(self) -> float:
        """RMS error between sum-of-bands and original signal (0.0 = perfect)."""
        if self._source_signal is None or not self.subbands:
            return float("inf")
        recon = np.zeros_like(self._source_signal)
        for i in range(len(self.subbands)):
            recon += np.asarray(self.get_subband(i), dtype=recon.dtype)
        err = self._source_signal - recon
        return float(np.sqrt(np.mean(err ** 2)))

    def reconstruct(self, band_mask: list[bool] | None = None) -> np.ndarray:
        """Sum subbands to reconstruct time-domain audio.

        *band_mask* selects which bands to include (all if *None*).
        With LR crossovers the sum is exact (perfect reconstruction).
        """
        if not self.subbands:
            return np.zeros(0, dtype=np.float32)
        if band_mask is None:
            band_mask = [b.enabled for b in self.bands]
        out = np.zeros_like(self.get_subband(0))
        for i, include in enumerate(band_mask):
            if include:
                out += np.asarray(self.get_subband(i), dtype=out.dtype)
        return out

    def compute_envelopes(self, hop: int | list[int] | None = None,
                          hilbert_progress: Any = None,
                          band_result_cb: Any = None,
                          resume_state: dict[str, Any] | None = None,
                          drop_after_callback: bool = False,
                          stream_chunk_dir: str | None = None,
                          stream_chunk_dtype: np.dtype | None = None,
                          ) -> tuple[list[np.ndarray], list[np.ndarray],
                                     list[int]]:
        """Compute per-band magnitude and phase envelopes via analytic signal.

        *hop* can be a single int (shared), a per-band list, or ``None``
        to auto-compute from each band's bandwidth.

        Returns ``(mags, phases, hops)`` where each element is a list of
        1-D float arrays at the active compute precision and *hops* records the hop
        used for each band.

        When PyTorch + CUDA are available the Hilbert transforms and
        frame-wise peak extraction run as batched GPU operations.
        Falls back to serial CPU (scipy) otherwise.
        """
        if not self.subbands:
            return [], [], []
        n_bands = len(self.subbands)
        first_sub = next((s for s in self.subbands if isinstance(s, np.ndarray)), None)
        if first_sub is None:
            for i in range(n_bands):
                cand = self.get_subband(i)
                if len(cand) > 0:
                    first_sub = cand
                    break
        if first_sub is None:
            # Nothing to process from subbands; only valid when resume_state
            # already marked all bands complete.
            n_samples = 0
        else:
            n_samples = len(first_sub)

        # Resolve per-band hops
        if hop is None:
            hops = [self.band_hop(b, self.sr) for b in self.bands]
        elif isinstance(hop, int):
            hops = [hop] * n_bands
        else:
            hops = list(hop)

        mags_seed, phases_seed, completed = self._resolve_envelope_resume_state(
            n_bands, resume_state)

        # --- Try GPU path ---------------------------------------------------
        try:
            import torch
            if torch.cuda.is_available():
                return self._compute_envelopes_stft_gpu(
                    torch, n_samples, hops,
                    hilbert_progress=hilbert_progress,
                    band_result_cb=band_result_cb,
                    mags_out=mags_seed,
                    phases_out=phases_seed,
                    completed=completed,
                    drop_after_callback=drop_after_callback,
                    stream_chunk_dir=stream_chunk_dir,
                    stream_chunk_dtype=stream_chunk_dtype)
            print("  Hilbert/STFT path: CPU fallback (CUDA unavailable)",
                  flush=True)
        except ImportError:
            print("  Hilbert/STFT path: CPU fallback (torch unavailable)",
                  flush=True)

        # --- CPU fallback ----------------------------------------------------
        return self._compute_envelopes_cpu(
            n_samples, hops, hilbert_progress=hilbert_progress,
            band_result_cb=band_result_cb,
            mags_out=mags_seed,
            phases_out=phases_seed,
            completed=completed,
            drop_after_callback=drop_after_callback)

    @staticmethod
    def _resolve_envelope_resume_state(
        n_bands: int,
        resume_state: dict[str, Any] | None,
    ) -> tuple[list[np.ndarray | None], list[np.ndarray | None], list[bool]]:
        mags_out: list[np.ndarray | None] = [None] * n_bands
        phases_out: list[np.ndarray | None] = [None] * n_bands
        completed = [False] * n_bands
        if not resume_state:
            return mags_out, phases_out, completed

        state_completed = list(resume_state.get("completed", []))
        state_mags = list(resume_state.get("mags", []))
        state_phases = list(resume_state.get("phases", []))
        limit = min(n_bands, len(state_completed))
        for i in range(limit):
            if not bool(state_completed[i]):
                continue
            completed[i] = True
            if i >= len(state_mags) or i >= len(state_phases):
                continue
            mag = state_mags[i]
            phase = state_phases[i]
            if mag is None or phase is None:
                continue
            mags_out[i] = np.asarray(mag)
            phases_out[i] = np.asarray(phase)
        return mags_out, phases_out, completed

    @staticmethod
    def _finalize_envelope_results(
        mags_out: list[np.ndarray | None],
        phases_out: list[np.ndarray | None],
        hops: list[int],
    ) -> tuple[list[np.ndarray], list[np.ndarray], list[int]]:
        missing = [
            i for i, (m, p) in enumerate(zip(mags_out, phases_out))
            if m is None or p is None
        ]
        if missing:
            raise RuntimeError(
                "Hilbert envelope computation finished with missing bands: "
                + ", ".join(str(i + 1) for i in missing[:8])
                + (" ..." if len(missing) > 8 else "")
            )
        return (
            [np.asarray(m) for m in mags_out],  # all non-None after validation
            [np.asarray(p) for p in phases_out],  # all non-None after validation
            hops,
        )


    @staticmethod
    def _extract_frame_peaks(env: np.ndarray, phi: np.ndarray,
                             h: int, n_samples: int,
                             ) -> tuple[np.ndarray, np.ndarray]:
        """Vectorized per-hop frame peak extraction.

        For each hop-sized window finds the sample with peak magnitude and
        returns its magnitude and phase.  Replaces the O(n_samples) Python
        loop that was catastrophically slow at hop=1.
        """
        n_frames = int(math.ceil(n_samples / h))
        total = n_frames * h
        pad = total - n_samples
        real_dt = np.result_type(env.dtype, phi.dtype, np.float32)
        if pad > 0:
            # Pad env with -inf so padded positions never win argmax
            env_p = np.empty(total, dtype=real_dt)
            env_p[:n_samples] = env[:n_samples]
            env_p[n_samples:] = -np.inf
            phi_p = np.empty(total, dtype=real_dt)
            phi_p[:n_samples] = phi[:n_samples]
            phi_p[n_samples:] = 0.0
        else:
            env_p = np.asarray(env[:n_samples], dtype=real_dt)
            phi_p = np.asarray(phi[:n_samples], dtype=real_dt)
        frames_e = env_p.reshape(n_frames, h)
        frames_p = phi_p.reshape(n_frames, h)
        local_idx = np.argmax(frames_e, axis=1)          # (n_frames,)
        row = np.arange(n_frames)
        return frames_e[row, local_idx], frames_p[row, local_idx]

    @staticmethod
    def _extract_frame_peaks_quadrature(
        real: np.ndarray,
        imag: np.ndarray,
        h: int,
        n_samples: int,
    ) -> tuple[np.ndarray, np.ndarray]:
        """Peak-pick magnitude/phase from real + Hilbert-imag quadrature."""
        n_frames = int(math.ceil(n_samples / h))
        total = n_frames * h
        pad = total - n_samples
        real_dt = np.result_type(real.dtype, imag.dtype, np.float32)
        if pad > 0:
            real_p = np.zeros(total, dtype=real_dt)
            imag_p = np.zeros(total, dtype=real_dt)
            real_p[:n_samples] = real[:n_samples]
            imag_p[:n_samples] = imag[:n_samples]
        else:
            real_p = np.asarray(real[:n_samples], dtype=real_dt)
            imag_p = np.asarray(imag[:n_samples], dtype=real_dt)
        frames_r = real_p.reshape(n_frames, h)
        frames_i = imag_p.reshape(n_frames, h)
        power = frames_r * frames_r + frames_i * frames_i
        local_idx = np.argmax(power, axis=1)
        row = np.arange(n_frames)
        mag = np.asarray(np.sqrt(power[row, local_idx]), dtype=real_dt)
        phase = np.asarray(
            np.arctan2(frames_i[row, local_idx], frames_r[row, local_idx]),
            dtype=real_dt,
        )
        return mag, phase

    @staticmethod
    def _extract_frame_peaks_quadrature_torch(
        torch: Any,
        real_t: Any,
        imag_t: Any,
        h: int,
        n_samples: int,
    ) -> tuple[Any, Any]:
        n_frames = int(math.ceil(n_samples / h))
        total = n_frames * h
        pad = total - n_samples
        if pad > 0:
            real_p = torch.zeros(total, device=real_t.device, dtype=real_t.dtype)
            imag_p = torch.zeros(total, device=imag_t.device, dtype=imag_t.dtype)
            real_p[:n_samples] = real_t[:n_samples]
            imag_p[:n_samples] = imag_t[:n_samples]
        else:
            real_p = real_t[:n_samples]
            imag_p = imag_t[:n_samples]
        frames_r = real_p.reshape(n_frames, h)
        frames_i = imag_p.reshape(n_frames, h)
        power = frames_r.square() + frames_i.square()
        local_idx = torch.argmax(power, dim=1)
        row = torch.arange(n_frames, device=real_t.device)
        mag = torch.sqrt(power[row, local_idx])
        phase = torch.atan2(frames_i[row, local_idx], frames_r[row, local_idx])
        return mag, phase

    @staticmethod
    def _stft_n_fft(hop: int) -> int:
        """STFT FFT length: next power of 2 of 4×hop, minimum 32."""
        return max(32, 1 << math.ceil(math.log2(max(4 * hop, 4))))

    @staticmethod
    def _hilbert_rfft_filter(n_samples: int, cplx_dt: np.dtype) -> np.ndarray:
        n_rfft = n_samples // 2 + 1
        filt = np.zeros(n_rfft, dtype=cplx_dt)
        if n_rfft <= 1:
            return filt
        if n_samples % 2 == 0:
            filt[1:-1] = -1.0j
        else:
            filt[1:] = -1.0j
        return filt

    def _compute_envelope_band_cpu(
        self,
        sub: np.ndarray,
        h: int,
        n_samples: int,
        hilbert_filter: np.ndarray | None = None,
    ) -> tuple[np.ndarray, np.ndarray]:
        from scipy.fft import irfft, rfft

        real_dt = np.result_type(sub.dtype, np.float32)
        cplx_dt = np.complex128 if real_dt == np.float64 else np.complex64
        h_filter = (hilbert_filter if hilbert_filter is not None
                    else self._hilbert_rfft_filter(n_samples, cplx_dt))
        real_band = np.asarray(sub, dtype=real_dt)
        imag_band = np.asarray(
            irfft(rfft(real_band) * h_filter, n=n_samples),
            dtype=real_dt,
        )
        return self._extract_frame_peaks_quadrature(
            real_band, imag_band, h, n_samples)

    def _compute_envelope_band_stft_cpu(
        self,
        sub: np.ndarray,
        h: int,
        n_samples: int,
    ) -> tuple[np.ndarray, np.ndarray]:
        """CPU STFT envelope: Hann-windowed spectral-peak amplitude and phase.

        For each hop frame, applies a Hann window of length n_fft = 4×hop
        (next power of two), computes the rfft, and reads off the magnitude
        and phase of the dominant frequency bin.  This retains the true
        spectral phase of the band's carrier rather than the broadband
        instantaneous phase produced by the rfft/Hilbert approach.
        """
        from scipy.fft import rfft as _rfft

        real_dt = np.result_type(sub.dtype, np.float32)
        nfft = self._stft_n_fft(h)
        sub_arr = np.asarray(sub[:n_samples], dtype=real_dt)
        n_frames = math.ceil(n_samples / h)
        win = np.hanning(nfft).astype(real_dt)
        mags = np.empty(n_frames, dtype=real_dt)
        phases = np.empty(n_frames, dtype=real_dt)
        for fi in range(n_frames):
            s = fi * h
            seg = np.zeros(nfft, dtype=real_dt)
            e = min(s + nfft, n_samples)
            seg[:e - s] = sub_arr[s:e]
            seg *= win
            X = _rfft(seg)
            pwr = X.real * X.real + X.imag * X.imag
            pk = int(np.argmax(pwr))
            mags[fi] = float(math.sqrt(float(pwr[pk])))
            phases[fi] = float(math.atan2(float(X.imag[pk]), float(X.real[pk])))
        return mags, phases

    def _compute_envelopes_stft_gpu(
        self,
        torch: Any,
        n_samples: int,
        hops: list[int],
        hilbert_progress: Any = None,
        band_result_cb: Any = None,
        mags_out: list[np.ndarray | None] | None = None,
        phases_out: list[np.ndarray | None] | None = None,
        completed: list[bool] | None = None,
        drop_after_callback: bool = False,
        stream_chunk_dir: str | None = None,
        stream_chunk_dtype: np.dtype | None = None,
    ) -> tuple[list[np.ndarray], list[np.ndarray], list[int]]:
        """Two-stage OOM STFT-based per-band amplitude/phase envelope.

        Replaces the single-shot rfft/irfft Hilbert with a Hann-windowed
        STFT (n_fft = 4×hop, next power of two).  For every hop-aligned
        frame the dominant frequency bin carries both the instantaneous
        amplitude and the true spectral phase, giving richer phase
        information than the time-domain quadrature peak-pick.

        Memory management — two independent OOM stages:

          Stage 1 (time division): when an STFT kernel OOMs, *T_cur*
            (samples per GPU dispatch) is halved and the failed segment
            is retried immediately.  All results from already-completed
            time segments are kept in *frame_parts* (no work is lost).
            *T_seg* persists so future batches inherit the last working
            segment size.

          Stage 2 (band reduction): when *T_cur* cannot be halved
            further (already at *T_MIN* = 4 × max STFT window), halve
            *band_chunk* and reset *T_cur = n_samples* so stage 1 can
            re-discover the right size under the new (less crowded) VRAM
            conditions.  Bands that remain in the new (smaller) chunk
            keep their already-accumulated partial frames; deferred bands
            are cleared and will reprocess from scratch in a later batch.

        The innermost retry uses a *chunk_results* staging dict: partial
        results are only committed to *frame_parts* after the entire
        segment succeeds, guaranteeing no duplicate frames on retry.
        """
        n_bands = len(self.subbands)
        device = torch.device("cuda")

        first_sub = next((s for s in self.subbands if isinstance(s, np.ndarray)), None)
        if first_sub is None:
            for i in range(n_bands):
                cand = self.get_subband(i)
                if len(cand) > 0:
                    first_sub = cand
                    break
        if first_sub is None:
            raise RuntimeError("No subband data available for Hilbert processing.")
        native_dtype = np.result_type(first_sub)
        real_dt: np.dtype = np.float64 if native_dtype == np.float64 else np.float32  # type: ignore[assignment]
        torch_real = torch.float64 if real_dt == np.float64 else torch.float32

        if mags_out is None:
            mags_out = [None] * n_bands
        if phases_out is None:
            phases_out = [None] * n_bands
        if completed is None:
            completed = [False] * n_bands

        done_count = sum(1 for f in completed if f)
        if hilbert_progress and done_count:
            hilbert_progress(done_count, n_bands)

        pending = [i for i in range(n_bands) if not completed[i]]
        if not pending:
            if drop_after_callback:
                return [], [], hops
            return self._finalize_envelope_results(mags_out, phases_out, hops)

        print(f"  Hilbert/STFT path: CUDA GPU ({len(pending)} pending bands)",
              flush=True)

        n_ffts = [self._stft_n_fft(hops[i]) for i in range(n_bands)]

        # T_MIN: smallest useful time segment — at least 4 full STFT windows
        # for every pending band so each dispatch yields ≥ 4 frames.
        T_MIN = max(512, max(n_ffts[i] * 4 for i in pending))
        T_MIN = min(T_MIN, n_samples)

        # Deterministic efficiency grid: choose initial (band_chunk, T_seg)
        # by maximizing throughput score under detected GPU + host RAM caps.
        real_item = np.dtype(real_dt).itemsize
        cplx_item = np.dtype(np.complex128 if real_dt == np.float64 else np.complex64).itemsize
        # GPU budget is derived only from live free VRAM (no fixed MB constants,
        # no environment override for GPU memory amount).
        gpu_budget_bytes: int | None = None
        try:
            free_b, _total_b = torch.cuda.mem_get_info(device=device)
            gpu_budget_bytes = int(float(free_b) * 0.70)
        except Exception:
            gpu_budget_bytes = None

        # Build candidate segment lengths by repeated halving (deterministic).
        seg_grid: list[int] = []
        t_probe = n_samples
        while True:
            if t_probe not in seg_grid:
                seg_grid.append(t_probe)
            if t_probe <= T_MIN:
                break
            t_probe = max(T_MIN, t_probe // 2)

        # Per-band frame counts / host result bytes (mag+phase).
        frames_total = {bi: max(1, math.ceil(n_samples / hops[bi])) for bi in pending}
        host_bytes_per_band = {bi: frames_total[bi] * 2 * real_item for bi in pending}

        def _gpu_bytes_for_band(bi: int, t_seg: int) -> int:
            nfft = n_ffts[bi]
            h = hops[bi]
            n_frames_seg = max(1, math.ceil(t_seg / max(h, 1)))
            n_bins = nfft // 2 + 1
            preload = (t_seg + nfft) * real_item
            stft_core = n_bins * n_frames_seg * cplx_item
            # Conservative multiplier for intermediate tensors / workspaces.
            return int(preload + stft_core * 4)

        # Sort pending bands by cost descending for safe worst-case chunk estimates.
        pending_host_sorted = sorted(
            pending, key=lambda bi: host_bytes_per_band[bi], reverse=True
        )

        # Start at maximum concurrency as requested, then reduce only on OOM
        # using the alternating diagonal walk (time, bands, time, ...).
        T_seg: int = n_samples
        band_chunk: int = len(pending)
        _gpu_src = ("live-free-vram" if gpu_budget_bytes is not None
                    else "unknown-vram (OOM fallback)")
        print(
            f"  Hilbert grid: band_chunk={band_chunk}, T_seg={T_seg} "
            f"(gpu={_gpu_src})",
            flush=True,
        )

        pend_pos = 0
        # Diagonal OOM walk: alternate reducing time and band count.
        trade_reduce_time_next = True

        while pend_pos < len(pending):
            chunk_end = min(pend_pos + band_chunk, len(pending))
            chunk = pending[pend_pos:chunk_end]
            # Disk-backed finalized Hilbert buffers (written per time chunk).
            chunk_outputs: dict[int, tuple[np.memmap, np.memmap, str, str]] = {}

            chunk_dt = np.dtype(stream_chunk_dtype if stream_chunk_dtype is not None else real_dt)

            def _init_chunk_outputs(_chunk: list[int]) -> dict[int, tuple[np.memmap, np.memmap, str, str]]:
                out: dict[int, tuple[np.memmap, np.memmap, str, str]] = {}
                for _bi in _chunk:
                    _n_frames_b = math.ceil(n_samples / hops[_bi])
                    if stream_chunk_dir:
                        _mag_path = self._envelope_stream_mag_path(stream_chunk_dir, _bi)
                        _phi_path = self._envelope_stream_phase_path(stream_chunk_dir, _bi)
                        os.makedirs(os.path.dirname(_mag_path), exist_ok=True)
                    else:
                        _mag_path = os.path.join(
                            os.getcwd(),
                            f".tmp_fb_hilbert_band_{_bi:05d}_mag.npy",
                        )
                        _phi_path = os.path.join(
                            os.getcwd(),
                            f".tmp_fb_hilbert_band_{_bi:05d}_phase.npy",
                        )
                    _mag_mode = "r+" if os.path.isfile(_mag_path) else "w+"
                    _phi_mode = "r+" if os.path.isfile(_phi_path) else "w+"
                    _mag_mm = np.lib.format.open_memmap(
                        _mag_path, mode=_mag_mode, dtype=chunk_dt, shape=(_n_frames_b,))
                    _phi_mm = np.lib.format.open_memmap(
                        _phi_path, mode=_phi_mode, dtype=chunk_dt, shape=(_n_frames_b,))
                    out[_bi] = (_mag_mm, _phi_mm, _mag_path, _phi_path)
                return out

            def _cleanup_chunk_outputs(_out: dict[int, tuple[np.memmap, np.memmap, str, str]]) -> None:
                for _mag_mm, _phi_mm, _mag_path, _phi_path in _out.values():
                    try:
                        _mag_mm.flush()
                    except Exception:
                        pass
                    try:
                        _phi_mm.flush()
                    except Exception:
                        pass
                    try:
                        del _mag_mm
                    except Exception:
                        pass
                    try:
                        del _phi_mm
                    except Exception:
                        pass
                    if not stream_chunk_dir:
                        for _p in (_mag_path, _phi_path):
                            try:
                                if os.path.isfile(_p):
                                    os.remove(_p)
                            except OSError:
                                pass

            chunk_outputs: dict[int, tuple[np.memmap, np.memmap, str, str]] = {}

            T_cur: int = T_seg   # local time segment; may shrink during loop
            t = 0
            need_outer_restart = False

            while t < n_samples:
                _backpressure_wait(label=f"stft_gpu t={t}")
                t_end = min(t + T_cur, n_samples)

                # Per-band frame range for this time segment
                # Frame f belongs to [t, t_end) when f*h ∈ [t, t_end).
                # With center=False STFT and sig starting at f_lo*h:
                #   local frame k → global frame f_lo + k
                seg_info: list[tuple[int, int, int]] = []  # (f_lo, f_hi, needed_len)
                for bi in chunk:
                    h = hops[bi]
                    nfft = n_ffts[bi]
                    n_frames_total = math.ceil(n_samples / h)
                    f_lo = (math.ceil(t / h) if t > 0 else 0)
                    f_hi = min(math.ceil(t_end / h), n_frames_total)
                    nsf = f_hi - f_lo
                    needed = (nfft + (nsf - 1) * h) if nsf > 0 else 0
                    seg_info.append((f_lo, f_hi, needed))

                # chunk_results: staged results — committed to chunk_outputs
                # only after this segment succeeds.
                chunk_results: dict[int, tuple[int, int, np.ndarray, np.ndarray]] = {}
                stacked_segs: list[Any] = []
                oom_err = False

                def _oom_cooldown() -> None:
                    # Slow down rapid OOM retry loops so CUDA alloc state can settle.
                    try:
                        torch.cuda.synchronize()
                    except Exception:
                        pass
                    gc.collect()
                    try:
                        torch.cuda.empty_cache()
                    except Exception:
                        pass
                    time.sleep(3.0)

                try:
                    # 1. Preload every band's time segment to GPU
                    for j, bi in enumerate(chunk):
                        f_lo, f_hi, needed = seg_info[j]
                        nsf = f_hi - f_lo
                        if nsf <= 0:
                            stacked_segs.append(None)
                            continue
                        sig_start = f_lo * hops[bi]
                        seg_np = np.zeros(needed, dtype=real_dt)
                        avail = max(0, min(needed, n_samples - sig_start))
                        if avail > 0:
                            src = self.subbands[bi]
                            if src is None:
                                src = self.get_subband(bi)
                            seg_np[:avail] = np.asarray(
                                src[sig_start: sig_start + avail],
                                dtype=real_dt,
                            )
                        stacked_segs.append(torch.from_numpy(seg_np).to(device))

                    torch.cuda.empty_cache()

                    # 2. STFT → dominant-bin mag + spectral phase per band.
                    # Group by (hop, nfft, n_frames) so each group runs in
                    # one batched torch.stft call instead of serial per-band calls.
                    grouped: dict[tuple[int, int, int], list[tuple[int, int]]] = {}
                    for j, bi in enumerate(chunk):
                        f_lo, f_hi, _needed = seg_info[j]
                        nsf = f_hi - f_lo
                        if nsf <= 0 or stacked_segs[j] is None:
                            continue
                        key = (hops[bi], n_ffts[bi], nsf)
                        grouped.setdefault(key, []).append((j, bi))

                    for (h, nfft, nsf), members in grouped.items():
                        win = torch.hann_window(nfft, device=device, dtype=torch_real)
                        batch = torch.stack([stacked_segs[j] for j, _bi in members], dim=0)
                        Zxx = torch.stft(
                            batch,
                            n_fft=nfft,
                            hop_length=h,
                            win_length=nfft,
                            window=win,
                            center=False,
                            return_complex=True,
                        )  # (B, n_bins, n_actual_frames)
                        del win, batch

                        Zxx = Zxx[:, :, :nsf]
                        power = Zxx.real.square() + Zxx.imag.square()
                        peak_bins = torch.argmax(power, dim=1)  # (B, nsf)
                        z_peak = torch.gather(
                            Zxx, 1, peak_bins.unsqueeze(1)).squeeze(1)  # (B, nsf)
                        del Zxx, power, peak_bins

                        mag_np = (z_peak.abs()
                                  .to(dtype=torch_real)
                                  .cpu().numpy()
                                  .astype(real_dt, copy=False))
                        phi_np = (torch.angle(z_peak)
                                  .to(dtype=torch_real)
                                  .cpu().numpy()
                                  .astype(real_dt, copy=False))
                        del z_peak
                        torch.cuda.empty_cache()

                        for row_idx, (j, bi) in enumerate(members):
                            f_lo, f_hi, _needed = seg_info[j]
                            chunk_results[bi] = (
                                f_lo,
                                f_hi,
                                mag_np[row_idx],
                                phi_np[row_idx],
                            )

                except (torch.cuda.OutOfMemoryError, RuntimeError, MemoryError) as _e:
                    if isinstance(_e, RuntimeError) and not _is_cuda_oom(_e):
                        raise
                    oom_err = True
                finally:
                    for st in stacked_segs:
                        if st is not None:
                            del st
                    stacked_segs.clear()
                    gc.collect()
                    torch.cuda.empty_cache()

                if oom_err:
                    _oom_cooldown()
                    # Explicitly unload subbands touched by the failed attempt
                    # so the retry starts from a cleaner RAM state.
                    for _bi in chunk:
                        if _bi < len(completed) and not completed[_bi]:
                            self.subbands[_bi] = None
                    gc.collect()
                    reduced = False
                    for _ in range(2):
                        reduce_time = trade_reduce_time_next
                        trade_reduce_time_next = not trade_reduce_time_next
                        if reduce_time:
                            new_T = T_cur // 2
                            if new_T >= T_MIN:
                                T_cur = new_T
                                T_seg = T_cur
                                print(
                                    f"\n  STFT OOM (time) — T_seg → {T_cur} samples",
                                    flush=True,
                                )
                                reduced = True
                                break
                        else:
                            if band_chunk > 1:
                                new_bc = max(1, band_chunk // 2)
                                new_chunk = pending[pend_pos: pend_pos + new_bc]
                                band_chunk = new_bc
                                chunk = new_chunk
                                chunk_end = pend_pos + new_bc
                                # Preserve already-written outputs for retained bands.
                                keep = set(chunk)
                                for _bi in list(chunk_outputs.keys()):
                                    if _bi not in keep:
                                        _m, _p, _m_path, _p_path = chunk_outputs.pop(_bi)
                                        try:
                                            _m.flush()
                                            _p.flush()
                                        except Exception:
                                            pass
                                        try:
                                            del _m
                                            del _p
                                        except Exception:
                                            pass
                                for _bi in chunk:
                                    if _bi not in chunk_outputs:
                                        # Lazily allocate output buffer only when needed.
                                        pass
                                # Keep current time segmentation; continue diagonal
                                # walk by alternating next OOM action.
                                seg_info = seg_info[:len(chunk)]
                                print(
                                    f"\n  STFT OOM (bands) — band_chunk → {band_chunk}",
                                    flush=True,
                                )
                                reduced = True
                                break
                    if reduced:
                        continue   # same t with reduced shape

                    # Single band at minimum time → CPU fallback
                    bi = chunk[0]
                    print(f"\n  STFT OOM — band {bi + 1}/{n_bands} → CPU",
                          flush=True)
                    src = self.subbands[bi]
                    if src is None:
                        src = self.get_subband(bi)
                    mags_out[bi], phases_out[bi] = (
                        self._compute_envelope_band_stft_cpu(
                            np.asarray(src, dtype=real_dt),
                            hops[bi], n_samples))
                    completed[bi] = True
                    if band_result_cb:
                        band_result_cb(bi, mags_out[bi], phases_out[bi], hops[bi])
                    # Band is finalized; release source subband immediately.
                    if bi < len(self.subbands):
                        self.subbands[bi] = None
                    done_count += 1
                    if hilbert_progress:
                        hilbert_progress(done_count, n_bands)
                    pend_pos += 1
                    need_outer_restart = True
                    break  # exit time loop; outer while re-derives chunk

                # Success: commit this segment's results directly to outputs
                for bi, (f_lo, f_hi, mag_np, phi_np) in chunk_results.items():
                    if bi not in chunk_outputs:
                        chunk_outputs.update(_init_chunk_outputs([bi]))
                    out_mag, out_phi, _mag_path, _phi_path = chunk_outputs[bi]
                    out_mag[f_lo:f_hi] = mag_np[:max(0, f_hi - f_lo)]
                    out_phi[f_lo:f_hi] = phi_np[:max(0, f_hi - f_lo)]
                    out_mag.flush()
                    out_phi.flush()

                t = t_end  # advance to next time segment
                if t < n_samples:
                    print(
                        f"\r  STFT segments: {t_end}/{n_samples} samples "
                        f"(bands {chunk[0] + 1}-{chunk[-1] + 1}, T={T_cur})",
                        end="",
                        flush=True,
                    )
                else:
                    print(
                        f"\r  STFT segments: {n_samples}/{n_samples} samples "
                        f"(bands {chunk[0] + 1}-{chunk[-1] + 1}, T={T_cur})",
                        end="",
                        flush=True,
                    )

            if need_outer_restart:
                _cleanup_chunk_outputs(chunk_outputs)
                continue  # outer while: re-derive chunk from updated pend_pos/band_chunk

            print()
            # All time segments done for this chunk → finalize and checkpoint
            for bi in chunk:
                if mags_out[bi] is not None:
                    continue  # already set by CPU fallback (shouldn't reach here)
                if bi not in chunk_outputs:
                    # No successful chunk writes for this band in this pass;
                    # materialize an empty buffer so downstream callbacks
                    # receive a consistent array.
                    chunk_outputs.update(_init_chunk_outputs([bi]))
                out_mag, out_phi, _mag_path, _phi_path = chunk_outputs[bi]
                mags_out[bi] = np.asarray(out_mag)
                phases_out[bi] = np.asarray(out_phi)
                completed[bi] = True
                if band_result_cb:
                    band_result_cb(bi, mags_out[bi], phases_out[bi], hops[bi])
                if drop_after_callback:
                    mags_out[bi] = None
                    phases_out[bi] = None
                # Band is finalized; release source subband immediately.
                if bi < len(self.subbands):
                    self.subbands[bi] = None
                done_count += 1

            _cleanup_chunk_outputs(chunk_outputs)

            gc.collect()
            torch.cuda.empty_cache()
            if hilbert_progress:
                hilbert_progress(done_count, n_bands)
            print(f"  STFT envelopes: {done_count}/{n_bands} bands on GPU",
                  flush=True)

            pend_pos = chunk_end

        if drop_after_callback:
            return [], [], hops
        return self._finalize_envelope_results(mags_out, phases_out, hops)

    def _compute_envelopes_cpu(self, n_samples: int,
                               hops: list[int],
                               hilbert_progress: Any = None,
                               band_result_cb: Any = None,
                               mags_out: list[np.ndarray | None] | None = None,
                               phases_out: list[np.ndarray | None] | None = None,
                               completed: list[bool] | None = None,
                               drop_after_callback: bool = False,
                               ) -> tuple[list[np.ndarray], list[np.ndarray],
                                          list[int]]:
        """Serial CPU Hilbert envelope computation (RFFT fallback)."""

        n_bands = len(self.subbands)
        if mags_out is None:
            mags_out = [None] * n_bands
        if phases_out is None:
            phases_out = [None] * n_bands
        if completed is None:
            completed = [False] * n_bands

        first_sub = next((s for s in self.subbands if isinstance(s, np.ndarray)), None)
        if first_sub is None:
            for i in range(n_bands):
                cand = self.get_subband(i)
                if len(cand) > 0:
                    first_sub = cand
                    break
        if first_sub is None:
            raise RuntimeError("No subband data available for Hilbert processing.")
        real_dt = np.result_type(first_sub.dtype, np.float32)
        cplx_dt = np.complex128 if real_dt == np.float64 else np.complex64
        hilbert_filter = self._hilbert_rfft_filter(n_samples, cplx_dt)
        done_count = sum(1 for flag in completed if flag)
        if hilbert_progress and done_count:
            hilbert_progress(done_count, n_bands)

        for i, sub in enumerate(self.subbands):
            if completed[i]:
                continue
            if sub is None:
                sub = self.get_subband(i)
            _backpressure_wait(label=f"envelope_cpu band_{i}")
            mags_out[i], phases_out[i] = self._compute_envelope_band_cpu(
                np.asarray(sub, dtype=real_dt), hops[i], n_samples, hilbert_filter)
            completed[i] = True
            if band_result_cb:
                band_result_cb(i, mags_out[i], phases_out[i], hops[i])
            if drop_after_callback:
                mags_out[i] = None
                phases_out[i] = None
            # Band is finalized; release source subband immediately.
            self.subbands[i] = None
            done_count += 1
            if hilbert_progress and (done_count % 10 == 0 or done_count == n_bands):
                hilbert_progress(done_count, n_bands)
        if drop_after_callback:
            return [], [], hops
        return self._finalize_envelope_results(mags_out, phases_out, hops)

    # ------------------------------------------------------------------
    # CQT ↔ filterbank band mapping
    # ------------------------------------------------------------------
    @staticmethod
    def bins_for_band(band: "BandDef",
                      cqt_freqs: np.ndarray) -> np.ndarray:
        """Return indices of CQT bins whose center frequencies fall within
        *band*'s [fmin, fmax) range.

        Each CQT bin is a bandpass filter centered at ``cqt_freqs[k]`` with
        bandwidth ``freq[k] / Q``.  A bin belongs to a filterbank band when
        its center frequency sits inside that band.  This gives a 1:1
        mapping between the two representations.
        """
        mask = np.ones(len(cqt_freqs), dtype=bool)
        if band.fmin > 0:
            mask &= cqt_freqs >= band.fmin
        if band.fmax < cqt_freqs[-1] * 1.01:  # allow tiny overshoot at top
            mask &= cqt_freqs < band.fmax
        return np.where(mask)[0]

    @staticmethod
    def band_map(bands: list["BandDef"],
                 cqt_freqs: np.ndarray) -> list[np.ndarray]:
        """Build a complete mapping: for each band, the array of CQT bin
        indices that belong to it.

        ``sum(len(m) for m in result)`` will equal ``len(cqt_freqs)`` when
        the bands tile the full frequency axis without gaps.
        """
        return [FilterBankDecomposition.bins_for_band(b, cqt_freqs)
                for b in bands]

    @staticmethod
    def band_hop(band: "BandDef", sr: int) -> int:
        """Nyquist-limited hop for one band based on its bandwidth."""
        if sr <= 0:
            return 1
        nyq = sr / 2.0
        bw = min(band.fmax, nyq) - max(band.fmin, 0.0)
        if bw <= 0:
            return 1
        return max(1, int(sr / (2.0 * bw)))

    def _filter_one_band(self, signal: np.ndarray, band: "BandDef",
                         nyq: float) -> np.ndarray:
        """Filter *signal* for a single band and return the subband array."""
        from filter_engine import apply_bandpass, FIR, IIR
        real_dt = np.result_type(signal.dtype, np.float32)

        if not band.enabled:
            return np.zeros_like(signal)
        flo, fhi = band.fmin, band.fmax
        if flo <= 0.0 and fhi >= nyq:
            return signal.copy()

        mode = IIR if self.filter_mode == "iir" else FIR
        order = int(self.filter_type.split()[-1])
        flo_arg = flo if flo > 0 else None
        fhi_arg = fhi if fhi < nyq else None
        return np.asarray(
            apply_bandpass(signal, self.sr, flo_arg, fhi_arg,
                           filter_mode=mode, order=order),
            dtype=real_dt,
        )

    def _lp_exponent(self) -> int:
        """Exponent N for zero-phase LP shape: lp(f,fc) = 1/(1+(f/fc)^N).

        LR order maps directly (LR4 → N=4).  Butterworth order k maps to
        N=2k so that the zero-phase response matches the squared Butterworth
        magnitude, which is the LR-equivalent profile.
        """
        if self.filter_type.startswith("Linkwitz-Riley"):
            return int(self.filter_type.split()[-1])
        if self.filter_type.startswith("Butterworth"):
            return 2 * int(self.filter_type.split()[-1])
        return 4

    def _filter_bands_gpu(
        self,
        signal: np.ndarray,
        bands: list["BandDef"],
        nyq: float,
        n_samples: int,
        n_bands: int,
        fb_dir: str,
        sr: int,
        all_subs: list,
        t0: float,
        progress_cb: Any,
    ) -> None:
        """GPU FFT zero-phase perfectly-reconstructing band filtering.

        Uses a cascade LP-difference partition:

            H_0(f)     = lp(f, xo[0])
            H_i(f)     = lp(f, xo[i]) - lp(f, xo[i-1])   for 1 <= i < n-1
            H_{n-1}(f) = 1 - lp(f, xo[n-2])

        where  lp(f, fc) = 1 / (1 + (f/fc)^order)  (standard LR formula,
        real-valued → zero-phase).  HP = 1 - LP ensures Σ H_i(f) = 1 at
        every frequency, guaranteeing perfect reconstruction.

        OOM strategy (two dimensions):
          1. Band-batch halving: try all n_bands together; halve on OOM.
          2. Time-chunk halving (overlap-save): if even 1 band cannot fit
             with the full-length FFT, split the signal into time blocks
             and process with proper overlap to avoid wrap artefacts.
             Block count doubles every halving so all VRAM is used.
        Neither dimension falls back to CPU — raises on exhaustion.
        """
        import torch

        device = torch.device("cuda")
        order = self._lp_exponent()
        real_dt = np.result_type(signal.dtype, np.float32)
        torch_real = torch.float64 if real_dt == np.float64 else torch.float32
        itemsize = np.dtype(real_dt).itemsize

        # Crossover frequencies: fmax of every band except the last.
        xo: list[float] = [
            max(1e-6, min(float(bands[i].fmax), nyq * (1.0 - 1e-9)))
            for i in range(n_bands - 1)
        ]

        est_subband_bytes = int(n_bands) * int(n_samples) * int(itemsize)
        # Automatic RAM policy (no env-based caps/overrides): go disk-backed
        # when projected subband footprint is a substantial fraction of
        # currently available physical RAM.
        avail_ram_bytes = 0
        try:
            import psutil  # type: ignore
            avail_ram_bytes = int(psutil.virtual_memory().available)
        except Exception:
            try:
                import ctypes
                class _MEMSTAT(ctypes.Structure):
                    _fields_ = [
                        ("dwLength", ctypes.c_uint32),
                        ("dwMemoryLoad", ctypes.c_uint32),
                        ("ullTotalPhys", ctypes.c_uint64),
                        ("ullAvailPhys", ctypes.c_uint64),
                        ("ullTotalPageFile", ctypes.c_uint64),
                        ("ullAvailPageFile", ctypes.c_uint64),
                        ("ullTotalVirtual", ctypes.c_uint64),
                        ("ullAvailVirtual", ctypes.c_uint64),
                        ("ullAvailExtendedVirtual", ctypes.c_uint64),
                    ]
                ms = _MEMSTAT()
                ms.dwLength = ctypes.sizeof(_MEMSTAT)
                if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(ms)):  # type: ignore[attr-defined]
                    avail_ram_bytes = int(ms.ullAvailPhys)
            except Exception:
                avail_ram_bytes = 0
        if avail_ram_bytes <= 0:
            # If RAM availability is unknown, prefer disk-backed safety.
            disk_backed = True
        else:
            # Switch to disk-backed before projected buffers can pressure RAM.
            disk_backed = est_subband_bytes > int(0.40 * avail_ram_bytes)
        # Alternate OOM reductions diagonally: time, bands, time, bands...
        oom_reduce_time_next = True
        if disk_backed:
            os.makedirs(fb_dir, exist_ok=True)
            print(
                "  Filterbank buffer mode: disk-backed "
                f"(~{est_subband_bytes / (1024**3):.2f} GiB projected)",
                flush=True,
            )
        else:
            print(
                "  Filterbank buffer mode: RAM-backed "
                f"(~{est_subband_bytes / (1024**3):.2f} GiB projected)",
                flush=True,
            )
        # --- Estimate overlap needed for time-chunk mode ------------------
        # IR decay of lp(f,fc)=1/(1+(f/fc)^N) ≈ exp(-2π·fc·t / N).
        # Use 5 time-constants → M ≈ 5·sr / (2π·fc_min / N).
        fc_min = float(xo[0]) if xo else 1.0
        overlap_M = max(1024, int(math.ceil(5.0 * order * sr / (2.0 * math.pi * fc_min))))

        # ---- helpers -------------------------------------------------------

        def _lp_vec(fc: float, freqs_t: "torch.Tensor") -> "torch.Tensor":
            """Real LP response on *device* for crossover *fc*."""
            r = (freqs_t / fc).pow(order)
            return 1.0 / (1.0 + r)

        def _build_H_batch(
            band_slice: range,
            freqs_t: "torch.Tensor",
            prev_lp_t: "torch.Tensor",
        ) -> "tuple[torch.Tensor, torch.Tensor]":
            """Return (H_batch, final_lp) for the given band slice.

            H_batch : (len(band_slice), n_rfft) float32 on device
            final_lp: (n_rfft,) float32 — LP at upper edge of last band
            """
            bis = list(band_slice)
            if not bis:
                return torch.empty((0, freqs_t.shape[0]), device=device, dtype=torch_real), prev_lp_t

            non_last = [bi for bi in bis if bi < n_bands - 1]
            if non_last:
                fc_t = torch.as_tensor(
                    [xo[bi] for bi in non_last], device=device, dtype=torch_real)
                curr_lps = 1.0 / (1.0 + (freqs_t.unsqueeze(0) / fc_t.unsqueeze(1)).pow(order))
                prev_stack = torch.empty_like(curr_lps)
                prev_stack[0] = prev_lp_t
                if curr_lps.shape[0] > 1:
                    prev_stack[1:] = curr_lps[:-1]
                diff_lps = curr_lps - prev_stack
                final_lp = curr_lps[-1]
            else:
                curr_lps = torch.empty((0, freqs_t.shape[0]), device=device, dtype=torch_real)
                diff_lps = curr_lps
                final_lp = prev_lp_t

            diff_map: dict[int, torch.Tensor] = {
                bi: diff_lps[i] for i, bi in enumerate(non_last)
            }
            prev_map: dict[int, torch.Tensor] = {}
            for i, bi in enumerate(non_last):
                prev_map[bi] = prev_stack[i]

            H_list: list["torch.Tensor"] = []
            for bi in bis:
                band = bands[bi]
                if not band.enabled:
                    H_list.append(torch.zeros_like(freqs_t))
                elif bi == n_bands - 1:
                    if non_last:
                        prev_for_last = final_lp
                    else:
                        prev_for_last = prev_lp_t
                    H_list.append(1.0 - prev_for_last)
                else:
                    H_list.append(diff_map[bi])
            return torch.stack(H_list), final_lp   # (B, n_rfft), (n_rfft,)

        def _alloc_sub_buffer(bi: int) -> np.ndarray:
            cur = all_subs[bi]
            if cur is not None:
                return cur
            # Backpressure: wait for RAM headroom before any new allocation.
            _backpressure_wait(label=f"band_{bi}")
            if disk_backed:
                # Write directly to permanent band shard path.
                path = os.path.join(fb_dir, f"band_{bi:02d}.npy")
                mm = np.lib.format.open_memmap(
                    path, mode="w+", dtype=real_dt, shape=(n_samples,))
                all_subs[bi] = mm
                return mm
            arr = np.zeros(n_samples, dtype=real_dt)
            all_subs[bi] = arr
            return arr

        # ================================================================
        # FULL-SIGNAL MODE: rfft(whole signal) kept on GPU; band-batch
        # halving handles VRAM pressure.
        # ================================================================
        def _run_full_signal(
            S: "torch.Tensor",        # (n_rfft,) complex64 on device
            freqs_t: "torch.Tensor",  # (n_rfft,) float32 on device
            n_fft: int,
        ) -> bool:
            """Process all bands using full-signal FFT.  Returns True on
            success.  Cleans up *all* temporaries on partial OOM and
            re-raises only when a single-band chunk still cannot fit."""
            nonlocal oom_reduce_time_next
            done = 0
            batch_sz = n_bands
            prev_lp = torch.zeros(S.shape[0], device=device, dtype=torch_real)

            while done < n_bands:
                chunk_sz = min(batch_sz, n_bands - done)

                # ---- OOM retry (band dimension) --------------------------
                H_batch = Y_batch = out_batch = final_lp = None
                while True:
                    try:
                        H_batch, final_lp = _build_H_batch(
                            range(done, done + chunk_sz), freqs_t, prev_lp)
                        Y_batch = S.unsqueeze(0) * H_batch   # (B, n_rfft) cplx
                        del H_batch; H_batch = None
                        out_batch = torch.fft.irfft(Y_batch, n=n_fft)[..., :n_samples]
                        del Y_batch; Y_batch = None
                        torch.cuda.empty_cache()
                        break
                    except (torch.cuda.OutOfMemoryError, RuntimeError) as _e:
                        if isinstance(_e, RuntimeError) and not _is_cuda_oom(_e):
                            raise
                        if H_batch  is not None: del H_batch;  H_batch  = None
                        if Y_batch  is not None: del Y_batch;  Y_batch  = None
                        if out_batch is not None: del out_batch; out_batch = None
                        if final_lp is not None: del final_lp; final_lp = None
                        torch.cuda.empty_cache()
                        if chunk_sz <= 1:
                            return False   # escalate to time-chunk mode
                        reduce_time = oom_reduce_time_next
                        oom_reduce_time_next = not oom_reduce_time_next
                        if reduce_time:
                            print(
                                "\n  GPU OOM (full-signal) — switching to "
                                "time-chunk mode",
                                flush=True,
                            )
                            return False
                        chunk_sz //= 2
                        batch_sz = chunk_sz
                        print(f"\n  GPU OOM (band-batch) — reducing to "
                              f"{chunk_sz} bands/chunk", flush=True)

                # Download and write band shard chunks.
                batch_np = out_batch.cpu().numpy()
                del out_batch
                _write_shard_batch(done, chunk_sz, batch_np)

                prev_lp = final_lp
                done += chunk_sz
                _print_progress(done, t0, progress_cb)

            return True

        # ================================================================
        # TIME-CHUNK (OVERLAP-SAVE) MODE: signal is split into blocks;
        # each block processed for all B bands.  Both the block size and
        # the band batch size halve independently on OOM.
        # ================================================================
        def _run_chunked(freqs_gen_fn: "Any") -> None:
            """Process in time blocks using overlap-save.

            freqs_gen_fn(n_rfft) → (freqs_t, H_precomputed?) — not used here;
            H is rebuilt per block since n_rfft changes with block size.
            """
            nonlocal oom_reduce_time_next
            # Start: one block covers the whole signal (halved on OOM).
            C = 1 << math.ceil(math.log2(max(n_samples, 2)))

            done = 0
            band_batch_sz = n_bands

            # LP cursor at the lower boundary of each band batch: computed
            # once per band-batch start and reused across block retries.
            # We store it as a numpy array so it survives tensor deletions.
            cursor_np: np.ndarray | None = None  # None → band 0, prev_lp = 0

            while done < n_bands:
                # bslice is always derived from the current band_batch_sz.
                bslice = range(done, min(done + band_batch_sz, n_bands))
                chunk_sz = len(bslice)

                # ---- overlap-save over time blocks ----------------------
                # Retry loop halves C on OOM; halves band_batch_sz and
                # restarts the outer while if the band slice must shrink.
                need_band_restart = False

                while True:
                    n_block  = 1 << math.ceil(math.log2(max(C + overlap_M, 2)))
                    n_rfft_b = n_block // 2 + 1

                    # Build freq axis and restore LP cursor for this n_rfft
                    freqs_b = torch.linspace(
                        0, nyq, n_rfft_b, device=device, dtype=torch_real)
                    if cursor_np is None:
                        prev_lp_b = torch.zeros(
                            n_rfft_b, device=device, dtype=torch_real)
                    else:
                        prev_lp_b = torch.from_numpy(cursor_np).to(device)
                        if prev_lp_b.shape[0] != n_rfft_b:
                            # n_rfft changed (C halved): recompute cursor
                            # from scratch by advancing through all prior xo.
                            prev_lp_b = torch.zeros(
                                n_rfft_b, device=device, dtype=torch_real)
                            for xi in range(done):
                                if xi < n_bands - 1:
                                    prev_lp_b = _lp_vec(xo[xi], freqs_b)

                    # Build H for this band slice
                    H_b = final_lp_b = None
                    try:
                        H_b, final_lp_b = _build_H_batch(
                            bslice, freqs_b, prev_lp_b)
                        del freqs_b, prev_lp_b
                        torch.cuda.empty_cache()
                    except (torch.cuda.OutOfMemoryError, RuntimeError) as _e:
                        if isinstance(_e, RuntimeError) and not _is_cuda_oom(_e):
                            raise
                        if H_b        is not None: del H_b
                        if final_lp_b is not None: del final_lp_b
                        del freqs_b, prev_lp_b
                        torch.cuda.empty_cache()
                        reduced = False
                        for _ in range(2):
                            reduce_time = oom_reduce_time_next
                            oom_reduce_time_next = not oom_reduce_time_next
                            if reduce_time and C > overlap_M:
                                C = max(overlap_M, C // 2)
                                print(f"\n  GPU OOM (chunk H-build) — C halved "
                                      f"→ {C}", flush=True)
                                reduced = True
                                break
                            if (not reduce_time) and chunk_sz > 1:
                                band_batch_sz = max(1, band_batch_sz // 2)
                                print(f"\n  GPU OOM (chunk H-build) — band batch "
                                      f"→ {band_batch_sz}", flush=True)
                                need_band_restart = True
                                reduced = True
                                break
                        if reduced:
                            if need_band_restart:
                                break
                            continue
                        if C <= overlap_M:
                            raise RuntimeError(
                                f"CUDA OOM: cannot build H for 1 band at "
                                f"block size {n_block} (n_rfft={n_rfft_b}). "
                                f"Insufficient VRAM.")
                        C = max(overlap_M, C // 2)
                        print(f"\n  GPU OOM (chunk H-build) — C halved "
                              f"→ {C}", flush=True)
                        continue   # retry with smaller block

                    # Process every time block with this H
                    n_time_blocks = math.ceil(n_samples / C)
                    block_oom = False
                    for blk in range(n_time_blocks):
                        out_start = blk * C
                        out_end   = min(out_start + C, n_samples)
                        if out_start >= n_samples:
                            break
                        valid_len = out_end - out_start

                        in_start  = out_start - overlap_M
                        seg = np.zeros(n_block, dtype=real_dt)
                        s0, s1 = max(0, in_start), min(n_samples, in_start + n_block)
                        seg[s0 - in_start: s0 - in_start + (s1 - s0)] = (
                            signal[s0:s1].astype(real_dt))

                        S_blk = H_Y = out_blk = None
                        try:
                            S_blk = torch.fft.rfft(
                                torch.from_numpy(seg).to(device))
                            H_Y   = S_blk.unsqueeze(0) * H_b
                            del S_blk; S_blk = None
                            out_blk = torch.fft.irfft(H_Y, n=n_block)
                            del H_Y;  H_Y = None
                            valid_out = out_blk[
                                :, overlap_M: overlap_M + valid_len
                            ].cpu().numpy()
                            del out_blk; out_blk = None
                            torch.cuda.empty_cache()
                        except (torch.cuda.OutOfMemoryError, RuntimeError) as _e:
                            if isinstance(_e, RuntimeError) and not _is_cuda_oom(_e):
                                raise
                            if S_blk  is not None: del S_blk
                            if H_Y    is not None: del H_Y
                            if out_blk is not None: del out_blk
                            del H_b; H_b = None
                            if final_lp_b is not None:
                                del final_lp_b; final_lp_b = None
                            torch.cuda.empty_cache()
                            reduced = False
                            for _ in range(2):
                                reduce_time = oom_reduce_time_next
                                oom_reduce_time_next = not oom_reduce_time_next
                                if reduce_time and C > overlap_M:
                                    C = max(overlap_M, C // 2)
                                    print(f"\n  GPU OOM (time block) — C halved "
                                          f"→ {C}", flush=True)
                                    reduced = True
                                    break
                                if (not reduce_time) and chunk_sz > 1:
                                    band_batch_sz = max(1, band_batch_sz // 2)
                                    print(f"\n  GPU OOM (time block) — band batch "
                                          f"→ {band_batch_sz}", flush=True)
                                    need_band_restart = True
                                    reduced = True
                                    break
                            if not reduced:
                                if C <= overlap_M:
                                    raise RuntimeError(
                                        f"CUDA OOM: time block C={C} at minimum. "
                                        f"Insufficient VRAM.")
                                C = max(overlap_M, C // 2)
                                print(f"\n  GPU OOM (time block) — C halved "
                                      f"→ {C}", flush=True)
                            block_oom = True
                            break

                        for j, bi in enumerate(bslice):
                            buf = _alloc_sub_buffer(bi)
                            buf[out_start:out_end] = valid_out[j]
                            if isinstance(buf, np.memmap):
                                buf.flush()

                    if block_oom or need_band_restart:
                        if H_b        is not None: del H_b
                        if final_lp_b is not None: del final_lp_b
                        break   # exit inner while → either retry or restart outer

                    # Success: advance LP cursor past this batch
                    cursor_np = final_lp_b.cpu().numpy()
                    del H_b, final_lp_b
                    torch.cuda.empty_cache()
                    break   # exit inner while, success

                if need_band_restart:
                    continue   # outer while: recompute bslice from new band_batch_sz

                done += chunk_sz
                _print_progress(done, t0, progress_cb)

        # ================================================================
        # Shared helpers
        # ================================================================
        def _write_shard_batch(done: int, chunk_sz: int,
                               batch_np: "np.ndarray") -> None:
            for j in range(chunk_sz):
                bi = done + j
                sub = np.asarray(batch_np[j], dtype=real_dt)
                buf = _alloc_sub_buffer(bi)
                buf[:] = sub
                if isinstance(buf, np.memmap):
                    buf.flush()

        def _print_progress(done: int, t0: float, cb: Any) -> None:
            elapsed = time.monotonic() - t0
            eta = (elapsed / done) * (n_bands - done) if done > 0 else 0.0
            print(
                f"\r  Filtering bands: {done}/{n_bands} "
                f"({done * 100 // n_bands}%) — "
                f"{elapsed:.1f}s elapsed, ~{eta:.0f}s remaining",
                end="", flush=True,
            )
            if cb:
                cb(done / n_bands * 0.5, f"Filtering {done}/{n_bands}")

        # ================================================================
        # Dispatch: attempt full-signal; escalate to time-chunk on OOM.
        # ================================================================
        n_fft = 1 << math.ceil(math.log2(max(n_samples, 2)))
        n_rfft = n_fft // 2 + 1

        # Upload signal FFT — if this alone OOMs, go straight to chunked
        S = freqs_t = None
        try:
            padded = np.zeros(n_fft, dtype=real_dt)
            padded[:n_samples] = signal.astype(real_dt)
            S = torch.fft.rfft(torch.from_numpy(padded).to(device))
            del padded
            torch.cuda.empty_cache()
            freqs_t = torch.linspace(
                0, nyq, n_rfft, device=device, dtype=torch_real)
        except (torch.cuda.OutOfMemoryError, RuntimeError) as _e:
            if isinstance(_e, RuntimeError) and not _is_cuda_oom(_e):
                raise
            if S      is not None: del S
            if freqs_t is not None: del freqs_t
            torch.cuda.empty_cache()
            print("  GPU: signal FFT too large for VRAM — using time-chunk mode",
                  flush=True)
            _run_chunked(None)
            print()
            return

        ok = _run_full_signal(S, freqs_t, n_fft)
        del S, freqs_t
        torch.cuda.empty_cache()

        if not ok:
            print("\n  GPU: escalating to time-chunk (overlap-save) mode",
                  flush=True)
            _run_chunked(None)

        print()

    @staticmethod
    def _write_band_npy_shard(
        fb_dir: str,
        bi: int,
        sub: np.ndarray | None,
        band: "BandDef",
        sr: int,
        save_precision: str,
        *,
        src_npy_path: str | None = None,
    ) -> dict[str, Any]:
        """Save one band shard as a .npy file.

        NPY stores the raw float signal at full computation precision with
        zero information loss.  The peak amplitude is recorded in metadata
        for reference but is NOT needed for reconstruction (the signal is
        stored unnormalized).

        If *src_npy_path* points to an existing `.npy` shard whose dtype
        already matches *save_precision*, it is reused directly.
        Otherwise a fresh np.save is issued.
        """
        save_dt = _precision_label_to_real_dtype(save_precision)
        fname = f"band_{bi:02d}.npy"
        fpath = os.path.join(fb_dir, fname)

        src_arr: np.ndarray | None = None
        if src_npy_path is not None and os.path.isfile(src_npy_path):
            src_arr = np.load(src_npy_path, mmap_mode="r", allow_pickle=False)
        elif sub is not None:
            src_arr = np.asarray(sub)
        else:
            raise RuntimeError(
                f"Missing source band data for band {bi} while writing {fname}"
            )

        peak = float(np.abs(np.asarray(src_arr)).max())
        moved = False
        same_path = (
            src_npy_path is not None
            and os.path.abspath(src_npy_path) == os.path.abspath(fpath)
        )
        if src_npy_path is not None and os.path.isfile(src_npy_path):
            # Existing `.npy` shard: reuse directly when dtype already matches.
            if hasattr(sub, 'flush'):
                sub.flush()
            src_dt = src_arr.dtype if src_arr is not None else None
            if src_dt == save_dt:
                if same_path:
                    moved = True
                else:
                    import shutil as _shutil
                    _shutil.move(src_npy_path, fpath)
                moved = True
        if not moved:
            _backpressure_wait(label=f"write_band_{bi}_npy")
            if same_path:
                # Avoid writing over a file that is currently mmap-open.
                tmp_path = fpath + ".tmp.npy"
                out_arr = np.asarray(src_arr, dtype=save_dt)
                if isinstance(src_arr, np.memmap):
                    _mm_obj = getattr(src_arr, "_mmap", None)
                    try:
                        src_arr.flush()
                    except Exception:
                        pass
                    if _mm_obj is not None:
                        try:
                            _mm_obj.close()
                        except Exception:
                            pass
                    del src_arr
                    gc.collect()
                np.save(tmp_path, out_arr)
                del out_arr
                os.replace(tmp_path, fpath)
            else:
                np.save(fpath, np.asarray(src_arr, dtype=save_dt))

        return {
            "index": bi,
            "fmin": band.fmin,
            "fmax": band.fmax,
            "label": band.label,
            "file": fname,
            "peak_amplitude": peak,
            "format": "npy",
        }

    def _write_band_npy_shards(
        self, fb_dir: str, sr: int, save_precision: str,
    ) -> list[dict[str, Any]]:
        """Write/update all band `.npy` shards from available sources."""
        results = []
        for i, band in enumerate(self.bands):
            sub = self.subbands[i] if i < len(self.subbands) else None
            src_path = None
            if i < len(self._subband_files):
                src_path = self._subband_files[i]
            if src_path is None:
                fallback = os.path.join(fb_dir, f"band_{i:02d}.npy")
                if os.path.isfile(fallback):
                    src_path = fallback
            results.append(self._write_band_npy_shard(
                fb_dir, i, sub, band, sr, save_precision,
                src_npy_path=src_path,
            ))

        return results

    def _reduce_existing_band_npy_bitdepth(
        self, fb_dir: str, sr: int, save_precision: str,
    ) -> list[dict[str, Any]]:
        """Reduce existing band `.npy` shards to save precision only.

        This path is disk-only: it requires existing `.npy` sources and does
        not use in-memory subband arrays.
        """
        results: list[dict[str, Any]] = []
        for i, band in enumerate(self.bands):
            src_path = None
            if i < len(self._subband_files):
                cand = self._subband_files[i]
                if cand and os.path.isfile(cand):
                    src_path = cand
            if src_path is None:
                cand = os.path.join(fb_dir, f"band_{i:02d}.npy")
                if os.path.isfile(cand):
                    src_path = cand
            if src_path is None:
                raise RuntimeError(
                    f"Missing required on-disk band shard for band {i}"
                )
            results.append(self._write_band_npy_shard(
                fb_dir, i, None, band, sr, save_precision,
                src_npy_path=src_path,
            ))
        return results

    @staticmethod
    def _envelope_path(analysis_dir: str) -> str:
        return os.path.join(analysis_dir, "filterbank", "fb_envelopes.npz")

    @staticmethod
    def _envelope_stream_mag_path(analysis_dir: str, band_idx: int) -> str:
        return os.path.join(
            analysis_dir, "filterbank", f"fb_envelope_mag_{int(band_idx):05d}.npy"
        )

    @staticmethod
    def _envelope_stream_phase_path(analysis_dir: str, band_idx: int) -> str:
        return os.path.join(
            analysis_dir, "filterbank", f"fb_envelope_phase_{int(band_idx):05d}.npy"
        )

    @staticmethod
    def _save_npz_atomic(path: str, data: dict[str, np.ndarray]) -> None:
        root, _ = os.path.splitext(path)
        tmp_base = root + ".tmp"
        tmp_actual = tmp_base + ".npz"
        try:
            np.savez_compressed(tmp_base, **data)
            os.replace(tmp_actual, path)
        finally:
            try:
                if os.path.exists(tmp_actual):
                    os.remove(tmp_actual)
            except OSError:
                pass

    def _write_filterbank_meta(
        self,
        fb_dir: str,
        sr: int,
        n_bands: int,
        meta_bands: list[dict[str, Any]],
        *,
        save_precision: str,
        band_audio_precision: str,
        wav_path: str | None = None,
        intermediate_precision: str | None = None,
    ) -> None:
        import json as _json

        meta: dict[str, Any] = {
            "filter_type": self.filter_type,
            "filter_mode": self.filter_mode,
            "sr": sr,
            "n_bands": n_bands,
            "bands": meta_bands,
            "save_precision": save_precision,
            "band_audio_precision": band_audio_precision,
        }
        if intermediate_precision is not None:
            meta["intermediate_precision"] = intermediate_precision
        center_hz = _infer_fb_center_hz_from_bands(self.bands)
        if center_hz is not None:
            meta["cafls_center_hz"] = float(center_hz)
        if wav_path:
            meta["wav_path"] = os.path.abspath(wav_path)
        with open(os.path.join(fb_dir, "filterbank_meta.json"), "w") as f:
            _json.dump(meta, f, indent=2)

    @staticmethod
    def _bands_match_meta(
        meta_bands: list[dict[str, Any]],
        bands: list["BandDef"],
    ) -> bool:
        if len(meta_bands) != len(bands):
            return False
        for meta_band, band in zip(meta_bands, bands):
            if not math.isclose(float(meta_band.get("fmin", 0.0)), float(band.fmin),
                                rel_tol=0.0, abs_tol=1e-9):
                return False
            if not math.isclose(float(meta_band.get("fmax", 0.0)), float(band.fmax),
                                rel_tol=0.0, abs_tol=1e-9):
                return False
        return True

    def compute_and_save(self, signal: np.ndarray, bands: list["BandDef"],
                         analysis_dir: str, sr: int,
                         batch_size: int = 32,
                         envelope_hop: int | list[int] | None = None,
                         intermediate_precision: str | None = None,
                         save_precision: str = "32-bit",
                         wav_path: str | None = None,
                         progress_cb: Any = None) -> None:
        """Filter, save band sidecars, and bake envelopes.

        Filtering: GPU FFT zero-phase cascade-LP-difference decomposition
        (perfect reconstruction, zero-phase, full VRAM utilisation with
        band-batch and time-chunk OOM halving).  Falls back to CPU only
        when CUDA is not available.

        After completion ``self.bands`` is set; ``self.subbands`` is
        cleared after all dependent analysis is finished and the final
        reduced sidecars have been written to disk.
        """
        import torch

        self._source_signal = signal.copy()
        self.bands = list(bands)
        self.subbands = []
        nyq = self.sr / 2.0
        n_bands = len(bands)
        n_samples = len(signal)
        if intermediate_precision is None:
            intermediate_precision = (
                "64-bit" if np.result_type(signal.dtype) == np.float64
                else "32-bit"
            )

        fb_dir = os.path.join(analysis_dir, "filterbank")
        os.makedirs(fb_dir, exist_ok=True)

        t0 = time.monotonic()
        if envelope_hop is None:
            expected_hops = [self.band_hop(b, self.sr) for b in self.bands]
        elif isinstance(envelope_hop, int):
            expected_hops = [envelope_hop] * n_bands
        else:
            expected_hops = list(envelope_hop)

        resume_state = self.load_envelope_checkpoint_state(analysis_dir)
        if resume_state is not None and resume_state.get("hops") != expected_hops:
            print("  Ignoring stale Hilbert checkpoint (hop mismatch)")
            resume_state = None

        reuse_saved = False
        meta_loaded = self.load_meta(analysis_dir)
        if meta_loaded is not None:
            meta_top, meta_bands = meta_loaded
            # Reuse existing permanent filterbank bands regardless of whether
            # Hilbert checkpoint exists.
            _meta_ok = (
                int(meta_top.get("sr", sr)) == sr
                and meta_top.get("filter_type", self.filter_type) == self.filter_type
                and self._bands_match_meta(meta_bands, bands)
                and len(meta_bands) == n_bands
            )
            if _meta_ok:
                real_dt = _precision_label_to_real_dtype(intermediate_precision)
                _subs: list[np.ndarray | None] = [None] * n_bands
                _completed = (
                    list(resume_state.get("completed", []))
                    if resume_state is not None else [False] * n_bands
                )
                if len(_completed) != n_bands:
                    _completed = [False] * n_bands
                for _bi, bm in enumerate(meta_bands):
                    if _completed[_bi]:
                        # Hilbert already complete for this band.
                        continue
                    fpath = os.path.join(fb_dir, bm["file"])
                    if not os.path.isfile(fpath):
                        _meta_ok = False
                        break
                    _mm = np.load(fpath, mmap_mode='r', allow_pickle=False)
                    if len(_mm) != n_samples:
                        _meta_ok = False
                        break
                    _subs[_bi] = _mm.astype(real_dt, copy=False)
            if _meta_ok:
                self.subbands = _subs
                self._subband_real_dt = real_dt
                self._subband_files = [
                    os.path.join(fb_dir, bm["file"]) for bm in meta_bands
                ]
                self._subband_file_meta = [dict(bm) for bm in meta_bands]
                reuse_saved = True
                if resume_state is None:
                    resume_state = {
                        "hops": list(expected_hops),
                        "completed": [False] * n_bands,
                    }
                    print("  Reusing existing filterbank bands from disk "
                          "(no refilter; Hilbert will run)")
                else:
                    done = sum(1 for flag in resume_state["completed"] if flag)
                    print(f"  Resuming Hilbert checkpoint: {done}/{n_bands} bands "
                          f"(bands mmap-backed, no eager RAM load)")

        if not reuse_saved:
            all_subs: list[np.ndarray | None] = [None] * n_bands
            if torch.cuda.is_available():
                # --- GPU zero-phase FFT filtering ------------------------
                self._filter_bands_gpu(signal, bands, nyq, n_samples, n_bands,
                                       fb_dir, sr, all_subs, t0,
                                       progress_cb)
            else:
                # --- CPU thread pool (CUDA unavailable) ------------------
                from concurrent.futures import ThreadPoolExecutor, as_completed

                n_workers = min(os.cpu_count() or 4, 16)

                def _filter_and_store(i: int) -> int:
                    sub = self._filter_one_band(signal, bands[i], nyq)
                    all_subs[i] = sub
                    return i

                done_count = 0
                with ThreadPoolExecutor(max_workers=n_workers) as pool:
                    futures = {pool.submit(_filter_and_store, i): i
                               for i in range(n_bands)}
                    for fut in as_completed(futures):
                        fut.result()
                        done_count += 1
                        frac = done_count / n_bands * 0.5
                        if done_count % 20 == 0 or done_count == n_bands:
                            elapsed = time.monotonic() - t0
                            eta = (elapsed / done_count) * (n_bands - done_count)
                            print(f"\r  Filtering bands: {done_count}/{n_bands} "
                                  f"({done_count * 100 // n_bands}%) — "
                                  f"{elapsed:.1f}s elapsed, ~{eta:.0f}s remaining",
                                  end="", flush=True)
                        if progress_cb:
                            progress_cb(frac, f"Filtering {done_count}/{n_bands}")
                print()

            self.subbands = [s for s in all_subs]  # type: ignore[misc]
            del all_subs

            # Persist restart-safe intermediary sidecars before Hilbert starts.
            interim_bands = self._write_band_npy_shards(
                fb_dir, sr, intermediate_precision)
            self._subband_real_dt = _precision_label_to_real_dtype(intermediate_precision)
            self._subband_files = [
                os.path.join(fb_dir, bm["file"]) for bm in interim_bands
            ]
            self._subband_file_meta = [dict(bm) for bm in interim_bands]
            self._write_filterbank_meta(
                fb_dir, sr, n_bands, interim_bands,
                save_precision=save_precision,
                band_audio_precision=intermediate_precision,
                wav_path=wav_path,
                intermediate_precision=intermediate_precision,
            )

        # --- Compute Hilbert envelopes (GPU when available) ---------------
        if progress_cb:
            progress_cb(0.5, "Hilbert envelopes")
        print("  Computing Hilbert envelopes ...", end="", flush=True)
        t1 = time.monotonic()
        env_save_dt = _precision_label_to_np_dtype(save_precision)

        checkpoint_state = {
            "mags": [None] * n_bands,
            "phases": [None] * n_bands,
            "hops": list(expected_hops),
            "completed": [False] * n_bands,
        }
        if resume_state is not None:
            rs_hops = list(resume_state.get("hops", []))
            rs_done = list(resume_state.get("completed", []))
            if len(rs_hops) == n_bands:
                checkpoint_state["hops"] = [int(h) for h in rs_hops]
            if len(rs_done) == n_bands:
                checkpoint_state["completed"] = [bool(x) for x in rs_done]

        def _hilbert_progress(chunk_done: int, chunk_total: int) -> None:
            # Hilbert = 50..90% of total
            frac = 0.5 + 0.4 * (chunk_done / max(chunk_total, 1))
            if progress_cb:
                progress_cb(frac, f"Hilbert {chunk_done}/{chunk_total}")

        def _checkpoint_band(
            band_idx: int,
            mag: np.ndarray,
            phase: np.ndarray,
            hop_val: int,
        ) -> None:
            checkpoint_state["mags"][band_idx] = None
            checkpoint_state["phases"][band_idx] = None
            checkpoint_state["hops"][band_idx] = int(hop_val)
            checkpoint_state["completed"][band_idx] = True
            self.save_envelope_progress_state(
                analysis_dir,
                hops=list(checkpoint_state["hops"]),
                completed=list(checkpoint_state["completed"]),
            )
            # Persist finalized per-band envelope shards in save precision.
            mag_path = self._envelope_stream_mag_path(analysis_dir, band_idx)
            phase_path = self._envelope_stream_phase_path(analysis_dir, band_idx)
            need_write = True
            try:
                if os.path.isfile(mag_path) and os.path.isfile(phase_path):
                    mm = np.load(mag_path, mmap_mode="r", allow_pickle=False)
                    pm = np.load(phase_path, mmap_mode="r", allow_pickle=False)
                    need_write = (
                        mm.dtype != env_save_dt
                        or pm.dtype != env_save_dt
                        or len(mm) != len(mag)
                        or len(pm) != len(phase)
                    )
            except Exception:
                need_write = True
            if need_write:
                np.save(mag_path, np.asarray(mag, dtype=env_save_dt))
                np.save(phase_path, np.asarray(phase, dtype=env_save_dt))

        if not all(bool(x) for x in checkpoint_state["completed"]):
            # Streaming Hilbert: each band is checkpoint-written on completion
            # and immediately dropped from RAM.
            _mags_ignored, _phases_ignored, _hops_ignored = self.compute_envelopes(
                hop=envelope_hop,
                hilbert_progress=_hilbert_progress,
                band_result_cb=_checkpoint_band,
                resume_state=checkpoint_state,
                drop_after_callback=True,
                stream_chunk_dir=analysis_dir,
                stream_chunk_dtype=np.dtype(env_save_dt))
        hops = list(checkpoint_state["hops"])
        if not all(bool(x) for x in checkpoint_state["completed"]):
            missing = [str(i + 1) for i, done in enumerate(checkpoint_state["completed"]) if not done]
            raise RuntimeError(
                "Hilbert checkpoint incomplete after run; missing bands: "
                + ", ".join(missing[:8])
                + (" ..." if len(missing) > 8 else "")
            )
        print(f" done ({time.monotonic() - t1:.1f}s)")
        if progress_cb:
            progress_cb(0.9, "Saving")
        # Final band shard conversion uses on-disk .npy sources only.
        meta_bands = self._reduce_existing_band_npy_bitdepth(
            fb_dir, sr, save_precision
        )
        self._write_filterbank_meta(
            fb_dir, sr, n_bands, meta_bands,
            save_precision=save_precision,
            band_audio_precision=save_precision,
            wav_path=wav_path,
            intermediate_precision=intermediate_precision,
        )

        # --- Finalize envelope progress marker (per-band envelope shards
        # remain on disk and are loaded lazily when needed) -----------------
        self.save_envelope_progress_state(
            analysis_dir,
            hops=hops,
            completed=[True] * n_bands,
        )
        self.subbands = []  # free the subband memory after envelopes + sidecars
        print(f"  Filterbank complete: {n_bands} bands in "
              f"{time.monotonic() - t0:.1f}s")
        if progress_cb:
            progress_cb(1.0, "FB done")

    def save(self, analysis_dir: str, sr: int,
             envelope_hop: int | list[int] | None = None,
             save_precision: str = "32-bit") -> None:
        """Save subbands as `.npy` shards + metadata, and bake Hilbert
        envelopes into *fb_envelopes.npz* with per-band hops derived
        from each band's bandwidth.

        If subbands are already in memory (from a prior ``compute()``),
        this saves them directly.  For large decompositions use
        ``compute_and_save()`` which batches to control peak memory.
        """
        fb_dir = os.path.join(analysis_dir, "filterbank")
        os.makedirs(fb_dir, exist_ok=True)
        meta = {
            "filter_type": self.filter_type,
            "sr": sr,
            "n_bands": len(self.bands),
            "save_precision": save_precision,
            "band_audio_precision": save_precision,
        }
        center_hz = _infer_fb_center_hz_from_bands(self.bands)
        if center_hz is not None:
            meta["cafls_center_hz"] = float(center_hz)
        # Keep native-precision subbands alive through envelope analysis, then
        # write reduced sidecars only once the dependent analysis is finished.
        mags, phases, hops = self.compute_envelopes(hop=envelope_hop)
        meta["bands"] = self._write_band_npy_shards(fb_dir, sr, save_precision)
        import json
        with open(os.path.join(fb_dir, "filterbank_meta.json"), "w") as f:
            json.dump(meta, f, indent=2)

        self.save_envelopes(analysis_dir, mags, phases, hops,
                            save_precision=save_precision)

    @staticmethod
    def envelope_save_dict(
        mags: list[np.ndarray | None],
        phases: list[np.ndarray | None],
        hops: list[int],
        *,
        save_precision: str = "32-bit",
        completed: list[bool] | None = None,
    ) -> dict[str, np.ndarray]:
        """Build an NPZ payload for filterbank envelopes."""
        n_bands = len(hops)
        if completed is None:
            completed = [True] * n_bands
        if len(mags) != n_bands or len(phases) != n_bands or len(completed) != n_bands:
            raise ValueError("Envelope payload lengths must match n_bands")

        save_dtype = _precision_label_to_np_dtype(save_precision)
        completed_idx = [
            i for i, done in enumerate(completed)
            if done and mags[i] is not None and phases[i] is not None
        ]
        mag_encoded, mag_scale = _encode_scaled_float_arrays(
            [np.asarray(mags[i]) for i in completed_idx], save_dtype)
        phase_encoded = [
            np.asarray(phases[i], dtype=save_dtype) for i in completed_idx
        ]
        data: dict[str, np.ndarray] = {
            "n_bands": np.int64(n_bands),
            "hops": np.array(hops, dtype=np.int64),
            "completed": np.array(completed, dtype=np.uint8),
        }
        if mag_scale is not None:
            data["mag_scale"] = np.float64(mag_scale)
        for slot, band_idx in enumerate(completed_idx):
            data[f"mag_{band_idx}"] = mag_encoded[slot]
            data[f"phase_{band_idx}"] = phase_encoded[slot]
        return data

    def save_envelopes(self, analysis_dir: str,
                       mags: list[np.ndarray],
                       phases: list[np.ndarray],
                       hops: list[int],
                       *,
                       save_precision: str = "32-bit") -> None:
        """Persist per-band envelopes as *fb_envelopes.npz*."""
        fb_dir = os.path.join(analysis_dir, "filterbank")
        os.makedirs(fb_dir, exist_ok=True)
        data = self.envelope_save_dict(
            mags, phases, hops, save_precision=save_precision)
        self._save_npz_atomic(self._envelope_path(analysis_dir), data)

    def save_envelope_progress_state(
        self,
        analysis_dir: str,
        *,
        hops: list[int],
        completed: list[bool],
    ) -> None:
        """Write lightweight progress metadata to the main envelope file.

        This updates *fb_envelopes.npz* after each completed band without
        materializing large mag/phase arrays in RAM.
        """
        fb_dir = os.path.join(analysis_dir, "filterbank")
        os.makedirs(fb_dir, exist_ok=True)
        data: dict[str, np.ndarray] = {
            "n_bands": np.int64(len(hops)),
            "hops": np.array([int(h) for h in hops], dtype=np.int64),
            "completed": np.array(completed, dtype=np.uint8),
            "progress_only": np.uint8(1),
        }
        self._save_npz_atomic(self._envelope_path(analysis_dir), data)

    @staticmethod
    def load_envelope_checkpoint_state(
        analysis_dir: str,
    ) -> dict[str, Any] | None:
        # Active path: resume state lives in fb_envelopes.npz
        path = FilterBankDecomposition._envelope_path(analysis_dir)
        if os.path.isfile(path):
            with np.load(path) as d:
                if "n_bands" not in d or "completed" not in d or "hops" not in d:
                    return None
                n = int(d["n_bands"])
                hops = d["hops"].tolist()
                completed = [bool(x) for x in np.asarray(d["completed"]).tolist()]
                if len(completed) != n:
                    return None
                if len(hops) != n:
                    return None
                return {
                    "hops": hops,
                    "completed": completed,
                }
        return None

    @staticmethod
    def load_envelope_band_shard(
        analysis_dir: str,
        band_idx: int,
    ) -> tuple[np.ndarray, np.ndarray, int] | None:
        mag_path = FilterBankDecomposition._envelope_stream_mag_path(
            analysis_dir, band_idx)
        phi_path = FilterBankDecomposition._envelope_stream_phase_path(
            analysis_dir, band_idx)
        if os.path.isfile(mag_path) and os.path.isfile(phi_path):
            mag = np.load(mag_path, mmap_mode="r", allow_pickle=False)
            phase_arr = np.load(phi_path, mmap_mode="r", allow_pickle=False)
            phase_dt = (np.float32 if phase_arr.dtype == np.float16
                        else phase_arr.dtype)
            phase = np.asarray(phase_arr, dtype=phase_dt)
            hop = 1
            state = FilterBankDecomposition.load_envelope_checkpoint_state(analysis_dir)
            if state is not None:
                hops = list(state.get("hops", []))
                if 0 <= band_idx < len(hops):
                    hop = int(hops[band_idx])
            return np.asarray(mag), phase, hop
        return None

    @staticmethod
    def load_envelopes(analysis_dir: str
                       ) -> tuple[list[np.ndarray], list[np.ndarray],
                                  list[int]] | None:
        """Load cached per-band envelopes.  Returns
        ``(mags, phases, hops)`` or *None* if no cache exists."""
        path = os.path.join(analysis_dir, "filterbank",
                            "fb_envelopes.npz")
        if not os.path.isfile(path):
            return None
        with np.load(path) as d:
            if "n_bands" not in d:
                # Legacy single-hop format — ignore, will recompute
                return None
            n = int(d["n_bands"])
            completed = ([bool(x) for x in np.asarray(d["completed"]).tolist()]
                         if "completed" in d else [True] * n)
            if not all(completed):
                return None
            hops = d["hops"].tolist()
            if "progress_only" in d:
                mags: list[np.ndarray] = []
                phases: list[np.ndarray] = []
                for i in range(n):
                    loaded = FilterBankDecomposition.load_envelope_band_shard(
                        analysis_dir, i)
                    if loaded is None:
                        return None
                    mag, phase, _hop = loaded
                    mags.append(np.asarray(mag))
                    phases.append(np.asarray(phase))
                return mags, phases, hops
            mag_scale = float(d["mag_scale"]) if "mag_scale" in d else None
            for i in range(n):
                if f"mag_{i}" not in d or f"phase_{i}" not in d:
                    return None
            mags = [_decode_scaled_float_array(d[f"mag_{i}"], mag_scale)
                    for i in range(n)]
            phases = []
            for i in range(n):
                phase_arr = d[f"phase_{i}"]
                phase_dt = np.float32 if phase_arr.dtype == np.float16 else phase_arr.dtype
                phases.append(np.asarray(phase_arr, dtype=phase_dt))
            return mags, phases, hops

    @staticmethod
    def load_meta(analysis_dir: str
                  ) -> tuple[dict, list[dict]] | None:
        """Load only filterbank metadata (no band shard payloads).

        Returns ``(top_meta, bands_list)`` or *None*.
        """
        import json
        fb_dir = os.path.join(analysis_dir, "filterbank")
        meta_path = os.path.join(fb_dir, "filterbank_meta.json")
        if not os.path.isfile(meta_path):
            return None
        with open(meta_path) as f:
            meta = json.load(f)
        return meta, meta["bands"]

    def get_subband(self, band_idx: int) -> np.ndarray:
        """Return one subband, loading it lazily from disk if needed."""
        if band_idx < 0 or band_idx >= len(self.subbands):
            return np.zeros(0, dtype=self._subband_real_dt)
        cached = self.subbands[band_idx]
        if isinstance(cached, np.ndarray):
            return cached
        fpath = (self._subband_files[band_idx]
                 if band_idx < len(self._subband_files) else None)
        bm = (self._subband_file_meta[band_idx]
              if band_idx < len(self._subband_file_meta) else None)
        if not fpath or not os.path.isfile(fpath):
            arr = np.zeros(0, dtype=self._subband_real_dt)
            self.subbands[band_idx] = arr
            return arr

        if fpath.lower().endswith(".npy"):
            raw = np.load(fpath, mmap_mode="r", allow_pickle=False)
            arr = raw.astype(self._subband_real_dt, copy=False)
        else:
            # Legacy scaled payload: restore original float scale.
            _sr_wav, data = _load_audio(fpath)
            peak = float((bm or {}).get("peak_amplitude", 1.0))
            if np.issubdtype(data.dtype, np.integer):
                imax = max(abs(np.iinfo(data.dtype).min),
                           np.iinfo(data.dtype).max)
                arr = data.astype(self._subband_real_dt) / imax * peak
            else:
                arr = data.astype(self._subband_real_dt) * peak
        self.subbands[band_idx] = arr
        return arr

    @staticmethod
    def load(analysis_dir: str, compute_precision: str | None = None
             ) -> "FilterBankDecomposition | None":
        """Load a previously saved filter bank decomposition."""
        import json
        fb_dir = os.path.join(analysis_dir, "filterbank")
        meta_path = os.path.join(fb_dir, "filterbank_meta.json")
        if not os.path.isfile(meta_path):
            return None
        with open(meta_path) as f:
            meta = json.load(f)
        fb = FilterBankDecomposition(meta["sr"], meta.get("filter_type", "Linkwitz-Riley 4"),
                                     filter_mode=meta.get("filter_mode", "fir"))
        real_dt = (_precision_label_to_real_dtype(compute_precision)
                   if compute_precision else np.float32)
        fb._subband_real_dt = real_dt
        n_bands = len(meta["bands"])
        t0 = time.monotonic()
        for idx, bm in enumerate(meta["bands"]):
            fb.bands.append(BandDef(
                fmin=bm["fmin"], fmax=bm["fmax"], label=bm.get("label", "")))
            fpath = os.path.join(fb_dir, bm["file"])
            fb._subband_files.append(fpath if os.path.isfile(fpath) else None)
            fb._subband_file_meta.append(dict(bm))
            fb.subbands.append(None)
            # Progress every 20 bands or on the last one
            if idx % 20 == 0 or idx == n_bands - 1:
                elapsed = time.monotonic() - t0
                pct = (idx + 1) / n_bands * 100
                eta = (elapsed / (idx + 1)) * (n_bands - idx - 1) if idx > 0 else 0.0
                print(f"\r  Loading filterbank metadata: {idx + 1}/{n_bands} "
                      f"({pct:.0f}%) — {elapsed:.1f}s elapsed, "
                      f"~{eta:.0f}s remaining", end="", flush=True)
        print()  # newline after progress
        return fb

    def graduate_band(self, band_idx: int, output_dir: str, sr: int) -> str:
        """Export a single subband as a standalone .npy file in output_dir.
        Returns the written file path.  Raw (unnormalized) float signal is
        stored so no precision is lost on export.
        """
        band = self.bands[band_idx]
        sub = self.get_subband(band_idx)
        safe_label = band.label.replace(" ", "_").replace("/", "-")
        fname = f"fb_{safe_label}.npy"
        fpath = os.path.join(output_dir, fname)
        np.save(fpath, np.asarray(sub))
        return fpath


def _build_field_sources(has_onset: bool,
                         has_fb: bool = False,
                         has_wvlt: bool = False) -> list[FieldSource]:
    """Build the list of data fields from the virtual texture layouts.

    Includes placeholder entries for filterbank and wavelet sources
    so they appear in the tree (greyed out when unavailable).

    Audio is always stored as L+R internally; mono-derived fields use
    the shader's *uMonoMixMode* uniform to mix L and R on the GPU.
    """
    seen: set[str] = set()
    sources: list[FieldSource] = []
    for tex_name, layout in _TEXTURE_LAYOUTS.items():
        if tex_name == "onset" and not has_onset:
            # Still add as unavailable so it shows in tree
            sources.append(FieldSource(
                name="onset",
                display_name=FIELD_DISPLAY.get("onset", "onset"),
                tex_name=tex_name,
                tex_channel=0,
                category="cqt",
                available=False,
            ))
            seen.add("onset")
            continue
        if tex_name == "wavelet_coeffs":
            # Wavelet fields handled separately below with has_wvlt flag
            continue
        if tex_name.startswith("fb_"):
            # Filterbank fields handled separately below with has_fb flag
            continue
        for ch_idx, ch_key in enumerate("RGBA"):
            field_name = layout.get(ch_key)
            if field_name is None or field_name in seen:
                continue
            seen.add(field_name)
            cat = _FIELD_CATEGORY_MAP.get(field_name, "cqt")
            sources.append(FieldSource(
                name=field_name,
                display_name=FIELD_DISPLAY.get(field_name, field_name),
                tex_name=tex_name,
                tex_channel=ch_idx,
                category=cat,
                available=True,
            ))

    # Filterbank L/R fields.
    # tex_names use dedicated "fb_*_polar" keys so they do NOT alias
    # the CQT textures — _compute_fb_envelopes uploads under these keys
    # and _render_fb_tf binds them through _set_field_uniforms.
    fb_fields = [
        ("fb_mag_left",    "FB Mag L",   "fb_left_polar",  0),
        ("fb_phase_left",  "FB Phase L", "fb_left_polar",  1),
        ("fb_mag_right",   "FB Mag R",   "fb_right_polar", 0),
        ("fb_phase_right", "FB Phase R", "fb_right_polar", 1),
    ]
    for fname, dname, tname, ch in fb_fields:
        if fname not in seen:
            seen.add(fname)
            sources.append(FieldSource(
                name=fname,
                display_name=dname,
                tex_name=tname,
                tex_channel=ch,
                category="fb",
                available=has_fb,
            ))

    # Wavelet approximation/detail
    wvlt_fields = [
        ("wvlt_approx", "Wvlt Approx", "wavelet_coeffs", 0),
        ("wvlt_detail", "Wvlt Detail", "wavelet_coeffs", 1),
    ]
    for fname, dname, tname, ch in wvlt_fields:
        if fname not in seen:
            seen.add(fname)
            sources.append(FieldSource(
                name=fname,
                display_name=dname,
                tex_name=tname,
                tex_channel=ch,
                category="wvlt",
                available=has_wvlt,
            ))

    return sources


# ---------------------------------------------------------------------------
# Menu bar — top-of-window pull-down menu system
# ---------------------------------------------------------------------------

@dataclass
class MenuItem:
    """One item inside a pull-down menu.

    *label*
        Display text.  ``"-"`` creates a visual separator.
    *action*
        Callable invoked when clicked.  ``None`` for separators / parent menus.
    *shortcut*
        Optional keyboard hint string shown right-aligned (display only).
    *toggle_state*
        Callable returning ``bool`` for check-mark items, or ``None``.
    *enabled*
        Callable returning ``bool``, or a plain ``bool``.
    *children*
        Nested ``list[MenuItem]`` for a submenu.
    *radio_group*
        Optional string tag.  All items in the same menu that share the
        same *radio_group* value form a mutually-exclusive set: clicking
        one deactivates the others.  The active item shows a bullet
        (``\u25cf``) instead of a checkmark.  Use *toggle_state* to
        report which is currently selected.
    """
    label: str
    action: Any = None            # () -> None
    shortcut: str = ""
    toggle_state: Any = None      # () -> bool | None
    enabled: Any = True           # () -> bool | bool
    children: list["MenuItem"] | None = None
    radio_group: str | None = None

    @property
    def is_separator(self) -> bool:
        return self.label == "-"

    @property
    def is_enabled(self) -> bool:
        if callable(self.enabled):
            return self.enabled()
        return bool(self.enabled)

    @property
    def is_checked(self) -> bool | None:
        if self.toggle_state is None:
            return None
        return self.toggle_state()

    @property
    def has_submenu(self) -> bool:
        return bool(self.children)


@dataclass
class _MenuColumn:
    """Runtime state for one open pull-down column."""
    title: str
    items: list[MenuItem]
    rect: pygame.Rect                   # bounding rect in screen coords
    item_rects: list[pygame.Rect]       # per-item rects in screen coords
    hover_idx: int = -1


class MenuBar:
    """Top-of-window pull-down menu bar.

    Usage::

        menu = MenuBar()
        menu.add_menu("File", [
            MenuItem("Open…", action=self._open_file, shortcut="Ctrl+O"),
            MenuItem("-"),
            MenuItem("Quit", action=self._quit, shortcut="Esc"),
        ])
        menu.add_menu("View", [...])

    In the run loop, call ``menu.handle_event(event)`` **before** other
    handlers (it returns ``True`` when consumed).  Call ``menu.render()``
    to get a ``pygame.Surface`` for the bar, and ``menu.render_dropdown()``
    for any open column.  Both may return ``None``.

    Rendering contract
    ------------------
    * The bar surface spans the full window width and ``MenuBar.BAR_H`` px.
    * Dropdown surfaces are positioned absolutely in screen space — query
      ``menu.dropdown_screen_rect`` for GL quad placement.
    """

    BAR_H = 24
    ITEM_H = 24
    SEP_H = 9
    MIN_COL_W = 160
    SHORTCUT_PAD = 40

    # colours
    _BAR_BG = (38, 38, 38, 230)
    _BAR_HOVER = (60, 60, 80, 255)
    _BAR_TEXT = (200, 200, 200)
    _DD_BG = (34, 34, 42, 240)
    _DD_HOVER = (55, 64, 90, 255)
    _DD_TEXT = (220, 220, 220)
    _DD_DISABLED = (100, 100, 100)
    _DD_SHORTCUT = (130, 130, 150)
    _DD_SEP = (60, 60, 70)
    _DD_CHECK = (120, 200, 120)
    _DD_BORDER = (80, 80, 100)
    _DD_SUBMENU_ARROW = (160, 160, 180)

    def __init__(self) -> None:
        self._menus: list[tuple[str, list[MenuItem]]] = []
        self._title_rects: list[pygame.Rect] = []
        self._open_idx: int = -1               # which top-level is open
        self._columns: list[_MenuColumn] = []   # stack (supports submenu depth)
        self._bar_hover_idx: int = -1
        self._armed: bool = False               # True while bar is "sticky"
        self.font: pygame.font.Font | None = None
        self.visible: bool = True

    # ---- Public API -------------------------------------------------------

    def add_menu(self, title: str, items: list[MenuItem]) -> None:
        """Append a new top-level menu."""
        self._menus.append((title, items))

    def insert_menu(self, index: int, title: str,
                    items: list[MenuItem]) -> None:
        """Insert a top-level menu at *index*."""
        self._menus.insert(index, (title, items))

    def set_items(self, title: str, items: list[MenuItem]) -> None:
        """Replace the items of an existing top-level menu by *title*."""
        for i, (t, _) in enumerate(self._menus):
            if t == title:
                self._menus[i] = (title, items)
                return
        self.add_menu(title, items)

    @property
    def is_open(self) -> bool:
        return self._open_idx >= 0

    @property
    def bar_height(self) -> int:
        return self.BAR_H if self.visible else 0

    # ---- Rendering --------------------------------------------------------

    def _ensure_font(self) -> None:
        if self.font is None:
            pygame.font.init()
            self.font = pygame.font.SysFont("consolas", 13)

    def _layout_titles(self, win_w: int) -> None:
        """Recompute title rects for the current window width."""
        self._ensure_font()
        x = 0
        rects: list[pygame.Rect] = []
        for title, _ in self._menus:
            tw = self.font.size(title)[0] + 20
            rects.append(pygame.Rect(x, 0, tw, self.BAR_H))
            x += tw
        self._title_rects = rects

    def render(self, win_w: int) -> pygame.Surface | None:
        """Return a surface for the menu bar (full window width)."""
        if not self.visible:
            return None
        self._ensure_font()
        self._layout_titles(win_w)
        surf = pygame.Surface((win_w, self.BAR_H), pygame.SRCALPHA)
        surf.fill(self._BAR_BG)

        for i, (title, _) in enumerate(self._menus):
            rect = self._title_rects[i]
            if i == self._open_idx or i == self._bar_hover_idx:
                pygame.draw.rect(surf, self._BAR_HOVER, rect)
            txt = self.font.render(title, True, self._BAR_TEXT)
            surf.blit(txt, (rect.x + 10, rect.y + (self.BAR_H - txt.get_height()) // 2))

        # subtle bottom border
        pygame.draw.line(surf, self._DD_BORDER, (0, self.BAR_H - 1),
                         (win_w, self.BAR_H - 1))
        return surf

    def render_dropdown(self) -> pygame.Surface | None:
        """Return a surface covering all open dropdown columns."""
        if not self._columns:
            return None
        # Compute bounding rect of all columns
        rects = [c.rect for c in self._columns]
        x0 = min(r.x for r in rects)
        y0 = min(r.y for r in rects)
        x1 = max(r.x + r.w for r in rects)
        y1 = max(r.y + r.h for r in rects)
        bw, bh = x1 - x0, y1 - y0
        surf = pygame.Surface((bw, bh), pygame.SRCALPHA)
        surf.fill((0, 0, 0, 0))
        # Blit each column into the combined surface
        for col in self._columns:
            cs = self._render_column(col)
            surf.blit(cs, (col.rect.x - x0, col.rect.y - y0))
        self._dropdown_bounding = pygame.Rect(x0, y0, bw, bh)
        return surf

    @property
    def dropdown_screen_rect(self) -> pygame.Rect | None:
        """Screen-space bounding rect of all open dropdown columns."""
        if not self._columns:
            return None
        return getattr(self, '_dropdown_bounding', self._columns[-1].rect)

    def _render_column(self, col: _MenuColumn) -> pygame.Surface:
        self._ensure_font()
        r = col.rect
        surf = pygame.Surface((r.w, r.h), pygame.SRCALPHA)
        surf.fill(self._DD_BG)
        for i, item in enumerate(col.items):
            ir = col.item_rects[i]
            # item_rects are in screen coords; offset to surface-local
            ly = ir.y - r.y
            lx = 0
            local_r = pygame.Rect(lx, ly, ir.w, ir.h)

            if item.is_separator:
                mid = ly + self.SEP_H // 2
                pygame.draw.line(surf, self._DD_SEP, (8, mid), (r.w - 8, mid))
                continue

            enabled = item.is_enabled
            if i == col.hover_idx and enabled:
                pygame.draw.rect(surf, self._DD_HOVER, local_r)

            text_col = self._DD_TEXT if enabled else self._DD_DISABLED
            x_text = 8

            # check / radio mark for toggle items
            checked = item.is_checked
            if checked is not None:
                if item.radio_group is not None:
                    mark = "\u25cf " if checked else "   "
                else:
                    mark = "\u2713 " if checked else "   "
                msf = self.font.render(mark, True, self._DD_CHECK if checked else text_col)
                surf.blit(msf, (x_text, ly + (ir.h - msf.get_height()) // 2))
                x_text += msf.get_width()

            label_sf = self.font.render(item.label, True, text_col)
            surf.blit(label_sf, (x_text, ly + (ir.h - label_sf.get_height()) // 2))

            # shortcut hint (right-aligned)
            if item.shortcut:
                sc_sf = self.font.render(item.shortcut, True, self._DD_SHORTCUT)
                surf.blit(sc_sf, (r.w - sc_sf.get_width() - 10,
                                  ly + (ir.h - sc_sf.get_height()) // 2))

            # submenu arrow
            if item.has_submenu:
                arr = self.font.render("\u25b6", True, self._DD_SUBMENU_ARROW)
                surf.blit(arr, (r.w - arr.get_width() - 6,
                                ly + (ir.h - arr.get_height()) // 2))

        pygame.draw.rect(surf, self._DD_BORDER,
                         pygame.Rect(0, 0, r.w, r.h), 1)
        return surf

    # ---- Column geometry helpers ------------------------------------------

    def _build_column(self, items: list[MenuItem], anchor_x: int,
                      anchor_y: int, title: str = "") -> _MenuColumn:
        """Create a _MenuColumn positioned at *(anchor_x, anchor_y)*.

        Clamps the column so it stays within the current window bounds.
        """
        self._ensure_font()
        col_w = self.MIN_COL_W
        for item in items:
            if item.is_separator:
                continue
            lw = self.font.size(item.label)[0] + 24
            if item.is_checked is not None or item.radio_group is not None:
                lw += self.font.size("\u25cf ")[0]
            if item.shortcut:
                lw += self.font.size(item.shortcut)[0] + self.SHORTCUT_PAD
            if item.has_submenu:
                lw += 20
            col_w = max(col_w, lw)

        total_h = sum(self.SEP_H if it.is_separator else self.ITEM_H
                       for it in items)

        # --- clamp to window bounds ---
        try:
            win_w, win_h = pygame.display.get_surface().get_size()
        except Exception:
            win_w, win_h = 1920, 1080
        # Horizontal: keep within window
        if anchor_x + col_w > win_w:
            anchor_x = max(0, win_w - col_w)
        # Vertical: if it'd extend past the bottom, shift it up
        if anchor_y + total_h > win_h:
            anchor_y = max(0, win_h - total_h)

        y = anchor_y
        rects: list[pygame.Rect] = []
        for item in items:
            h = self.SEP_H if item.is_separator else self.ITEM_H
            rects.append(pygame.Rect(anchor_x, y, col_w, h))
            y += h

        col_rect = pygame.Rect(anchor_x, anchor_y, col_w, total_h)
        return _MenuColumn(title=title, items=items, rect=col_rect,
                           item_rects=rects)

    def _open_top_menu(self, idx: int) -> None:
        """Open top-level menu *idx*, closing whatever was open."""
        self._close_all()
        if idx < 0 or idx >= len(self._menus):
            return
        title, items = self._menus[idx]
        r = self._title_rects[idx]
        col = self._build_column(items, r.x, self.BAR_H, title)
        self._columns = [col]
        self._open_idx = idx
        self._armed = True

    def _close_all(self) -> None:
        self._columns.clear()
        self._open_idx = -1
        self._armed = False

    # ---- Event handling ---------------------------------------------------

    def handle_event(self, event: pygame.event.Event) -> bool:
        """Process *event*.  Returns ``True`` if consumed."""
        if not self.visible:
            return False

        if event.type == MOUSEMOTION:
            mx, my = event.pos
            # Track hover over bar titles
            self._bar_hover_idx = -1
            for i, r in enumerate(self._title_rects):
                if r.collidepoint(mx, my):
                    self._bar_hover_idx = i
                    # If another menu is already open, slide into this one
                    if self._armed and i != self._open_idx:
                        self._open_top_menu(i)
                    break

            # Track hover inside open columns (from deepest to shallowest)
            if self._columns:
                hit_any = False
                for depth in range(len(self._columns) - 1, -1, -1):
                    col = self._columns[depth]
                    if not col.rect.collidepoint(mx, my):
                        continue
                    hit_any = True
                    col.hover_idx = -1
                    opened_submenu = False
                    for j, ir in enumerate(col.item_rects):
                        if ir.collidepoint(mx, my):
                            item = col.items[j]
                            if not item.is_separator:
                                col.hover_idx = j
                                # Auto-open submenu on hover
                                if item.has_submenu and item.is_enabled:
                                    self._open_submenu(j, col)
                                    opened_submenu = True
                            break
                    # If mouse is in a parent column and did NOT just
                    # open a submenu, collapse any deeper columns
                    if not opened_submenu and depth < len(self._columns) - 1:
                        while len(self._columns) > depth + 1:
                            self._columns.pop()
                    break  # only process the deepest hit

                # If mouse is outside all columns and bar, clear deepest hover
                if not hit_any and my >= self.BAR_H:
                    self._columns[-1].hover_idx = -1

            # Consume motion only if over bar or open column
            if my < self.BAR_H:
                return True
            if self._columns:
                for c in self._columns:
                    if c.rect.collidepoint(mx, my):
                        return True
            return False

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos

            # Click on bar title
            for i, r in enumerate(self._title_rects):
                if r.collidepoint(mx, my):
                    if self._open_idx == i:
                        self._close_all()
                    else:
                        self._open_top_menu(i)
                    return True

            # Click inside open dropdown (check all columns, deepest first)
            if self._columns:
                for depth in range(len(self._columns) - 1, -1, -1):
                    col = self._columns[depth]
                    if not col.rect.collidepoint(mx, my):
                        continue
                    for j, ir in enumerate(col.item_rects):
                        if ir.collidepoint(mx, my):
                            item = col.items[j]
                            if item.is_separator or not item.is_enabled:
                                return True
                            if item.has_submenu:
                                self._open_submenu(j, col)
                                return True
                            # Fire action
                            if item.action:
                                self._close_all()
                                item.action()
                            else:
                                self._close_all()
                            return True
                    # Clicked inside column rect but not on any item
                    return True

            # Click outside — close everything
            if self._armed:
                self._close_all()
                return True

            # Click in bar region but not on a title — consume anyway
            if my < self.BAR_H:
                return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            mx, my = event.pos
            if my < self.BAR_H:
                return True
            if self._columns:
                for c in self._columns:
                    if c.rect.collidepoint(mx, my):
                        return True

        if event.type == MOUSEWHEEL:
            mx, my = pygame.mouse.get_pos()
            if my < self.BAR_H:
                return True
            if self._columns:
                for c in self._columns:
                    if c.rect.collidepoint(mx, my):
                        return True

        if event.type == KEYDOWN and self._armed:
            key = event.key
            if key == K_ESCAPE:
                self._close_all()
                return True
            if key == K_LEFT:
                self._navigate_bar(-1)
                return True
            if key == K_RIGHT:
                self._navigate_bar(1)
                return True
            if self._columns:
                col = self._columns[-1]
                if key == pygame.K_UP:
                    col.hover_idx = self._next_enabled(col, col.hover_idx, -1)
                    return True
                if key == pygame.K_DOWN:
                    col.hover_idx = self._next_enabled(col, col.hover_idx, 1)
                    return True
                if key == pygame.K_RETURN:
                    if 0 <= col.hover_idx < len(col.items):
                        item = col.items[col.hover_idx]
                        if item.has_submenu and item.is_enabled:
                            self._open_submenu(col.hover_idx, col)
                        elif item.action and item.is_enabled:
                            self._close_all()
                            item.action()
                    return True

        return False

    # ---- Keyboard navigation helpers --------------------------------------

    def _navigate_bar(self, direction: int) -> None:
        n = len(self._menus)
        if n == 0:
            return
        idx = (self._open_idx + direction) % n
        self._open_top_menu(idx)

    @staticmethod
    def _next_enabled(col: _MenuColumn, current: int,
                      direction: int) -> int:
        n = len(col.items)
        if n == 0:
            return -1
        idx = current
        for _ in range(n):
            idx = (idx + direction) % n
            item = col.items[idx]
            if not item.is_separator and item.is_enabled:
                return idx
        return current

    def _open_submenu(self, parent_idx: int, col: '_MenuColumn | None' = None) -> None:
        if col is None:
            col = self._columns[-1]
        item = col.items[parent_idx]
        if not item.children:
            return
        # Find the depth of the parent column
        try:
            col_depth = self._columns.index(col)
        except ValueError:
            return
        # Avoid re-opening the same submenu
        if (col_depth + 1 < len(self._columns)
                and self._columns[col_depth + 1].title == item.label):
            return
        # Pop any columns deeper than the parent
        while len(self._columns) > col_depth + 1:
            self._columns.pop()
        ir = col.item_rects[parent_idx]
        sub = self._build_column(item.children, ir.right, ir.y, item.label)
        self._columns.append(sub)


# ---------------------------------------------------------------------------
# Scrollable item list — reusable scrolling row list with selection
# ---------------------------------------------------------------------------

def _hue_to_rgb(h: float, s: float = 1.0) -> tuple[int, int, int]:
    """Convert hue (0-1) and saturation to an RGB tuple for UI display."""
    import colorsys
    r, g, b = colorsys.hls_to_rgb(h, 0.5, s)
    return (int(r * 255), int(g * 255), int(b * 255))


_TGT_COLORS: dict[str, tuple[int, int, int]] = {
    "Ch1": _hue_to_rgb(DEFAULT_CHANNEL_HUES[0]),
    "Ch2": _hue_to_rgb(DEFAULT_CHANNEL_HUES[1]),
    "Ch3": _hue_to_rgb(DEFAULT_CHANNEL_HUES[2]),
    "Ch4": _hue_to_rgb(DEFAULT_CHANNEL_HUES[3]),
    "Alpha": (200, 200, 200),
    "none": (80, 80, 80),
}


@dataclass
class ListItem:
    """One row in a :class:`ScrollableItemList`."""
    key: str              # unique id
    display_name: str     # shown label
    tag: str = "none"     # short right-side tag text (target channel, etc.)
    tag_color_key: str = "none"   # lookup in _TGT_COLORS
    timeline_segments: list[tuple[float, float, tuple[int, int, int], int]] = field(default_factory=list)


@dataclass
class ModularSubpanelSpec:
    """Specification for one modular panel inside a scrollable stack."""
    key: str
    title: str
    summary_lines: list[str] = field(default_factory=list)
    expanded: bool = True
    enabled: bool = True
    accent_rgb: tuple[int, int, int] = (120, 140, 200)
    body_height: int = 0
    render_body: Any = None
    payload: Any = None


@dataclass
class SubpanelAddOption:
    key: str
    label: str
    accent_rgb: tuple[int, int, int] = (100, 120, 160)


@dataclass(order=True)
class HierarchicalControlRecord:
    path: tuple[str, ...]
    rect: Any = field(compare=False)
    kind: str = field(compare=False, default="button")
    payload: Any = field(compare=False, default=None)


class HierarchicalControlTable:
    """Hierarchical identity table for controls inside a modular UI stack."""

    def __init__(self) -> None:
        self.records: list[HierarchicalControlRecord] = []

    def clear(self) -> None:
        self.records = []

    def register(
        self,
        path: tuple[str, ...],
        rect: Any,
        *,
        kind: str = "button",
        payload: Any = None,
    ) -> None:
        self.records.append(HierarchicalControlRecord(
            tuple(str(p) for p in path), rect, kind=kind, payload=payload))

    def sorted_records(self) -> list[HierarchicalControlRecord]:
        return sorted(self.records)

    def hit(self, x: int, y: int) -> HierarchicalControlRecord | None:
        for rec in self.records:
            if rec.rect.collidepoint(x, y):
                return rec
        return None


class ScrollableSubpanelList:
    """Reusable scrollable stack of collapsible modular subpanels.

    Each subpanel has a header plus optional body content. Bodies can either be
    rendered from summary text or by a caller-provided render callback.
    """

    TITLE_H = 22
    HEADER_H = 22
    PAD = 6
    BODY_PAD = 6

    def __init__(
        self,
        title: str,
        *,
        max_height: int = 220,
        key_prefix: str = "subpanel",
    ) -> None:
        self.title = title
        self.max_height = max(60, int(max_height))
        self.key_prefix = str(key_prefix)
        self.subpanels: list[ModularSubpanelSpec] = []
        self.selected_key: str | None = None
        self.scroll_y: int = 0
        self._rendered_h: int = 0
        self._viewport_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._header_rects: dict[str, pygame.Rect] = {}
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._content_h: int = 0
        self.add_options: list[SubpanelAddOption] = []
        self.show_remove_button: bool = False
        self._selected_add_option_idx: int = 0
        self._add_dropdown_rect: pygame.Rect | None = None
        self._add_confirm_rect: pygame.Rect | None = None
        self._add_button_rects: dict[str, pygame.Rect] = {}  # kept for compat
        self._remove_button_rect: pygame.Rect | None = None
        self.control_table = HierarchicalControlTable()

    def set_subpanels(self, subpanels: list[ModularSubpanelSpec]) -> None:
        self.subpanels = list(subpanels)
        keys = {sp.key for sp in self.subpanels}
        if self.selected_key not in keys:
            self.selected_key = self.subpanels[0].key if self.subpanels else None
        self._clamp_scroll()

    def set_add_options(self, options: list[SubpanelAddOption]) -> None:
        self.add_options = list(options)

    def _summary_height(
        self,
        spec: ModularSubpanelSpec,
        font: pygame.font.Font,
        body_w: int,
    ) -> int:
        if not spec.summary_lines:
            return 0
        line_h = max(font.get_linesize(), self.HEADER_H - 4)
        return len(spec.summary_lines) * line_h + 2 * self.BODY_PAD

    def _body_height(
        self,
        spec: ModularSubpanelSpec,
        font: pygame.font.Font,
        body_w: int,
    ) -> int:
        if not spec.expanded:
            return 0
        if spec.render_body is not None:
            return max(0, int(spec.body_height))
        return self._summary_height(spec, font, body_w)

    def _total_content_height(self, font: pygame.font.Font, body_w: int) -> int:
        total = 0
        for spec in self.subpanels:
            total += self.HEADER_H + self._body_height(spec, font, body_w)
        return total

    def _clamp_scroll(self) -> None:
        max_scroll = max(0, self._content_h - self.max_height)
        self.scroll_y = max(0, min(int(self.scroll_y), int(max_scroll)))

    def render(
        self,
        surf: pygame.Surface,
        font: pygame.font.Font,
        x: int,
        y: int,
        w: int,
    ) -> int:
        start_y = y
        self._header_rects = {}
        self._item_map = {}
        self._add_button_rects = {}
        self._remove_button_rect = None
        self.control_table.clear()

        ttl = font.render(f"\u2500\u2500 {self.title} \u2500\u2500",
                          True, (180, 180, 180))
        surf.blit(ttl, (x + self.PAD, y + 2))
        y += self.TITLE_H + 2

        viewport_h = self.max_height
        viewport = pygame.Rect(x + self.PAD, y, w - 2 * self.PAD, viewport_h)
        pygame.draw.rect(surf, (34, 36, 44), viewport)
        pygame.draw.rect(surf, (58, 62, 74), viewport, 1)
        self._viewport_rect = viewport

        body_w = max(1, viewport.w)
        self._content_h = self._total_content_height(font, body_w)
        self._clamp_scroll()
        content_h = max(viewport_h, self._content_h)
        content = pygame.Surface((body_w, content_h), pygame.SRCALPHA)
        content.fill((0, 0, 0, 0))

        cy = 0
        line_h = max(font.get_linesize(), self.HEADER_H - 4)
        for spec in self.subpanels:
            hdr = pygame.Rect(0, cy, body_w, self.HEADER_H)
            is_selected = (spec.key == self.selected_key)
            base = (48, 52, 66) if is_selected else (42, 46, 56)
            if not spec.enabled:
                base = (36, 36, 40)
            pygame.draw.rect(content, base, hdr)
            pygame.draw.rect(content, spec.accent_rgb, hdr, 1)
            arrow = "\u25bc" if spec.expanded else "\u25b6"
            title_color = (230, 230, 230) if spec.enabled else (120, 120, 120)
            txt = font.render(f" {arrow} {spec.title}", True, title_color)
            content.blit(txt, (4, cy + 3))
            hit = pygame.Rect(
                viewport.x + hdr.x,
                viewport.y + hdr.y - self.scroll_y,
                hdr.w,
                hdr.h,
            )
            self._header_rects[spec.key] = hit
            self._item_map[f"{self.key_prefix}:{spec.key}:header"] = (hit, spec)
            cy += self.HEADER_H

            body_h = self._body_height(spec, font, body_w)
            if body_h <= 0:
                continue
            body_rect = pygame.Rect(0, cy, body_w, body_h)
            pygame.draw.rect(content, (28, 30, 38), body_rect)
            pygame.draw.rect(content, (50, 54, 68), body_rect, 1)
            if spec.render_body is not None:
                def _register_body_control(
                    path: tuple[str, ...],
                    rect: Any,
                    *,
                    kind: str = "button",
                    payload: Any = None,
                ) -> None:
                    hit = pygame.Rect(
                        viewport.x + rect.x,
                        viewport.y + rect.y - self.scroll_y,
                        rect.w,
                        rect.h,
                    )
                    self.control_table.register(path, hit, kind=kind, payload=payload)
                spec.render_body(
                    content, font, body_rect, spec, self._item_map, _register_body_control)
            else:
                ty = cy + self.BODY_PAD
                for line in spec.summary_lines:
                    if not line:
                        ty += line_h
                        continue
                    st = font.render(line, True, (180, 188, 196))
                    content.blit(st, (self.BODY_PAD, ty))
                    ty += line_h
            cy += body_h

        prev_clip = surf.get_clip()
        surf.set_clip(viewport)
        surf.blit(content, (viewport.x, viewport.y - self.scroll_y))
        surf.set_clip(prev_clip)

        if self._content_h > viewport_h:
            track = pygame.Rect(viewport.right - 6, viewport.y + 2, 4, viewport_h - 4)
            pygame.draw.rect(surf, (46, 48, 56), track)
            thumb_h = max(24, int(track.h * viewport_h / max(self._content_h, 1)))
            max_scroll = max(1, self._content_h - viewport_h)
            thumb_y = track.y + int((track.h - thumb_h) * self.scroll_y / max_scroll)
            thumb = pygame.Rect(track.x, thumb_y, track.w, thumb_h)
            pygame.draw.rect(surf, (110, 120, 145), thumb)

        footer_y = y + viewport_h + 4
        footer_h = self._render_footer(surf, font, x, footer_y, w)

        self._rendered_h = (y - start_y) + viewport_h + 2 + footer_h
        return self._rendered_h

    def _render_footer(
        self,
        surf: pygame.Surface,
        font: pygame.font.Font,
        x: int,
        footer_y: int,
        w: int,
    ) -> int:
        """Render the dropdown+Add engine footer. Returns height consumed."""
        self._add_dropdown_rect = None
        self._add_confirm_rect = None
        self._add_button_rects = {}
        self._remove_button_rect = None
        if not self.add_options and not self.show_remove_button:
            return 0
        btn_h = self.HEADER_H
        bx = x + self.PAD
        footer_h = btn_h + 2
        if self.show_remove_button:
            rw = max(80, min(120, w // 4))
            rr = pygame.Rect(bx, footer_y, rw, btn_h)
            pygame.draw.rect(surf, (84, 56, 56), rr)
            pygame.draw.rect(surf, (132, 88, 88), rr, 1)
            rt = font.render("Remove Sel", True, (235, 220, 220))
            surf.blit(rt, (rr.x + 6, rr.y + 3))
            self._remove_button_rect = rr
            bx = rr.right + 6
        if self.add_options:
            self._selected_add_option_idx = max(
                0, min(self._selected_add_option_idx, len(self.add_options) - 1))
            opt = self.add_options[self._selected_add_option_idx]
            avail_w = (x + w - self.PAD) - bx - 6
            dd_w = max(70, avail_w * 2 // 3)
            confirm_w = max(36, avail_w - dd_w - 4)
            dd_rect = pygame.Rect(bx, footer_y, dd_w, btn_h)
            pygame.draw.rect(surf, (38, 42, 54), dd_rect)
            pygame.draw.rect(surf, opt.accent_rgb, dd_rect, 1)
            dd_txt = font.render(f"◄ {opt.label} ►", True, (220, 226, 235))
            surf.blit(dd_txt, (dd_rect.x + 6, dd_rect.y + 3))
            self._add_dropdown_rect = dd_rect
            add_rect = pygame.Rect(dd_rect.right + 4, footer_y, confirm_w, btn_h)
            pygame.draw.rect(surf, (44, 68, 44), add_rect)
            pygame.draw.rect(surf, (80, 140, 80), add_rect, 1)
            add_txt = font.render("+ Add", True, (180, 240, 180))
            surf.blit(add_txt, (add_rect.x + add_rect.w // 2 - add_txt.get_width() // 2,
                                add_rect.y + 3))
            self._add_confirm_rect = add_rect
        return footer_h

    def handle_click(self, lx: int, ly: int) -> str | None:
        if self._remove_button_rect and self._remove_button_rect.collidepoint(lx, ly):
            return f"remove:{self.selected_key or ''}"
        if self._add_dropdown_rect and self._add_dropdown_rect.collidepoint(lx, ly):
            if self.add_options:
                self._selected_add_option_idx = (
                    self._selected_add_option_idx + 1) % len(self.add_options)
            return "add_cycle"
        if self._add_confirm_rect and self._add_confirm_rect.collidepoint(lx, ly):
            if self.add_options:
                opt = self.add_options[self._selected_add_option_idx]
                return f"add:{opt.key}"
            return "add_cycle"
        # legacy: individual add-button rects (unused when dropdown active)
        for opt_key, rect in self._add_button_rects.items():
            if rect.collidepoint(lx, ly):
                return f"add:{opt_key}"
        if not self._viewport_rect.collidepoint(lx, ly):
            return None
        rec = self.control_table.hit(lx, ly)
        if rec is not None:
            return "control:" + "|".join(rec.path)
        for key, rect in self._header_rects.items():
            if rect.collidepoint(lx, ly):
                self.selected_key = key
                for spec in self.subpanels:
                    if spec.key == key:
                        spec.expanded = not spec.expanded
                        break
                return key
        return ""

    def handle_scroll(self, direction: int) -> bool:
        if self._content_h <= self.max_height:
            return False
        self.scroll_y += int(direction) * 28
        self._clamp_scroll()
        return True

class ScrollableItemList:
    """Generic scrollable list widget rendered onto a parent surface.

    Supports arbitrary item count, scroll offset, single selection, and
    per-item target-colour tag.  Designed to be embedded inside a larger
    panel surface — all coordinates are surface-local.

    The ``▲ more`` / ``▼ more`` indicators are clickable buttons that
    scroll by one page.  Mouse-wheel scrolling works anywhere in the list.
    """

    ROW_H = 22
    MORE_H = 18          # height of a clickable more-indicator row
    PAD = 6

    def __init__(self, title: str, max_visible: int = 8) -> None:
        self.title = title
        self.items: list[ListItem] = []
        self.selected_idx: int = 0
        self.scroll_offset: int = 0
        self.max_visible = max_visible
        self._row_rects: list[pygame.Rect] = []  # surface-local rects
        self._more_up_rect: pygame.Rect | None = None
        self._more_down_rect: pygame.Rect | None = None
        self._rendered_h: int = 0                 # height consumed in last render

    @property
    def needs_scroll(self) -> bool:
        return len(self.items) > self.max_visible

    @property
    def visible_count(self) -> int:
        return min(len(self.items), self.max_visible)

    def clamp(self) -> None:
        """Ensure selection and scroll offset are within bounds."""
        n = len(self.items)
        if n == 0:
            self.selected_idx = 0
            self.scroll_offset = 0
            return
        self.selected_idx = max(0, min(self.selected_idx, n - 1))
        max_off = max(0, n - self.max_visible)
        self.scroll_offset = max(0, min(self.scroll_offset, max_off))

    def scroll_to_selected(self) -> None:
        """Adjust scroll offset so the selected item is visible."""
        if self.selected_idx < self.scroll_offset:
            self.scroll_offset = self.selected_idx
        if self.selected_idx >= self.scroll_offset + self.max_visible:
            self.scroll_offset = self.selected_idx - self.max_visible + 1

    def render(self, surf: pygame.Surface, font: pygame.font.Font,
               x: int, y: int, w: int) -> int:
        """Draw the list onto *surf* starting at *(x, y)*.

        Returns the total height consumed (including title).
        """
        self._row_rects = []
        self._more_up_rect = None
        self._more_down_rect = None
        pad = self.PAD
        start_y = y

        # Title
        ttl = font.render(f"\u2500\u2500 {self.title} \u2500\u2500",
                           True, (180, 180, 180))
        surf.blit(ttl, (pad, y + 2))
        y += self.ROW_H + 2

        if not self.items:
            dim = font.render("(empty)", True, (100, 100, 100))
            surf.blit(dim, (pad + 4, y + 3))
            y += self.ROW_H + 2
            self._rendered_h = y - start_y
            return self._rendered_h

        self.clamp()
        vis_start = self.scroll_offset
        vis_end = min(len(self.items), vis_start + self.max_visible)

        # Scroll-up button
        if vis_start > 0:
            btn = pygame.Rect(pad, y, w - 2 * pad, self.MORE_H)
            pygame.draw.rect(surf, (40, 40, 55), btn)
            pygame.draw.rect(surf, (60, 60, 80), btn, 1)
            arr = font.render(f"\u25b2 more ({vis_start})", True, (140, 140, 170))
            surf.blit(arr, (w // 2 - arr.get_width() // 2, y + 1))
            self._more_up_rect = btn
            y += self.MORE_H + 2

        for idx in range(vis_start, vis_end):
            item = self.items[idx]
            rect = pygame.Rect(pad, y, w - 2 * pad, self.ROW_H)
            if idx == self.selected_idx:
                pygame.draw.rect(surf, (50, 50, 70), rect)
            pygame.draw.rect(surf, (60, 60, 80), rect, 1)
            if item.timeline_segments:
                self._render_timeline(surf, rect, item.timeline_segments)
            txt = font.render(item.display_name, True, (200, 200, 200))
            surf.blit(txt, (pad + 4, y + 3))
            color = _TGT_COLORS.get(item.tag_color_key, (80, 80, 80))
            arrow = font.render(f"\u2192 {item.tag}", True, color)
            surf.blit(arrow, (w - 60, y + 3))
            self._row_rects.append(rect)
            y += self.ROW_H + 2

        # Scroll-down button
        remaining = len(self.items) - vis_end
        if remaining > 0:
            btn = pygame.Rect(pad, y, w - 2 * pad, self.MORE_H)
            pygame.draw.rect(surf, (40, 40, 55), btn)
            pygame.draw.rect(surf, (60, 60, 80), btn, 1)
            arr = font.render(f"\u25bc more ({remaining})", True, (140, 140, 170))
            surf.blit(arr, (w // 2 - arr.get_width() // 2, y + 1))
            self._more_down_rect = btn
            y += self.MORE_H + 2

        self._rendered_h = y - start_y
        return self._rendered_h

    @staticmethod
    def _render_timeline(
        surf: pygame.Surface,
        rect: Any,
        segments: list[tuple[float, float, tuple[int, int, int], int]],
    ) -> None:
        bar = pygame.Rect(rect.x + 4, rect.y + rect.h - 7, max(10, rect.w - 70), 4)
        pygame.draw.rect(surf, (28, 30, 36), bar)
        for lo, hi, rgb, alpha in segments:
            x0 = bar.x + int(max(0.0, min(1.0, lo)) * bar.w)
            x1 = bar.x + int(max(0.0, min(1.0, hi)) * bar.w)
            if x1 <= x0:
                x1 = min(bar.right, x0 + 1)
            try:
                pygame.draw.rect(
                    surf,
                    (int(rgb[0]), int(rgb[1]), int(rgb[2]), int(alpha)),
                    pygame.Rect(x0, bar.y, max(1, x1 - x0), bar.h),
                )
            except Exception:
                pygame.draw.rect(
                    surf,
                    rgb,
                    pygame.Rect(x0, bar.y, max(1, x1 - x0), bar.h),
                )
        pygame.draw.rect(surf, (70, 74, 84), bar, 1)

    def handle_click(self, lx: int, ly: int) -> int | None:
        """Test click at surface-local *(lx, ly)*.

        Returns the **absolute** item index if a row was hit, else ``None``.
        Clicking the ``▲ more`` / ``▼ more`` buttons scrolls by one page
        and returns ``-1`` (consumed but no selection change).
        """
        # More-up button
        if self._more_up_rect and self._more_up_rect.collidepoint(lx, ly):
            self.scroll_offset = max(0, self.scroll_offset - self.max_visible)
            return -1
        # More-down button
        if self._more_down_rect and self._more_down_rect.collidepoint(lx, ly):
            max_off = max(0, len(self.items) - self.max_visible)
            self.scroll_offset = min(max_off,
                                     self.scroll_offset + self.max_visible)
            return -1
        # Row items
        for vis_i, rect in enumerate(self._row_rects):
            if rect.collidepoint(lx, ly):
                idx = self.scroll_offset + vis_i
                self.selected_idx = idx
                return idx
        return None

    def handle_scroll(self, direction: int) -> bool:
        """Scroll by *direction* rows (-1 = up, +1 = down).

        Returns True if the list consumed the event.
        """
        if not self.needs_scroll:
            return False
        self.scroll_offset = max(
            0, min(self.scroll_offset + direction,
                   len(self.items) - self.max_visible))
        return True


# ---------------------------------------------------------------------------
# Tree item list — collapsible category tree for data sources
# ---------------------------------------------------------------------------

@dataclass
class TreeCategory:
    """One collapsible category in a :class:`TreeItemList`."""
    key: str
    label: str
    expanded: bool = True


class TreeItemList:
    """Scrollable tree with collapsible category headers.

    Items are grouped by category. Categories can be expanded/collapsed.
    Unavailable items appear greyed out and cannot be selected.
    """

    ROW_H = 22
    CAT_H = 24
    MORE_H = 18
    PAD = 6
    INDENT = 16  # extra indent for items under a category

    def __init__(self, title: str, max_visible: int = 12) -> None:
        self.title = title
        self.categories: list[TreeCategory] = []
        self.items: list[ListItem] = []
        # Map item key → category key
        self.item_categories: dict[str, str] = {}
        # Map item key → available flag
        self.item_available: dict[str, bool] = {}
        self.selected_idx: int = 0
        self.scroll_offset: int = 0
        self.max_visible = max_visible
        self._row_rects: list[pygame.Rect] = []
        self._cat_rects: dict[str, pygame.Rect] = {}
        self._flat_indices: list[int] = []  # maps visible row → items index
        self._more_up_rect: pygame.Rect | None = None
        self._more_down_rect: pygame.Rect | None = None
        self._rendered_h: int = 0

    def _build_flat_list(self) -> list[tuple[str, int | None]]:
        """Build a flat list of (type, data) tuples for rendering.

        Returns list of ("cat", cat_idx) and ("item", item_idx).
        """
        flat: list[tuple[str, int | None]] = []
        cat_items: dict[str, list[int]] = {c.key: [] for c in self.categories}
        for i, item in enumerate(self.items):
            cat_key = self.item_categories.get(item.key, "")
            if cat_key in cat_items:
                cat_items[cat_key].append(i)

        for ci, cat in enumerate(self.categories):
            items_in_cat = cat_items.get(cat.key, [])
            if not items_in_cat:
                continue
            flat.append(("cat", ci))
            if cat.expanded:
                for ii in items_in_cat:
                    flat.append(("item", ii))
        return flat

    @property
    def needs_scroll(self) -> bool:
        return len(self._build_flat_list()) > self.max_visible

    def clamp(self) -> None:
        n = len(self.items)
        if n == 0:
            self.selected_idx = 0
            self.scroll_offset = 0
            return
        self.selected_idx = max(0, min(self.selected_idx, n - 1))
        flat = self._build_flat_list()
        max_off = max(0, len(flat) - self.max_visible)
        self.scroll_offset = max(0, min(self.scroll_offset, max_off))

    def scroll_to_selected(self) -> None:
        flat = self._build_flat_list()
        # Find the flat index of the selected item
        flat_idx = -1
        for fi, (ftype, fdata) in enumerate(flat):
            if ftype == "item" and fdata == self.selected_idx:
                flat_idx = fi
                break
        if flat_idx < 0:
            return
        if flat_idx < self.scroll_offset:
            self.scroll_offset = flat_idx
        if flat_idx >= self.scroll_offset + self.max_visible:
            self.scroll_offset = flat_idx - self.max_visible + 1

    def render(self, surf: pygame.Surface, font: pygame.font.Font,
               x: int, y: int, w: int) -> int:
        self._row_rects = []
        self._cat_rects = {}
        self._flat_indices = []
        self._more_up_rect = None
        self._more_down_rect = None
        pad = self.PAD
        start_y = y

        # Title
        ttl = font.render(f"\u2500\u2500 {self.title} \u2500\u2500",
                           True, (180, 180, 180))
        surf.blit(ttl, (pad, y + 2))
        y += self.ROW_H + 2

        flat = self._build_flat_list()
        if not flat:
            dim = font.render("(no sources)", True, (100, 100, 100))
            surf.blit(dim, (pad + 4, y + 3))
            y += self.ROW_H + 2
            self._rendered_h = y - start_y
            return self._rendered_h

        self.clamp()
        vis_start = self.scroll_offset
        vis_end = min(len(flat), vis_start + self.max_visible)

        # Scroll-up
        if vis_start > 0:
            btn = pygame.Rect(pad, y, w - 2 * pad, self.MORE_H)
            pygame.draw.rect(surf, (40, 40, 55), btn)
            pygame.draw.rect(surf, (60, 60, 80), btn, 1)
            arr = font.render(f"\u25b2 more ({vis_start})", True, (140, 140, 170))
            surf.blit(arr, (w // 2 - arr.get_width() // 2, y + 1))
            self._more_up_rect = btn
            y += self.MORE_H + 2

        for fi in range(vis_start, vis_end):
            ftype, fdata = flat[fi]
            if ftype == "cat":
                cat = self.categories[fdata]
                rect = pygame.Rect(pad, y, w - 2 * pad, self.CAT_H)
                pygame.draw.rect(surf, (38, 38, 48), rect)
                pygame.draw.rect(surf, (70, 70, 90), rect, 1)
                arrow = "\u25bc" if cat.expanded else "\u25b6"
                ct = font.render(f"{arrow} {cat.label}", True,
                                 (200, 200, 220))
                surf.blit(ct, (pad + 4, y + 4))
                self._cat_rects[cat.key] = rect
                y += self.CAT_H + 1
            elif ftype == "item":
                item = self.items[fdata]
                avail = self.item_available.get(item.key, True)
                rect = pygame.Rect(pad + self.INDENT, y,
                                   w - 2 * pad - self.INDENT, self.ROW_H)
                if fdata == self.selected_idx and avail:
                    pygame.draw.rect(surf, (50, 50, 70), rect)
                pygame.draw.rect(surf, (55, 55, 68) if avail
                                 else (40, 40, 45), rect, 1)
                tc = (200, 200, 200) if avail else (80, 80, 90)
                txt = font.render(item.display_name, True, tc)
                surf.blit(txt, (pad + self.INDENT + 4, y + 3))
                if avail:
                    color = _TGT_COLORS.get(item.tag_color_key, (80, 80, 80))
                    arrow = font.render(f"\u2192 {item.tag}", True, color)
                else:
                    arrow = font.render("\u2014", True, (60, 60, 70))
                surf.blit(arrow, (w - 60, y + 3))
                self._row_rects.append(rect)
                self._flat_indices.append(fdata)
                y += self.ROW_H + 2

        # Scroll-down
        remaining = len(flat) - vis_end
        if remaining > 0:
            btn = pygame.Rect(pad, y, w - 2 * pad, self.MORE_H)
            pygame.draw.rect(surf, (40, 40, 55), btn)
            pygame.draw.rect(surf, (60, 60, 80), btn, 1)
            arr = font.render(f"\u25bc more ({remaining})", True, (140, 140, 170))
            surf.blit(arr, (w // 2 - arr.get_width() // 2, y + 1))
            self._more_down_rect = btn
            y += self.MORE_H + 2

        self._rendered_h = y - start_y
        return self._rendered_h

    def handle_click(self, lx: int, ly: int) -> int | None:
        # Category headers — toggle expand/collapse
        for cat_key, rect in self._cat_rects.items():
            if rect.collidepoint(lx, ly):
                for cat in self.categories:
                    if cat.key == cat_key:
                        cat.expanded = not cat.expanded
                        break
                return -1  # consumed, no selection change

        # More buttons
        if self._more_up_rect and self._more_up_rect.collidepoint(lx, ly):
            self.scroll_offset = max(0, self.scroll_offset - self.max_visible)
            return -1
        if self._more_down_rect and self._more_down_rect.collidepoint(lx, ly):
            flat = self._build_flat_list()
            max_off = max(0, len(flat) - self.max_visible)
            self.scroll_offset = min(max_off,
                                     self.scroll_offset + self.max_visible)
            return -1

        # Item rows
        for vi, rect in enumerate(self._row_rects):
            if rect.collidepoint(lx, ly):
                idx = self._flat_indices[vi]
                avail = self.item_available.get(
                    self.items[idx].key, True)
                if not avail:
                    return -1  # unavailable — consume but don't select
                self.selected_idx = idx
                return idx
        return None

    def handle_scroll(self, direction: int) -> bool:
        flat = self._build_flat_list()
        if len(flat) <= self.max_visible:
            return False
        max_off = max(0, len(flat) - self.max_visible)
        self.scroll_offset = max(0, min(self.scroll_offset + direction,
                                        max_off))
        return True


# ---------------------------------------------------------------------------
# Synthesis product — one output from the synthesizer
# ---------------------------------------------------------------------------

PHASE_MODES = ["original", "griffin_lim", "zero_phase", "freq_carrier"]
PHASE_LABELS = {
    "original":    "Original Phase",
    "griffin_lim":  "Griffin-Lim",
    "zero_phase":  "Zero Phase",
    "freq_carrier": "Freq Carrier",
}


@dataclass
class SynthJob:
    """One synthesis job in the async queue."""
    job_id: int
    label: str
    status: str = "queued"          # queued | running | done | error
    source_type: str = "cqt"       # cqt | filterbank | mixed
    params: dict = field(default_factory=dict)
    result_stereo: np.ndarray | None = None   # (N, 2) int16
    duration: float = 0.0
    view_t0: float = 0.0
    view_t1: float = 0.0
    error_msg: str = ""
    submitted_at: float = 0.0
    completed_at: float = 0.0


# ---------------------------------------------------------------------------
# Panel base class — common interface for dockable side panels
# ---------------------------------------------------------------------------

class Panel:
    """Abstract base for a dockable side panel.

    Subclasses must implement :meth:`render` and :meth:`handle_event`.
    """

    PANEL_W = 280
    _top_offset: int = 0   # set by the viewer (e.g. menu-bar height)

    def __init__(self, *, title: str = "Panel",
                 side: str = "right") -> None:
        self.title = title
        self.side: str = side          # "left" or "right"
        self.visible: bool = True
        self.font: pygame.font.Font | None = None
        self._panel_scroll_y: int = 0  # vertical scroll offset for panel content
        self._content_h: int = 0       # total height of last rendered content

    def _ensure_font(self) -> None:
        if self.font is None:
            pygame.font.init()
            self.font = pygame.font.SysFont("consolas", 13)

    @property
    def panel_rect(self) -> pygame.Rect:
        sw = pygame.display.get_surface().get_width()
        sh = pygame.display.get_surface().get_height()
        top = self._top_offset
        if self.side == "left":
            return pygame.Rect(0, top, self.PANEL_W, sh - top)
        return pygame.Rect(sw - self.PANEL_W, top, self.PANEL_W, sh - top)

    def _clamp_panel_scroll(self) -> None:
        """Keep panel scroll within bounds."""
        pr = self.panel_rect
        max_scroll = max(0, self._content_h - pr.h)
        self._panel_scroll_y = max(0, min(self._panel_scroll_y, max_scroll))

    def _apply_panel_scroll(self, full_surf: pygame.Surface) -> pygame.Surface:
        """Clip *full_surf* to the available panel height, applying scroll."""
        pr = self.panel_rect
        self._content_h = full_surf.get_height()
        self._clamp_panel_scroll()
        avail_h = pr.h
        if self._content_h <= avail_h:
            return full_surf
        clipped = pygame.Surface((full_surf.get_width(), avail_h),
                                 pygame.SRCALPHA)
        clipped.blit(full_surf, (0, -self._panel_scroll_y))
        # Draw a thin scrollbar track on the right edge
        w = full_surf.get_width()
        bar_w = 4
        track_h = avail_h
        thumb_frac = avail_h / self._content_h
        thumb_h = max(16, int(track_h * thumb_frac))
        max_scroll = self._content_h - avail_h
        thumb_y = int((track_h - thumb_h) * self._panel_scroll_y
                      / max(max_scroll, 1))
        pygame.draw.rect(clipped, (60, 60, 70),
                         pygame.Rect(w - bar_w, 0, bar_w, track_h))
        pygame.draw.rect(clipped, (120, 120, 150),
                         pygame.Rect(w - bar_w, thumb_y, bar_w, thumb_h))
        return clipped

    def _handle_panel_wheel(self, event: pygame.event.Event) -> bool:
        """Scroll panel content on mouse wheel. Call from handle_event."""
        if event.type != MOUSEWHEEL:
            return False
        mx, my = pygame.mouse.get_pos()
        pr = self.panel_rect
        if not pr.collidepoint(mx, my):
            return False
        self._panel_scroll_y -= event.y * 28
        self._clamp_panel_scroll()
        return True

    def render(self) -> pygame.Surface | None:
        raise NotImplementedError

    def handle_event(self, event: pygame.event.Event) -> bool:
        raise NotImplementedError

    def render_dropdown_overlay(self) -> pygame.Surface | None:
        return None


# ---------------------------------------------------------------------------
# Curve helpers for the plot widget
# ---------------------------------------------------------------------------

def _apply_curve(xs: np.ndarray, norm_mode: int,
                 gamma: float, scale: float) -> np.ndarray:
    """Replicate the GLSL applyNorm → pow(v,gamma)*scale pipeline on CPU."""
    if norm_mode == 1:  # dB
        safe = np.maximum(xs, 1e-12)
        db = 10.0 * np.log10(safe)
        normed = np.clip((db + 60.0) / 60.0, 0.0, 1.0)
    else:  # linear (0) or rank_order (2) — passthrough
        normed = np.clip(xs, 0.0, 1.0)
    return np.clip(np.power(normed, gamma) * scale, 0.0, 1.0).astype(np.float32)


def _apply_curve_unclipped(xs: np.ndarray, norm_mode: int,
                           gamma: float, scale: float) -> np.ndarray:
    """Like _apply_curve but without final [0,1] clamp — preserves HDR range.

    The normalization step still maps the domain, but the gamma*scale
    output is left unbounded so the curves plot can show where values
    exceed the normal [0,1] display range.
    """
    if norm_mode == 1:  # dB
        safe = np.maximum(xs, 1e-12)
        db = 10.0 * np.log10(safe)
        normed = (db + 60.0) / 60.0   # no clamp
    else:
        normed = xs  # no clamp
    return (np.power(np.maximum(normed, 0.0), gamma) * scale).astype(np.float32)


def _hdr_normalize(ys: np.ndarray, gd: "GlobalDefaults",
                   auto_lo: float = 0.0, auto_hi: float = 1.0) -> np.ndarray:
    """Apply the HDR normalizer to pre-clip post-blend values.

    Maps from the auto-detected input range [auto_lo, auto_hi]
    into [hdr_output_lo, hdr_output_hi] using the selected tone-mapping
    curve.  Operates on raw unclipped values.
    """
    mode = gd.hdr_normalizer
    lo_in = auto_lo
    hi_in = auto_hi
    lo_out = gd.hdr_output_lo
    hi_out = gd.hdr_output_hi
    span_in = hi_in - lo_in if abs(hi_in - lo_in) > 1e-12 else 1.0
    span_out = hi_out - lo_out

    if mode == 0:  # None — raw passthrough
        return ys

    # Remap into [0, 1] input space
    t = (ys - lo_in) / span_in

    if mode == 1:  # Clamp
        t = np.clip(t, 0.0, 1.0)
    elif mode == 2:  # Reinhard
        t = np.maximum(t, 0.0)
        t = t / (1.0 + t)
    elif mode == 3:  # Sigmoid
        t = 1.0 / (1.0 + np.exp(-6.0 * (t - 0.5)))
    elif mode == 4:  # Linear Compress
        t = np.clip(t, 0.0, 1.0)

    # Map to output range
    return (lo_out + t * span_out).astype(np.float32)


def _jitter_color(base: tuple[int, int, int],
                  idx: int) -> tuple[int, int, int]:
    """Shift brightness for the *idx*-th duplicate on the same target."""
    if idx == 0:
        return base
    shift = ((-1) ** idx) * (18 * ((idx + 1) // 2))
    return (max(0, min(255, base[0] + shift)),
            max(0, min(255, base[1] + shift)),
            max(0, min(255, base[2] + shift)))


# ---------------------------------------------------------------------------
# GUI Panel — per-field tab interface
# ---------------------------------------------------------------------------

class FieldTabPanel(Panel):
    """Panel with a tree of data fields grouped by source category,
    per-field controls, global defaults, and output controls.

    Data sources are displayed in a collapsible tree with categories
    (CQT, Filterbank, Wavelet).  Unavailable sources appear greyed out.
    """

    PANEL_W = 280
    ROW_H = 22
    PAD = 6

    def __init__(self, fields: list[FieldSource],
                 configs: list[FieldConfig],
                 global_defaults: GlobalDefaults,
                 *, side: str = "right") -> None:
        super().__init__(title="Fields", side=side)
        self.fields = fields
        self.configs = configs
        self.global_defaults = global_defaults
        self.selected_idx = 0
        self._prev_selected_idx: int = -1
        self._active_dropdown: str | None = None
        self._dropdown_opts: list[str] = []
        self._dropdown_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._dropdown_item_rects: list[pygame.Rect] = []
        self._dragging: str | None = None
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self.on_save_view_png16: Any = None
        self.on_export_resize: Any = None   # callable(w, h) -> str | None
        self._export_resize_preset: str = _EXPORT_PRESETS[0]
        self._status_msg: str = ""

        # Data-field tree list (top section) — grouped by category
        self.data_list = TreeItemList("Data Sources", max_visible=14)
        self._sync_data_list()

        # Plot widget (bottom section — shows normalised data curves)
        self.plot = PlotWidget()
        self.plot.title = "Data Curves"
        self.plot.y_min = None  # auto-range to show full HDR extent
        self.plot.y_max = None
        self.plot.clip_lo = 0.0
        self.plot.clip_hi = 1.0
        self._plot_h: int = 140  # pixel height of the plot box

    def _sync_data_list(self) -> None:
        """Rebuild data_list items and categories from fields/configs."""
        # Build categories from _FIELD_CATEGORIES
        cats: list[TreeCategory] = []
        seen_cats: set[str] = set()
        for fs in self.fields:
            if fs.category not in seen_cats:
                seen_cats.add(fs.category)
        for cat_key, cat_label in _FIELD_CATEGORIES:
            if cat_key in seen_cats:
                # Preserve existing expanded state if category exists
                existing = None
                for c in self.data_list.categories:
                    if c.key == cat_key:
                        existing = c
                        break
                if existing:
                    cats.append(existing)
                else:
                    cats.append(TreeCategory(key=cat_key, label=cat_label))
        self.data_list.categories = cats

        items: list[ListItem] = []
        item_categories: dict[str, str] = {}
        item_available: dict[str, bool] = {}
        for i, fs in enumerate(self.fields):
            cfg = self.configs[i]
            tgt_text = TARGET_LABELS[TARGET_VALUES.index(cfg.target)] if fs.available else "—"
            items.append(ListItem(
                key=fs.name,
                display_name=fs.display_name,
                tag=tgt_text,
                tag_color_key=tgt_text if fs.available else "none",
            ))
            item_categories[fs.name] = fs.category
            item_available[fs.name] = fs.available
        self.data_list.items = items
        self.data_list.item_categories = item_categories
        self.data_list.item_available = item_available
        self.data_list.selected_idx = self.selected_idx

    _CURVE_XS = np.linspace(0.0, 1.0, 256, dtype=np.float32)

    def _rebuild_plot_series(self) -> None:
        """Recompute transfer-curve series from current field configs.

        Uses unclipped curve values so the plot shows exactly where data
        exceeds [0,1].  If an HDR normalizer is active, a second
        (normalized) series is overlaid.  Clips show as red segments.
        """
        xs = self._CURVE_XS
        gd = self.global_defaults
        target_seen: dict[int, int] = {}  # target → count seen so far
        series: list[PlotSeries] = []

        xs_hdr = xs

        for i, (fs, cfg) in enumerate(zip(self.fields, self.configs)):
            if cfg.target < 0:
                continue
            norm_mode = cfg.norm_mode if not cfg.use_global else gd.norm_mode
            gamma = cfg.gamma if not cfg.use_global else gd.gamma
            scale = cfg.scale if not cfg.use_global else gd.scale

            # Unclipped curve — shows true output before any clamping
            ys_raw = _apply_curve_unclipped(xs_hdr, norm_mode, gamma, scale)

            tgt_label = TARGET_LABELS[TARGET_VALUES.index(cfg.target)]
            base_color = _TGT_COLORS.get(tgt_label, (180, 180, 180))
            n = target_seen.get(cfg.target, 0)
            target_seen[cfg.target] = n + 1
            color = _jitter_color(base_color, n)

            series.append(PlotSeries(
                key=fs.name,
                label=fs.display_name,
                color=color,
                line=True,
                data_x=xs_hdr,
                data_y=ys_raw,
                clip_color=(200, 50, 50),  # red for clipped segments
            ))

            # If HDR normalizer is active, add the normalized curve
            if gd.hdr_normalizer > 0:
                ys_norm = _hdr_normalize(ys_raw, gd,
                                         float(ys_raw.min()),
                                         float(ys_raw.max()))
                series.append(PlotSeries(
                    key=f"{fs.name}_hdr",
                    label=f"{fs.display_name} HDR",
                    color=_jitter_color(
                        (min(255, color[0] + 40),
                         min(255, color[1] + 40),
                         min(255, color[2] + 40)), 0),
                    line=True,
                    dots=False,
                    data_x=xs_hdr,
                    data_y=ys_norm,
                ))

        # Update clip boundary lines based on output range
        self.plot.clip_lo = gd.hdr_output_lo
        self.plot.clip_hi = gd.hdr_output_hi
        self.plot.series = series

    # ---- Rendering --------------------------------------------------------

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._item_map = {}

        # Keep list selections in sync — scroll only when selection changes
        sel_changed = (self.selected_idx != self._prev_selected_idx)
        self._prev_selected_idx = self.selected_idx
        self.data_list.selected_idx = self.selected_idx
        self._sync_data_list()
        if sel_changed:
            self.data_list.scroll_to_selected()

        # We render into a list of sections, summing height as we go,
        # then blit everything onto the final surface.

        # --- Upper half: data field list + controls ---
        upper_rows: list[tuple[str, Any]] = []


        # Selected field controls
        sel = self.selected_idx
        sel_fs = self.fields[sel]
        sel_cfg = self.configs[sel]
        upper_rows.append(("label", f"\u2500\u2500 {sel_fs.display_name} \u2500\u2500"))

        tgt_label = TARGET_LABELS[TARGET_VALUES.index(sel_cfg.target)]
        upper_rows.append(("dropdown", ("f_target", tgt_label, TARGET_LABELS)))
        upper_rows.append(("toggle", ("f_custom", "Custom", not sel_cfg.use_global)))

        gd = self.global_defaults
        eff_norm = NORM_MODES[sel_cfg.norm_mode if not sel_cfg.use_global else gd.norm_mode]
        eff_gamma = sel_cfg.gamma if not sel_cfg.use_global else gd.gamma
        eff_scale = sel_cfg.scale if not sel_cfg.use_global else gd.scale

        upper_rows.append(("dropdown", ("f_norm", eff_norm, NORM_MODES)))
        upper_rows.append(("slider", ("f_gamma", eff_gamma, 0.1, 5.0, "{:.2f}")))
        upper_rows.append(("slider", ("f_scale", eff_scale, 0.01, 10.0, "{:.2f}")))



        upper_rows.append(("label", ""))

        # Global defaults
        upper_rows.append(("label", "\u2500\u2500 Global Defaults \u2500\u2500"))
        upper_rows.append(("dropdown", ("g_norm",
                                         NORM_MODES[gd.norm_mode], NORM_MODES)))
        upper_rows.append(("slider", ("g_gamma", gd.gamma, 0.1, 5.0, "{:.2f}")))
        upper_rows.append(("slider", ("g_scale", gd.scale, 0.01, 10.0, "{:.2f}")))

        upper_rows.append(("label", ""))

        # Output post-aggregation
        upper_rows.append(("label", "\u2500\u2500 Output \u2500\u2500"))
        upper_rows.append(("slider", ("o_gamma", gd.out_gamma, 0.1, 5.0, "{:.2f}")))
        upper_rows.append(("slider", ("o_scale", gd.out_scale, 0.01, 10.0, "{:.2f}")))
        upper_rows.append(("button", ("save_view_png16", "Save View PNG (16-bit)")))
        upper_rows.append(("label", "\u2500\u2500 Resize Method \u2500\u2500"))
        upper_rows.append(("dropdown", ("resize_method",
                                         _RESIZE_METHODS[gd.resize_method], _RESIZE_METHODS)))
        upper_rows.append(("label", "\u2500\u2500 Export & Resize \u2500\u2500"))
        upper_rows.append(("dropdown", ("export_size", self._export_resize_preset,
                                         _EXPORT_PRESETS)))
        upper_rows.append(("button", ("export_and_resize", "Export + Resize")))
        if self._status_msg:
            upper_rows.append(("label", self._status_msg[:36]))

        # Post-FX aesthetic shader selector
        upper_rows.append(("label", "\u2500\u2500 Post FX \u2500\u2500"))
        upper_rows.append(("dropdown", ("post_fx",
                                         _FX_PRESETS[gd.fx_mode], _FX_PRESETS)))

        # Blend mode
        upper_rows.append(("dropdown", ("blend_mode",
                                         BLEND_MODES[gd.blend_mode], BLEND_MODES)))

        # Channel HSL controls
        upper_rows.append(("label", "\u2500\u2500 Channel Hues \u2500\u2500"))
        for ci in range(4):
            upper_rows.append(("label", f"Ch{ci + 1} Hue / Sat"))
            upper_rows.append(("slider", (f"ch{ci}_hue", gd.channel_hues[ci], 0.0, 1.0, "{:.2f}")))
            upper_rows.append(("slider", (f"ch{ci}_sat", gd.channel_sats[ci], 0.0, 1.0, "{:.2f}")))

        # HDR Dynamic Range controls
        upper_rows.append(("label", ""))
        upper_rows.append(("label", "\u2500\u2500 HDR / Dynamic Range \u2500\u2500"))
        upper_rows.append(("dropdown", ("hdr_norm",
                                         HDR_NORMALIZERS[gd.hdr_normalizer],
                                         HDR_NORMALIZERS)))
        upper_rows.append(("label", "Output Range"))
        upper_rows.append(("slider", ("hdr_out_lo", gd.hdr_output_lo, -1.0, 1.0, "{:.2f}")))
        upper_rows.append(("slider", ("hdr_out_hi", gd.hdr_output_hi, 0.0, 3.0, "{:.2f}")))

        # --- Pre-compute total height ---
        # Data list — estimate from flat list produced by tree
        flat = self.data_list._build_flat_list()
        vis_rows = min(len(flat), self.data_list.max_visible)
        data_list_h = self.data_list.ROW_H + 2  # title
        if flat:
            for fi in range(self.data_list.scroll_offset,
                            self.data_list.scroll_offset + vis_rows):
                if fi >= len(flat):
                    break
                ftype, _ = flat[fi]
                if ftype == "cat":
                    data_list_h += self.data_list.CAT_H + 1
                else:
                    data_list_h += self.ROW_H + 2
            if self.data_list.scroll_offset > 0:
                data_list_h += self.data_list.MORE_H + 2
            vis_end = self.data_list.scroll_offset + self.data_list.max_visible
            if vis_end < len(flat):
                data_list_h += self.data_list.MORE_H + 2
        else:
            data_list_h += self.ROW_H + 2

        upper_controls_h = sum(self.ROW_H + 2 for _ in upper_rows)

        plot_h = self._plot_h

        total_h = self.PAD + data_list_h + upper_controls_h + plot_h + self.PAD

        surf = pygame.Surface((w, total_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))

        y = self.PAD
        field_uses_global = sel_cfg.use_global

        # --- Render data field list ---
        data_h = self.data_list.render(surf, font, 0, y, w)
        y += data_h

        # --- Render field controls ---
        for rtype, rdata in upper_rows:
            if rtype == "label":
                txt = font.render(rdata, True, (180, 180, 180))
                surf.blit(txt, (self.PAD, y + 2))

            elif rtype == "dropdown":
                key, current, opts = rdata
                greyed = (key == "f_norm" and field_uses_global)
                prefix = {"f_target": "Tgt:", "f_norm": "Nrm:",
                          "g_norm": "Nrm:",
                          "blend_mode": "Blend:",
                          "hdr_norm": "HDR:"}.get(key, key[:4])
                lbl_col = (100, 100, 100) if greyed else (160, 160, 160)
                lbl = font.render(prefix, True, lbl_col)
                surf.blit(lbl, (self.PAD, y + 2))
                btn_x = 60
                btn_w = w - btn_x - self.PAD
                btn_rect = pygame.Rect(btn_x, y, btn_w, self.ROW_H)
                if greyed:
                    bg = (40, 40, 50)
                elif self._active_dropdown == key:
                    bg = (80, 80, 120)
                else:
                    bg = (60, 60, 80)
                pygame.draw.rect(surf, bg, btn_rect)
                pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
                tc = (120, 120, 120) if greyed else (220, 220, 220)
                txt = font.render(current, True, tc)
                surf.blit(txt, (btn_x + 4, y + 3))
                if not greyed:
                    self._item_map[key] = (btn_rect, opts)

            elif rtype == "toggle":
                key, label_text, checked = rdata
                rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, self.ROW_H)
                box = pygame.Rect(self.PAD + 2, y + 4, 14, 14)
                pygame.draw.rect(surf, (80, 80, 100), box, 1)
                if checked:
                    pygame.draw.line(surf, (120, 200, 120),
                                    (box.x + 2, box.y + 7),
                                    (box.x + 5, box.y + 11), 2)
                    pygame.draw.line(surf, (120, 200, 120),
                                    (box.x + 5, box.y + 11),
                                    (box.x + 12, box.y + 2), 2)
                txt = font.render(label_text, True, (200, 200, 200))
                surf.blit(txt, (self.PAD + 22, y + 3))
                self._item_map[key] = (rect, None)

            elif rtype == "slider":
                key, val, vmin, vmax, fmt = rdata
                greyed = (key.startswith("f_") and field_uses_global)
                BTN_W = 16
                lbl_end = self.PAD
                val_space = 50

                # Minus button
                minus_r = pygame.Rect(lbl_end, y + 2, BTN_W, self.ROW_H - 4)
                mc = (35, 35, 45) if greyed else (50, 50, 65)
                pygame.draw.rect(surf, mc, minus_r)
                pygame.draw.rect(surf, (80, 80, 100), minus_r, 1)
                mt = font.render("\u2212", True,
                                 (80, 80, 90) if greyed else (180, 180, 200))
                surf.blit(mt, (minus_r.x + (BTN_W - mt.get_width()) // 2,
                               y + 2))

                # Track
                track_x = lbl_end + BTN_W + 2
                track_end = w - self.PAD - val_space - BTN_W - 2
                track_w = max(track_end - track_x, 10)
                tc = (35, 35, 40) if greyed else (50, 50, 60)
                pygame.draw.rect(surf, tc,
                                 pygame.Rect(track_x, y + 8, track_w, 6))
                frac = (val - vmin) / max(vmax - vmin, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track_x + int(frac * track_w)
                thc = (70, 80, 100) if greyed else (120, 140, 200)
                pygame.draw.rect(surf, thc,
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))

                # Plus button
                plus_r = pygame.Rect(track_end + 2, y + 2, BTN_W,
                                     self.ROW_H - 4)
                pc = (35, 35, 45) if greyed else (50, 50, 65)
                pygame.draw.rect(surf, pc, plus_r)
                pygame.draw.rect(surf, (80, 80, 100), plus_r, 1)
                pt = font.render("+", True,
                                 (80, 80, 90) if greyed else (180, 180, 200))
                surf.blit(pt, (plus_r.x + (BTN_W - pt.get_width()) // 2,
                               y + 2))

                # Value label
                vc = (100, 100, 100) if greyed else (200, 200, 200)
                vtxt = font.render(fmt.format(val), True, vc)
                surf.blit(vtxt, (plus_r.x + BTN_W + 4, y + 2))

                if not greyed:
                    self._item_map[f"{key}_minus"] = (minus_r, None)
                    self._item_map[f"{key}_plus"] = (plus_r, None)
                    self._item_map[key] = (
                        pygame.Rect(track_x, y, track_w, self.ROW_H),
                        (vmin, vmax))

            elif rtype == "button":
                key, label_text = rdata
                btn_rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, self.ROW_H)
                pygame.draw.rect(surf, (50, 80, 140), btn_rect)
                pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
                txt = font.render(label_text, True, (220, 220, 220))
                surf.blit(txt, (btn_rect.x + (btn_rect.w - txt.get_width()) // 2, y + 3))
                self._item_map[key] = (btn_rect, None)

            y += self.ROW_H + 2

        # --- Rebuild & render plot widget ---
        self._rebuild_plot_series()
        self.plot.render(surf, self.PAD, y, w - 2 * self.PAD, self._plot_h,
                         font=font)

        return surf

    # ---- Event handling ---------------------------------------------------

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False

        pr = self.panel_rect

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if not pr.collidepoint(mx, my):
                if self._active_dropdown:
                    self._active_dropdown = None
                return False

            lx, ly = mx - pr.x, my - pr.y
            ly += self._panel_scroll_y

            # Open dropdown item selection
            if self._active_dropdown and self._dropdown_rect.collidepoint(lx, ly):
                for i, ir in enumerate(self._dropdown_item_rects):
                    if ir.collidepoint(lx, ly):
                        self._select_dropdown(self._active_dropdown,
                                              self._dropdown_opts[i])
                        break
                self._active_dropdown = None
                return True

            if self._active_dropdown:
                self._active_dropdown = None

            # Data field rows
            hit = self.data_list.handle_click(lx, ly)
            if hit is not None:
                if hit >= 0:
                    self.selected_idx = hit
                return True

            # Toggle
            if "f_custom" in self._item_map:
                rect, _ = self._item_map["f_custom"]
                if rect.collidepoint(lx, ly):
                    cfg = self.configs[self.selected_idx]
                    if cfg.use_global:
                        gd = self.global_defaults
                        cfg.norm_mode = gd.norm_mode
                        cfg.gamma = gd.gamma
                        cfg.scale = gd.scale
                    cfg.use_global = not cfg.use_global
                    return True

            if "save_view_png16" in self._item_map:
                rect, _ = self._item_map["save_view_png16"]
                if rect.collidepoint(lx, ly):
                    if self.on_save_view_png16:
                        try:
                            out_path = self.on_save_view_png16()
                            if out_path:
                                self._status_msg = f"Saved: {os.path.basename(out_path)}"
                            else:
                                self._status_msg = "Save skipped"
                        except Exception as exc:
                            self._status_msg = f"Save error: {exc}"
                    else:
                        self._status_msg = "Save handler missing"
                    return True

            if "export_and_resize" in self._item_map:
                rect, _ = self._item_map["export_and_resize"]
                if rect.collidepoint(lx, ly):
                    preset = self._export_resize_preset
                    if preset == "native":
                        if self.on_save_view_png16:
                            try:
                                out_path = self.on_save_view_png16()
                                self._status_msg = (f"Saved: {os.path.basename(out_path)}"
                                                    if out_path else "Save skipped")
                            except Exception as exc:
                                self._status_msg = f"Save error: {exc}"
                        else:
                            self._status_msg = "Save handler missing"
                    else:
                        if self.on_export_resize:
                            try:
                                w, h = (int(x) for x in preset.split("x"))
                                out_path = self.on_export_resize(w, h)
                                self._status_msg = (f"Resized: {os.path.basename(out_path)}"
                                                    if out_path else "Resize skipped")
                            except Exception as exc:
                                self._status_msg = f"Resize error: {exc}"
                        else:
                            self._status_msg = "Resize handler missing"
                    return True

            # Dropdowns
            for key in ("f_target", "f_norm", "g_norm", "blend_mode",
                        "hdr_norm", "export_size", "post_fx", "resize_method"):
                if key in self._item_map:
                    rect, opts = self._item_map[key]
                    if rect.collidepoint(lx, ly):
                        self._open_dropdown(key, opts, rect, pr)
                        return True

            # Slider +/- buttons and track drag — collect all slider keys
            _slider_keys = ["f_gamma", "f_scale",
                            "g_gamma", "g_scale",
                            "o_gamma", "o_scale"]
            for ci in range(4):
                _slider_keys.append(f"ch{ci}_hue")
                _slider_keys.append(f"ch{ci}_sat")
            _slider_keys.extend(["hdr_out_lo", "hdr_out_hi"])
            for key in _slider_keys:
                minus_k = f"{key}_minus"
                plus_k = f"{key}_plus"
                if minus_k in self._item_map:
                    rect, _ = self._item_map[minus_k]
                    if rect.collidepoint(lx, ly):
                        self._nudge_slider(key, -1)
                        return True
                if plus_k in self._item_map:
                    rect, _ = self._item_map[plus_k]
                    if rect.collidepoint(lx, ly):
                        self._nudge_slider(key, +1)
                        return True

            # Slider track drag
            for key in _slider_keys:
                if key in self._item_map:
                    rect, (vmin, vmax) = self._item_map[key]
                    if rect.collidepoint(lx, ly):
                        self._dragging = key
                        self._update_slider(key, lx, rect, vmin, vmax)
                        return True

            return True  # consumed (in panel area)

        if event.type == MOUSEBUTTONUP and event.button == 1:
            if self._dragging:
                self._dragging = None
                return True
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEMOTION:
            if self._dragging:
                if not event.buttons[0]:
                    self._dragging = None
                else:
                    mx, my = event.pos
                    lx = mx - pr.x
                    key = self._dragging
                    if key in self._item_map:
                        rect, (vmin, vmax) = self._item_map[key]
                        self._update_slider(key, lx, rect, vmin, vmax)
                return True
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEWHEEL:
            return self._handle_panel_wheel(event)

        return False

    def _open_dropdown(self, key: str, opts: list[str],
                       btn_rect: pygame.Rect,
                       panel_rect: pygame.Rect) -> None:
        self._active_dropdown = key
        self._dropdown_opts = opts
        x = btn_rect.x
        y = btn_rect.y + btn_rect.h
        item_h = self.ROW_H
        total_h = item_h * len(opts)
        self._dropdown_rect = pygame.Rect(x, y, btn_rect.w, total_h)
        self._dropdown_item_rects = [
            pygame.Rect(x, y + i * item_h, btn_rect.w, item_h)
            for i in range(len(opts))
        ]

    def _select_dropdown(self, key: str, value: str) -> None:
        cfg = self.configs[self.selected_idx]
        if key == "f_target":
            cfg.target = TARGET_VALUES[TARGET_LABELS.index(value)]
        elif key == "f_norm":
            cfg.norm_mode = NORM_MODES.index(value)
        elif key == "g_norm":
            self.global_defaults.norm_mode = NORM_MODES.index(value)
        elif key == "blend_mode":
            self.global_defaults.blend_mode = BLEND_MODES.index(value)
        elif key == "hdr_norm":
            self.global_defaults.hdr_normalizer = HDR_NORMALIZERS.index(value)
        elif key == "export_size":
            self._export_resize_preset = value
        elif key == "post_fx":
            self.global_defaults.fx_mode = _FX_PRESETS.index(value)
        elif key == "resize_method":
            self.global_defaults.resize_method = _RESIZE_METHODS.index(value)
        elif key == "cwt_wavelet":
            cfg.cwt_wavelet = value
        elif key == "dwt_wavelet":
            cfg.dwt_wavelet = value

    def _update_slider(self, key: str, lx: int,
                       rect: pygame.Rect,
                       vmin: float, vmax: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / rect.w))
        val = round(vmin + frac * (vmax - vmin), 2)
        self._apply_slider_value(key, val)

    def _apply_slider_value(self, key: str, val: float) -> None:
        cfg = self.configs[self.selected_idx]
        gd = self.global_defaults
        if key == "f_gamma":
            cfg.gamma = val
        elif key == "f_scale":
            cfg.scale = val
        elif key == "g_gamma":
            gd.gamma = val
        elif key == "g_scale":
            gd.scale = val
        elif key == "o_gamma":
            gd.out_gamma = val
        elif key == "o_scale":
            gd.out_scale = val
        elif key.startswith("ch") and key.endswith("_hue"):
            ci = int(key[2])
            gd.channel_hues[ci] = val
        elif key.startswith("ch") and key.endswith("_sat"):
            ci = int(key[2])
            gd.channel_sats[ci] = val
        elif key == "hdr_out_lo":
            gd.hdr_output_lo = val
        elif key == "hdr_out_hi":
            gd.hdr_output_hi = val
        # Per-transform window/time support
        elif key == "cqt_bins":
            cfg.cqt_bins = int(val)
        elif key == "cqt_q":
            cfg.cqt_q = float(val)
        elif key == "fb_window":
            cfg.fb_window = int(val)
        elif key == "fb_bandwidth":
            cfg.fb_bandwidth = float(val)
        elif key == "cwt_width":
            cfg.cwt_width = int(val)
        elif key == "dwt_levels":
            cfg.dwt_levels = int(val)
        # nsgt_window_size does not belong here; handled in SourcePanel

    def _nudge_slider(self, key: str, direction: int) -> None:
        """Move a slider by one logical step. direction: +1 or -1."""
        # Determine current value and range from _item_map
        if key not in self._item_map:
            return
        _, (vmin, vmax) = self._item_map[key]
        cfg = self.configs[self.selected_idx]
        gd = self.global_defaults
        current = {
            "f_gamma": cfg.gamma, "f_scale": cfg.scale,
            "g_gamma": gd.gamma, "g_scale": gd.scale,
            "o_gamma": gd.out_gamma, "o_scale": gd.out_scale,
            "hdr_out_lo": gd.hdr_output_lo, "hdr_out_hi": gd.hdr_output_hi,
        }
        for ci in range(4):
            current[f"ch{ci}_hue"] = gd.channel_hues[ci]
            current[f"ch{ci}_sat"] = gd.channel_sats[ci]
        current = current.get(key, 0.0)
        step = (vmax - vmin) / 50.0
        val = round(max(vmin, min(vmax, current + direction * step)), 2)
        self._apply_slider_value(key, val)

    def render_dropdown_overlay(self) -> pygame.Surface | None:
        if not self._active_dropdown or not self._dropdown_opts:
            return None
        self._ensure_font()
        font = self.font
        rect = self._dropdown_rect
        surf = pygame.Surface((rect.w, rect.h), pygame.SRCALPHA)
        surf.fill((40, 40, 50, 240))
        for i, opt in enumerate(self._dropdown_opts):
            ir = self._dropdown_item_rects[i]
            iy = ir.y - rect.y
            txt = font.render(opt, True, (220, 220, 220))
            surf.blit(txt, (4, iy + 3))
            if i < len(self._dropdown_opts) - 1:
                pygame.draw.line(surf, (60, 60, 70),
                                 (0, iy + self.ROW_H - 1),
                                 (rect.w, iy + self.ROW_H - 1))
        pygame.draw.rect(surf, (100, 100, 130),
                         pygame.Rect(0, 0, rect.w, rect.h), 1)
        return surf


# ---------------------------------------------------------------------------
# Hybrid view panel — controls for hybrid-only display behaviour
# ---------------------------------------------------------------------------

class HybridViewPanel(Panel):
    """Dockable controls for the TF hybrid stack."""

    ROW_H = 22
    PAD = 6

    def __init__(self, config: HybridViewConfig, *, side: str = "right") -> None:
        super().__init__(title="Hybrid View", side=side)
        self.config = config
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._dragging: str | None = None
        self._is_active: Any = lambda: False
        self.on_change: Any = lambda: None

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._item_map = {}

        rows: list[tuple[str, Any]] = [
            ("label", "Hybrid stack"),
            ("label", "CWT bottom  |  FB centered  |  FFT top"),
        ]
        if not self._is_active():
            rows.append(("label", "Active in TF -> Hybrid"))
        rows.extend([
            ("toggle", ("hide_gutter_bands", "Hide LP/HP gutters",
                        self.config.hide_gutter_bands)),
            ("slider", ("fb_mix", "FB Blend", self.config.fb_mix,
                        0.0, 1.0, "{:.2f}")),
            ("slider", ("overlap_alpha_floor", "Uncertainty Floor",
                        self.config.overlap_alpha_floor,
                        0.0, 1.0, "{:.2f}")),
            ("toggle", ("show_scale_crossover", "Scale crossover line",
                        self.config.show_scale_crossover)),
            ("toggle", ("show_overlap_lines", "Overlap guides",
                        self.config.show_overlap_lines)),
            ("toggle", ("show_marker_labels", "Marker labels",
                        self.config.show_marker_labels)),
        ])

        total_h = self.PAD * 2 + len(rows) * (self.ROW_H + 2)
        surf = pygame.Surface((w, total_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))

        y = self.PAD
        for rtype, rdata in rows:
            if rtype == "label":
                color = (170, 170, 175) if self._is_active() else (140, 140, 145)
                txt = font.render(str(rdata), True, color)
                surf.blit(txt, (self.PAD, y + 3))
            elif rtype == "toggle":
                key, label, value = rdata
                rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, self.ROW_H)
                box = pygame.Rect(self.PAD, y + 3, 16, 16)
                pygame.draw.rect(surf, (45, 45, 55), box)
                pygame.draw.rect(surf, (90, 90, 110), box, 1)
                if value:
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 2, box.y + 8),
                                     (box.x + 6, box.y + 12), 2)
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 6, box.y + 12),
                                     (box.x + 13, box.y + 3), 2)
                txt = font.render(label, True, (210, 210, 210))
                surf.blit(txt, (self.PAD + 24, y + 3))
                self._item_map[key] = (rect, None)
            elif rtype == "slider":
                key, label, value, vmin, vmax, fmt = rdata
                txt = font.render(label, True, (210, 210, 210))
                surf.blit(txt, (self.PAD, y + 3))
                lbl_w = max(92, txt.get_width() + 8)
                val_txt = font.render(fmt.format(value), True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                frac = (value - vmin) / max(vmax - vmin, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                pygame.draw.rect(surf, (120, 140, 200),
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, self.ROW_H),
                    (vmin, vmax),
                )
            y += self.ROW_H + 2

        return surf

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False

        pr = self.panel_rect
        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if not pr.collidepoint(mx, my):
                return False
            lx, ly = mx - pr.x, my - pr.y + self._panel_scroll_y
            for key, (rect, meta) in self._item_map.items():
                if not rect.collidepoint(lx, ly):
                    continue
                if meta is None:
                    setattr(self.config, key, not getattr(self.config, key))
                    self.on_change()
                    return True
                self._dragging = key
                self._update_slider(key, lx, rect, meta[0], meta[1])
                return True
            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            if self._dragging:
                self._dragging = None
                self.on_change()
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEMOTION:
            if self._dragging:
                if not event.buttons[0]:
                    self._dragging = None
                    self.on_change()
                    return True
                mx, _ = event.pos
                lx = mx - pr.x
                rect, meta = self._item_map[self._dragging]
                self._update_slider(self._dragging, lx, rect, meta[0], meta[1])
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEWHEEL:
            return self._handle_panel_wheel(event)

        return False

    def _update_slider(self, key: str, lx: int,
                       rect: pygame.Rect,
                       vmin: float, vmax: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        setattr(self.config, key, round(vmin + frac * (vmax - vmin), 2))


# ---------------------------------------------------------------------------
# Time-Scale (wavelet) view panel
# ---------------------------------------------------------------------------

class TimeScaleViewPanel(Panel):
    """Dockable panel for the Time-Scale (TSC) wavelet display.

    Contains a viewport-local time-scale slider and a Play/Stop button.
    Synthesis and playback are handled entirely within this panel and the
    viewer's ``_play_wavelet_direct`` method — no SynthesisPanel involvement.

    Slider range: −5 … +5 in log₂  (≈ ×0.031 to ×32).
    Snap to every integer log₂ (×0.03, ×0.06, ×0.125, ×0.25, ×0.5,
    ×1, ×2, ×4, ×8, ×16, ×32).  Mouse-wheel steps 0.25 log₂ per click.
    """

    ROW_H = 22
    PAD = 6
    BTN_H = 26
    _LOG2_MIN = -5.0
    _LOG2_MAX = 5.0
    _TARGET_MIDI = 72  # C5

    def __init__(self, config: WaveletViewConfig, *, side: str = "right") -> None:
        super().__init__(title="Wavelet Playback", side=side)
        self.config = config
        self.viewport_widget = ViewportBoundaryWidget(prefix="vp")
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._dragging: str | None = None
        # Playback state (updated by viewer via _play_wavelet_direct)
        self._status: str = "idle"    # idle | synthesizing | playing | error
        self._error_msg: str = ""
        self._playing_channel: pygame.mixer.Channel | None = None
        self._playing_sound: Any = None   # pygame.mixer.Sound
        self._synth_thread: threading.Thread | None = None
        # Callbacks wired by the viewer
        self.on_play: Any = lambda: None   # () → triggers synthesis+play
        self.on_stop: Any = lambda: None   # () → stop playback
        self.get_viewport_context: Any = lambda: {}
        self.get_scale_slider_range: Any = lambda: (self._LOG2_MIN, self._LOG2_MAX)

    def _log2_range(self) -> tuple[float, float]:
        try:
            lo, hi = self.get_scale_slider_range()
        except Exception:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        lo = float(lo)
        hi = float(hi)
        if hi <= lo:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        return lo, hi

    @staticmethod
    def _snap_log2_values(l2min: float, l2max: float) -> list[float]:
        i0 = int(math.ceil(l2min))
        i1 = int(math.floor(l2max))
        snaps = [float(i) for i in range(i0, i1 + 1)]
        if 0.0 not in snaps and l2min <= 0.0 <= l2max:
            snaps.append(0.0)
            snaps.sort()
        return snaps

    # ------------------------------------------------------------------
    def stop_playback(self) -> None:
        """Stop any active playback and reset status to idle."""
        if self._playing_channel is not None:
            try:
                self._playing_channel.stop()
            except Exception:
                pass
            self._playing_channel = None
        self._playing_sound = None
        self._status = "idle"

    # ------------------------------------------------------------------
    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._item_map = {}

        # Auto-update status: clear "playing" once channel finishes
        if self._status == "playing" and self._playing_channel is not None:
            if not self._playing_channel.get_busy():
                self._status = "idle"
                self._playing_channel = None
                self._playing_sound = None

        bright = (210, 210, 210)
        dim    = (150, 150, 155)

        ts = self.config.time_scale
        l2 = self.config.time_scale_log2
        l2min, l2max = self._log2_range()
        snap_log2 = self._snap_log2_values(l2min, l2max)

        # Status line
        if self._status == "synthesizing":
            status_col = (120, 180, 255)
            status_str = "Synthesizing…"
        elif self._status == "playing":
            status_col = (100, 220, 120)
            status_str = f"Playing  ×{ts:.3f}"
        elif self._status == "error":
            status_col = (255, 100, 100)
            status_str = f"Error: {self._error_msg[:26]}"
        else:
            status_col = dim
            status_str = "Idle"

        # Build row list
        rows: list[tuple[str, Any]] = [
            ("label_col", ("Wavelet Time-Scale Playback", bright)),
            ("label_col", (status_str, status_col)),
            ("log_slider", ("time_scale_log2", "Scale",
                            l2, l2min, l2max)),
            ("toggle", ("normalize", "Normalize loudness",
                        self.config.normalize)),
        ]
        rows.extend(
            self.viewport_widget.build_rows(
                self.config.viewport_boundary,
                self.get_viewport_context(),
            )
        )
        rows.extend([
            ("play_stop", None),
        ])

        row_heights = []
        for rtype, _ in rows:
            row_heights.append(self.BTN_H if rtype == "play_stop"
                               else self.ROW_H)

        total_h = self.PAD * 2 + sum(rh + 2 for rh in row_heights)
        surf = pygame.Surface((w, total_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))

        y = self.PAD
        for (rtype, rdata), rh in zip(rows, row_heights):

            if rtype == "label_col":
                text, col = rdata
                txt = font.render(text, True, col)
                surf.blit(txt, (self.PAD, y + 3))

            elif rtype == "toggle":
                key, label, value = rdata
                rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, rh)
                box = pygame.Rect(self.PAD, y + 3, 16, 16)
                pygame.draw.rect(surf, (45, 45, 55), box)
                pygame.draw.rect(surf, (90, 90, 110), box, 1)
                if value:
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 2, box.y + 8),
                                     (box.x + 6, box.y + 12), 2)
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 6, box.y + 12),
                                     (box.x + 13, box.y + 3), 2)
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD + 24, y + 3))
                self._item_map[key] = (rect, None)

            elif rtype == "slider":
                key, label, value, vmin, vmax, fmt = rdata
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD, y + 3))
                lbl_w = max(78, txt.get_width() + 8)
                val_txt = font.render(fmt.format(value), True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                frac = (value - vmin) / max(vmax - vmin, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                pygame.draw.rect(surf, (120, 140, 200),
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (vmin, vmax),
                )

            elif rtype == "log_slider":
                key, label, log2_val, l2min, l2max = rdata
                lbl_txt = font.render(label, True, bright)
                surf.blit(lbl_txt, (self.PAD, y + 3))
                lbl_w = lbl_txt.get_width() + 8

                actual = 2.0 ** log2_val
                # Show as fraction or multiplier cleanly
                if actual < 1.0:
                    val_str = f"÷{1.0/actual:.2f}"
                else:
                    val_str = f"×{actual:.2f}"
                val_txt = font.render(val_str, True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))

                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)

                # Tick marks at every integer log₂ — label ×1 centre
                for snap in snap_log2:
                    frac_s = (snap - l2min) / (l2max - l2min)
                    tx = track.x + int(round(frac_s * track.w))
                    h_tick = 8 if snap == 0.0 else 4
                    pygame.draw.line(surf, (90, 90, 110),
                                     (tx, track.y - 1),
                                     (tx, track.y + h_tick), 1)

                frac = (log2_val - l2min) / max(l2max - l2min, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                thumb_col = (100, 200, 120) if abs(log2_val) < 0.05 \
                            else (120, 140, 200)
                pygame.draw.rect(surf, thumb_col,
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))

                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (l2min, l2max),
                )

            elif rtype == "play_stop":
                btn_w = (w - self.PAD * 3) // 2
                playing = self._status in ("playing", "synthesizing")

                # Play button
                play_rect = pygame.Rect(self.PAD, y, btn_w, rh)
                play_col = (50, 100, 50) if not playing else (35, 60, 35)
                pygame.draw.rect(surf, play_col, play_rect, border_radius=4)
                pygame.draw.rect(surf, (80, 160, 80), play_rect, 1,
                                 border_radius=4)
                ptxt = font.render("▶ Play", True,
                                   (180, 255, 180) if not playing
                                   else (100, 140, 100))
                surf.blit(ptxt, (play_rect.x + (btn_w - ptxt.get_width()) // 2,
                                 play_rect.y + (rh - ptxt.get_height()) // 2))
                self._item_map["_play"] = (play_rect, "play")

                # Stop button
                stop_x = self.PAD * 2 + btn_w
                stop_rect = pygame.Rect(stop_x, y, btn_w, rh)
                stop_col = (100, 50, 50) if playing else (50, 35, 35)
                pygame.draw.rect(surf, stop_col, stop_rect, border_radius=4)
                pygame.draw.rect(surf, (160, 80, 80), stop_rect, 1,
                                 border_radius=4)
                stxt = font.render("■ Stop", True,
                                   (255, 180, 180) if playing
                                   else (120, 80, 80))
                surf.blit(stxt, (stop_rect.x + (btn_w - stxt.get_width()) // 2,
                                 stop_rect.y + (rh - stxt.get_height()) // 2))
                self._item_map["_stop"] = (stop_rect, "stop")

            y += rh + 2

        return surf

    # ------------------------------------------------------------------
    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False

        pr = self.panel_rect

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            for key, (rect, meta) in self._item_map.items():
                if not rect.collidepoint(lx, ly):
                    continue
                if meta == "play":
                    if self._status not in ("playing", "synthesizing"):
                        self.on_play()
                    return True
                if meta == "stop":
                    self.on_stop()
                    return True
                if meta is None:
                    if self.viewport_widget.handle_toggle(
                        key, self.config.viewport_boundary
                    ):
                        return True
                    # Toggle boolean config field
                    setattr(self.config, key, not getattr(self.config, key))
                    return True
                # Log-slider drag
                self._dragging = key
                if key == "time_scale_log2":
                    self._update_log_slider(key, lx, rect, meta[0], meta[1])
                else:
                    self._update_slider(key, lx, rect, meta[0], meta[1])
                return True
            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            if self._dragging:
                self._dragging = None
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEMOTION:
            if self._dragging:
                if not event.buttons[0]:
                    self._dragging = None
                    return True
                mx, _ = event.pos
                lx = mx - pr.x
                rect, meta = self._item_map[self._dragging]
                if self._dragging == "time_scale_log2":
                    self._update_log_slider(self._dragging, lx, rect,
                                            meta[0], meta[1])
                else:
                    self._update_slider(self._dragging, lx, rect,
                                        meta[0], meta[1])
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEWHEEL:
            mx, my = pygame.mouse.get_pos()
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            if "time_scale_log2" in self._item_map:
                rect, meta = self._item_map["time_scale_log2"]
                if rect.collidepoint(lx, ly):
                    step = 0.25 * (1 if event.y > 0 else -1)
                    cur = self.config.time_scale_log2
                    l2min, l2max = self._log2_range()
                    self.config.time_scale_log2 = round(
                        max(l2min, min(l2max, cur + step)), 3)
                    return True
            return self._handle_panel_wheel(event)

        return False

    def _update_log_slider(self, key: str, lx: int,
                           rect: pygame.Rect,
                           l2min: float, l2max: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        raw = l2min + frac * (l2max - l2min)
        # Snap to integer log₂ values when within ~0.1 unit
        for snap in self._snap_log2_values(l2min, l2max):
            if abs(raw - snap) < 0.10:
                raw = float(snap)
                break
        setattr(self.config, key, round(raw, 3))

    def _update_slider(self, key: str, lx: int,
                       rect: pygame.Rect,
                       vmin: float, vmax: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        val = round(vmin + frac * (vmax - vmin), 2)
        if self.viewport_widget.apply_slider_value(
            key, val, self.config.viewport_boundary
        ):
            return


class FilterbankScalerPanel(Panel):
    """Dockable direct-playback panel for filterbank-band scaling."""

    ROW_H = 22
    PAD = 6
    BTN_H = 26
    _LOG2_MIN = -5.0
    _LOG2_MAX = 5.0
    _TARGET_MIDI = 72  # C5

    def __init__(self, config: FilterbankScalerConfig, *, side: str = "right") -> None:
        super().__init__(title="Filterbank Scaler", side=side)
        self.config = config
        self.viewport_widget = ViewportBoundaryWidget(prefix="fbvp")
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._dragging: str | None = None
        self._active_dropdown: str | None = None
        self._dropdown_opts: list[str] = []
        self._dropdown_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._dropdown_item_rects: list[pygame.Rect] = []
        self._status: str = "idle"
        self._error_msg: str = ""
        self._playing_channel: pygame.mixer.Channel | None = None
        self._playing_sound: Any = None
        self._synth_thread: threading.Thread | None = None
        self._is_active: Any = lambda: False
        self.on_play: Any = lambda: None
        self.on_stop: Any = lambda: None
        self.get_viewport_context: Any = lambda: {}
        self.get_scale_slider_range: Any = lambda: (self._LOG2_MIN, self._LOG2_MAX)

    def _log2_range(self) -> tuple[float, float]:
        try:
            lo, hi = self.get_scale_slider_range()
        except Exception:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        lo = float(lo)
        hi = float(hi)
        if hi <= lo:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        return lo, hi

    @staticmethod
    def _snap_log2_values(l2min: float, l2max: float) -> list[float]:
        i0 = int(math.ceil(l2min))
        i1 = int(math.floor(l2max))
        snaps = [float(i) for i in range(i0, i1 + 1)]
        if 0.0 not in snaps and l2min <= 0.0 <= l2max:
            snaps.append(0.0)
            snaps.sort()
        return snaps

    def stop_playback(self) -> None:
        if self._playing_channel is not None:
            try:
                self._playing_channel.stop()
            except Exception:
                pass
            self._playing_channel = None
        self._playing_sound = None
        self._status = "idle"

    def _open_dropdown(self, key: str, options: list[str], anchor: pygame.Rect) -> None:
        self._active_dropdown = key
        self._dropdown_opts = list(options)
        self._dropdown_rect = anchor

    def _select_dropdown(self, idx: int) -> None:
        key = self._active_dropdown
        self._active_dropdown = None
        if key == "method" and 0 <= idx < len(FILTERBANK_SCALER_METHODS):
            self.config.method = FILTERBANK_SCALER_METHODS[idx]

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._item_map = {}

        if self._status == "playing" and self._playing_channel is not None:
            if not self._playing_channel.get_busy():
                self._status = "idle"
                self._playing_channel = None
                self._playing_sound = None

        bright = (210, 210, 210)
        dim = (150, 150, 155)
        scale = self.config.scale
        l2 = self.config.scale_log2
        l2min, l2max = self._log2_range()
        snap_log2 = self._snap_log2_values(l2min, l2max)

        if self._status == "synthesizing":
            status_col = (120, 180, 255)
            status_str = "Preparing band…"
        elif self._status == "playing":
            status_col = (100, 220, 120)
            status_str = f"Playing  ×{scale:.3f}"
        elif self._status == "error":
            status_col = (255, 100, 100)
            status_str = f"Error: {self._error_msg[:26]}"
        else:
            status_col = dim
            status_str = "Idle"

        method_label = FILTERBANK_SCALER_METHOD_LABELS.get(
            self.config.method, self.config.method.title())

        rows: list[tuple[str, Any]] = [
            ("label_col", ("Filterbank Scaler", bright)),
            ("label_col", (status_str, status_col)),
            ("dropdown", ("method", "Method", method_label)),
            ("log_slider", ("scale_log2", "Scale", l2, l2min, l2max)),
            ("toggle", ("use_only_existing_bands", "Use only existing bands",
                        self.config.use_only_existing_bands)),
            ("toggle", ("normalize", "Normalize loudness",
                        self.config.normalize)),
        ]
        rows.extend(
            self.viewport_widget.build_rows(
                self.config.viewport_boundary,
                self.get_viewport_context(),
            )
        )
        rows.append(("play_stop", None))

        row_heights = [
            self.BTN_H if rtype == "play_stop" else self.ROW_H
            for rtype, _ in rows
        ]
        total_h = self.PAD * 2 + sum(rh + 2 for rh in row_heights)
        surf = pygame.Surface((w, total_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))

        y = self.PAD
        for (rtype, rdata), rh in zip(rows, row_heights):
            if rtype == "label_col":
                text, col = rdata
                txt = font.render(text, True, col)
                surf.blit(txt, (self.PAD, y + 3))

            elif rtype == "toggle":
                key, label, value = rdata
                rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, rh)
                box = pygame.Rect(self.PAD, y + 3, 16, 16)
                pygame.draw.rect(surf, (45, 45, 55), box)
                pygame.draw.rect(surf, (90, 90, 110), box, 1)
                if value:
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 2, box.y + 8),
                                     (box.x + 6, box.y + 12), 2)
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 6, box.y + 12),
                                     (box.x + 13, box.y + 3), 2)
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD + 24, y + 3))
                self._item_map[key] = (rect, None)

            elif rtype == "dropdown":
                key, label, value = rdata
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD, y + 3))
                btn_w = 120
                btn_x = w - self.PAD - btn_w
                btn = pygame.Rect(btn_x, y + 1, btn_w, rh - 2)
                pygame.draw.rect(surf, (50, 50, 60), btn, border_radius=3)
                pygame.draw.rect(surf, (90, 90, 110), btn, 1, border_radius=3)
                val_txt = font.render(value, True, (220, 220, 220))
                surf.blit(val_txt, (btn.x + 6, y + 3))
                tri = [(btn.right - 14, y + 9), (btn.right - 6, y + 9), (btn.right - 10, y + 14)]
                pygame.draw.polygon(surf, (180, 180, 190), tri)
                self._item_map[key] = (btn, "dropdown")

            elif rtype == "slider":
                key, label, value, vmin, vmax, fmt = rdata
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD, y + 3))
                lbl_w = max(78, txt.get_width() + 8)
                val_txt = font.render(fmt.format(value), True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                frac = (value - vmin) / max(vmax - vmin, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                pygame.draw.rect(surf, (120, 140, 200),
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (vmin, vmax),
                )

            elif rtype == "log_slider":
                key, label, log2_val, lo, hi = rdata
                lbl_txt = font.render(label, True, bright)
                surf.blit(lbl_txt, (self.PAD, y + 3))
                lbl_w = lbl_txt.get_width() + 8
                actual = 2.0 ** log2_val
                val_str = f"÷{1.0/actual:.2f}" if actual < 1.0 else f"×{actual:.2f}"
                val_txt = font.render(val_str, True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                for snap in snap_log2:
                    frac_s = (snap - lo) / max(hi - lo, 1e-9)
                    tx = track.x + int(round(frac_s * track.w))
                    h_tick = 8 if snap == 0.0 else 4
                    pygame.draw.line(surf, (90, 90, 110),
                                     (tx, track.y - 1),
                                     (tx, track.y + h_tick), 1)
                frac = (log2_val - lo) / max(hi - lo, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                thumb_col = (100, 200, 120) if abs(log2_val) < 0.05 else (120, 140, 200)
                pygame.draw.rect(surf, thumb_col,
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (lo, hi),
                )

            elif rtype == "play_stop":
                btn_w = (w - self.PAD * 3) // 2
                playing = self._status in ("playing", "synthesizing")
                play_rect = pygame.Rect(self.PAD, y, btn_w, rh)
                stop_rect = pygame.Rect(self.PAD * 2 + btn_w, y, btn_w, rh)
                pygame.draw.rect(surf, (50, 100, 50) if not playing else (35, 60, 35),
                                 play_rect, border_radius=4)
                pygame.draw.rect(surf, (80, 160, 80), play_rect, 1, border_radius=4)
                pygame.draw.rect(surf, (100, 50, 50) if playing else (50, 35, 35),
                                 stop_rect, border_radius=4)
                pygame.draw.rect(surf, (160, 80, 80), stop_rect, 1, border_radius=4)
                ptxt = font.render("▶ Play", True,
                                   (180, 255, 180) if not playing else (100, 140, 100))
                stxt = font.render("■ Stop", True,
                                   (255, 180, 180) if playing else (120, 80, 80))
                surf.blit(ptxt, (play_rect.x + (btn_w - ptxt.get_width()) // 2,
                                 play_rect.y + (rh - ptxt.get_height()) // 2))
                surf.blit(stxt, (stop_rect.x + (btn_w - stxt.get_width()) // 2,
                                 stop_rect.y + (rh - stxt.get_height()) // 2))
                self._item_map["_play"] = (play_rect, "play")
                self._item_map["_stop"] = (stop_rect, "stop")

            y += rh + 2

        return surf

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False
        pr = self.panel_rect

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if self._active_dropdown:
                for i, ir in enumerate(self._dropdown_item_rects):
                    if ir.collidepoint(mx, my):
                        self._select_dropdown(i)
                        return True
                self._active_dropdown = None
                return True
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            for key, (rect, meta) in self._item_map.items():
                if not rect.collidepoint(lx, ly):
                    continue
                if meta == "play":
                    if self._status not in ("playing", "synthesizing"):
                        self.on_play()
                    return True
                if meta == "stop":
                    self.on_stop()
                    return True
                if meta == "dropdown":
                    self._open_dropdown(
                        key,
                        [FILTERBANK_SCALER_METHOD_LABELS[m]
                         for m in FILTERBANK_SCALER_METHODS],
                        pygame.Rect(rect.x, rect.y + rect.h, rect.w, 0),
                    )
                    return True
                if meta is None:
                    if self.viewport_widget.handle_toggle(
                        key, self.config.viewport_boundary
                    ):
                        return True
                    setattr(self.config, key, not getattr(self.config, key))
                    return True
                self._dragging = key
                if key == "scale_log2":
                    self._update_log_slider(key, lx, rect, meta[0], meta[1])
                else:
                    self._update_slider(key, lx, rect, meta[0], meta[1])
                return True
            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            if self._dragging:
                self._dragging = None
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEMOTION:
            if self._dragging:
                if not event.buttons[0]:
                    self._dragging = None
                    return True
                mx, _ = event.pos
                lx = mx - pr.x
                rect, meta = self._item_map[self._dragging]
                if self._dragging == "scale_log2":
                    self._update_log_slider(self._dragging, lx, rect, meta[0], meta[1])
                else:
                    self._update_slider(self._dragging, lx, rect, meta[0], meta[1])
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEWHEEL:
            mx, my = pygame.mouse.get_pos()
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            if "scale_log2" in self._item_map:
                rect, _meta = self._item_map["scale_log2"]
                if rect.collidepoint(lx, ly):
                    step = 0.25 * (1 if event.y > 0 else -1)
                    cur = self.config.scale_log2
                    l2min, l2max = self._log2_range()
                    self.config.scale_log2 = round(
                        max(l2min, min(l2max, cur + step)), 3)
                    return True
            return self._handle_panel_wheel(event)

        return False

    def _update_log_slider(self, key: str, lx: int,
                           rect: pygame.Rect,
                           l2min: float, l2max: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        raw = l2min + frac * (l2max - l2min)
        for snap in self._snap_log2_values(l2min, l2max):
            if abs(raw - snap) < 0.10:
                raw = float(snap)
                break
        setattr(self.config, key, round(raw, 3))

    def _update_slider(self, key: str, lx: int,
                       rect: pygame.Rect,
                       vmin: float, vmax: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        val = round(vmin + frac * (vmax - vmin), 2)
        if self.viewport_widget.apply_slider_value(
            key, val, self.config.viewport_boundary
        ):
            return

    def render_dropdown_overlay(self) -> pygame.Surface | None:
        if not self._active_dropdown:
            return None
        opts = self._dropdown_opts
        if not opts:
            return None
        self._ensure_font()
        font = self.font
        pr = self.panel_rect
        item_h = self.ROW_H
        ow = self._dropdown_rect.w
        oh = len(opts) * item_h
        overlay = pygame.Surface((ow, oh), pygame.SRCALPHA)
        overlay.fill((40, 40, 55, 240))
        self._dropdown_item_rects = []
        for i, label in enumerate(opts):
            iy = i * item_h
            ir_screen = pygame.Rect(pr.x + self._dropdown_rect.x,
                                    pr.y + self._dropdown_rect.y + iy
                                    - self._panel_scroll_y,
                                    ow, item_h)
            self._dropdown_item_rects.append(ir_screen)
            pygame.draw.rect(overlay, (60, 60, 80), (0, iy, ow, item_h), 1)
            txt = font.render(label, True, (220, 220, 220))
            overlay.blit(txt, (4, iy + 3))
        return overlay


class FFTScalerPanel(Panel):
    """Dockable direct-playback panel for FFT-domain scaling."""

    ROW_H = 22
    PAD = 6
    BTN_H = 26
    _LOG2_MIN = -5.0
    _LOG2_MAX = 5.0
    _TARGET_MIDI = 72  # C5

    def __init__(self, config: FFTScalerConfig, *, side: str = "right") -> None:
        super().__init__(title="FFT Scaler", side=side)
        self.config = config
        self.viewport_widget = ViewportBoundaryWidget(prefix="fftvp")
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._dragging: str | None = None
        self._active_dropdown: str | None = None
        self._dropdown_opts: list[str] = []
        self._dropdown_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._dropdown_item_rects: list[pygame.Rect] = []
        self._status: str = "idle"
        self._error_msg: str = ""
        self._playing_channel: pygame.mixer.Channel | None = None
        self._playing_sound: Any = None
        self._synth_thread: threading.Thread | None = None
        self._is_active: Any = lambda: False
        self.on_play: Any = lambda: None
        self.on_stop: Any = lambda: None
        self.get_viewport_context: Any = lambda: {}
        self.get_pitch_slider_range: Any = lambda: (self._LOG2_MIN, self._LOG2_MAX)

    def stop_playback(self) -> None:
        if self._playing_channel is not None:
            try:
                self._playing_channel.stop()
            except Exception:
                pass
            self._playing_channel = None
        self._playing_sound = None
        self._status = "idle"

    def _open_dropdown(self, key: str, options: list[str], anchor: pygame.Rect) -> None:
        self._active_dropdown = key
        self._dropdown_opts = list(options)
        self._dropdown_rect = anchor

    def _select_dropdown(self, idx: int) -> None:
        key = self._active_dropdown
        self._active_dropdown = None
        if key == "method" and 0 <= idx < len(FFT_SCALER_METHODS):
            self.config.method = FFT_SCALER_METHODS[idx]

    def _pitch_log2_range(self) -> tuple[float, float]:
        try:
            lo, hi = self.get_pitch_slider_range()
        except Exception:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        lo = float(lo)
        hi = float(hi)
        if hi <= lo:
            lo, hi = self._LOG2_MIN, self._LOG2_MAX
        return lo, hi

    @staticmethod
    def _snap_log2_values(l2min: float, l2max: float) -> list[float]:
        i0 = int(math.ceil(l2min))
        i1 = int(math.floor(l2max))
        snaps = [float(i) for i in range(i0, i1 + 1)]
        if 0.0 not in snaps and l2min <= 0.0 <= l2max:
            snaps.append(0.0)
            snaps.sort()
        return snaps

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._item_map = {}

        if self._status == "playing" and self._playing_channel is not None:
            if not self._playing_channel.get_busy():
                self._status = "idle"
                self._playing_channel = None
                self._playing_sound = None

        bright = (210, 210, 210)
        dim = (150, 150, 155)
        if self._status == "synthesizing":
            status_col = (120, 180, 255)
            status_str = "Analyzing…"
        elif self._status == "playing":
            status_col = (100, 220, 120)
            status_str = (f"Playing  T×{self.config.time_scale:.3f}  "
                          f"P×{self.config.pitch_scale:.3f}")
        elif self._status == "error":
            status_col = (255, 100, 100)
            status_str = f"Error: {self._error_msg[:26]}"
        else:
            status_col = dim
            status_str = "Idle"

        method_label = FFT_SCALER_METHOD_LABELS.get(
            self.config.method, self.config.method.title())
        p_lo, p_hi = self._pitch_log2_range()
        p_snaps = self._snap_log2_values(p_lo, p_hi)
        t_snaps = self._snap_log2_values(self._LOG2_MIN, self._LOG2_MAX)

        rows: list[tuple[str, Any]] = [
            ("label_col", ("FFT Scaler", bright)),
            ("label_col", (status_str, status_col)),
            ("dropdown", ("method", "Method", method_label)),
            ("log_slider", ("time_scale_log2", "Time", self.config.time_scale_log2,
                            self._LOG2_MIN, self._LOG2_MAX, t_snaps)),
            ("log_slider", ("pitch_scale_log2", "Pitch", self.config.pitch_scale_log2,
                            p_lo, p_hi, p_snaps)),
            ("toggle", ("normalize", "Normalize loudness", self.config.normalize)),
        ]
        rows.extend(
            self.viewport_widget.build_rows(
                self.config.viewport_boundary,
                self.get_viewport_context(),
            )
        )
        rows.append(("play_stop", None))

        row_heights = [
            self.BTN_H if rtype == "play_stop" else self.ROW_H
            for rtype, _ in rows
        ]
        total_h = self.PAD * 2 + sum(rh + 2 for rh in row_heights)
        surf = pygame.Surface((w, total_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))

        y = self.PAD
        for (rtype, rdata), rh in zip(rows, row_heights):
            if rtype == "label_col":
                text, col = rdata
                txt = font.render(text, True, col)
                surf.blit(txt, (self.PAD, y + 3))
            elif rtype == "toggle":
                key, label, value = rdata
                rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, rh)
                box = pygame.Rect(self.PAD, y + 3, 16, 16)
                pygame.draw.rect(surf, (45, 45, 55), box)
                pygame.draw.rect(surf, (90, 90, 110), box, 1)
                if value:
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 2, box.y + 8),
                                     (box.x + 6, box.y + 12), 2)
                    pygame.draw.line(surf, (120, 200, 120),
                                     (box.x + 6, box.y + 12),
                                     (box.x + 13, box.y + 3), 2)
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD + 24, y + 3))
                self._item_map[key] = (rect, None)
            elif rtype == "dropdown":
                key, label, value = rdata
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD, y + 3))
                btn_w = 120
                btn_x = w - self.PAD - btn_w
                btn = pygame.Rect(btn_x, y + 1, btn_w, rh - 2)
                pygame.draw.rect(surf, (50, 50, 60), btn, border_radius=3)
                pygame.draw.rect(surf, (90, 90, 110), btn, 1, border_radius=3)
                val_txt = font.render(value, True, (220, 220, 220))
                surf.blit(val_txt, (btn.x + 6, y + 3))
                tri = [(btn.right - 14, y + 9), (btn.right - 6, y + 9), (btn.right - 10, y + 14)]
                pygame.draw.polygon(surf, (180, 180, 190), tri)
                self._item_map[key] = (btn, "dropdown")
            elif rtype == "slider":
                key, label, value, vmin, vmax, fmt = rdata
                txt = font.render(label, True, bright)
                surf.blit(txt, (self.PAD, y + 3))
                lbl_w = max(78, txt.get_width() + 8)
                val_txt = font.render(fmt.format(value), True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                frac = (value - vmin) / max(vmax - vmin, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                pygame.draw.rect(surf, (120, 140, 200),
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (vmin, vmax),
                )
            elif rtype == "log_slider":
                key, label, log2_val, l2min, l2max, snaps = rdata
                lbl_txt = font.render(label, True, bright)
                surf.blit(lbl_txt, (self.PAD, y + 3))
                lbl_w = lbl_txt.get_width() + 8
                actual = 2.0 ** log2_val
                val_str = f"÷{1.0/actual:.2f}" if actual < 1.0 else f"×{actual:.2f}"
                val_txt = font.render(val_str, True, (200, 200, 200))
                val_x = w - self.PAD - val_txt.get_width()
                surf.blit(val_txt, (val_x, y + 3))
                track_x = self.PAD + lbl_w
                track_w = max(40, val_x - track_x - 8)
                track = pygame.Rect(track_x, y + 8, track_w, 6)
                pygame.draw.rect(surf, (50, 50, 60), track)
                for snap in snaps:
                    frac_s = (snap - l2min) / max(l2max - l2min, 1e-9)
                    tx = track.x + int(round(frac_s * track.w))
                    h_tick = 8 if snap == 0.0 else 4
                    pygame.draw.line(surf, (90, 90, 110),
                                     (tx, track.y - 1),
                                     (tx, track.y + h_tick), 1)
                frac = (log2_val - l2min) / max(l2max - l2min, 1e-9)
                frac = max(0.0, min(1.0, frac))
                thumb_x = track.x + int(round(frac * track.w))
                thumb_col = (100, 200, 120) if abs(log2_val) < 0.05 else (120, 140, 200)
                pygame.draw.rect(surf, thumb_col,
                                 pygame.Rect(thumb_x - 5, y + 3, 10, 16))
                self._item_map[key] = (
                    pygame.Rect(track.x, y, track.w, rh),
                    (l2min, l2max),
                )
            elif rtype == "play_stop":
                btn_w = (w - self.PAD * 3) // 2
                playing = self._status in ("playing", "synthesizing")
                play_rect = pygame.Rect(self.PAD, y, btn_w, rh)
                stop_rect = pygame.Rect(self.PAD * 2 + btn_w, y, btn_w, rh)
                pygame.draw.rect(surf, (50, 100, 50) if not playing else (35, 60, 35),
                                 play_rect, border_radius=4)
                pygame.draw.rect(surf, (80, 160, 80), play_rect, 1, border_radius=4)
                pygame.draw.rect(surf, (100, 50, 50) if playing else (50, 35, 35),
                                 stop_rect, border_radius=4)
                pygame.draw.rect(surf, (160, 80, 80), stop_rect, 1, border_radius=4)
                ptxt = font.render("▶ Play", True,
                                   (180, 255, 180) if not playing else (100, 140, 100))
                stxt = font.render("■ Stop", True,
                                   (255, 180, 180) if playing else (120, 80, 80))
                surf.blit(ptxt, (play_rect.x + (btn_w - ptxt.get_width()) // 2,
                                 play_rect.y + (rh - ptxt.get_height()) // 2))
                surf.blit(stxt, (stop_rect.x + (btn_w - stxt.get_width()) // 2,
                                 stop_rect.y + (rh - stxt.get_height()) // 2))
                self._item_map["_play"] = (play_rect, "play")
                self._item_map["_stop"] = (stop_rect, "stop")
            y += rh + 2
        return surf

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False
        pr = self.panel_rect
        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos
            if self._active_dropdown:
                for i, ir in enumerate(self._dropdown_item_rects):
                    if ir.collidepoint(mx, my):
                        self._select_dropdown(i)
                        return True
                self._active_dropdown = None
                return True
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            for key, (rect, meta) in self._item_map.items():
                if not rect.collidepoint(lx, ly):
                    continue
                if meta == "play":
                    if self._status not in ("playing", "synthesizing"):
                        self.on_play()
                    return True
                if meta == "stop":
                    self.on_stop()
                    return True
                if meta == "dropdown":
                    self._open_dropdown(
                        key,
                        [FFT_SCALER_METHOD_LABELS[m] for m in FFT_SCALER_METHODS],
                        pygame.Rect(rect.x, rect.y + rect.h, rect.w, 0),
                    )
                    return True
                if meta is None:
                    if self.viewport_widget.handle_toggle(
                        key, self.config.viewport_boundary
                    ):
                        return True
                    setattr(self.config, key, not getattr(self.config, key))
                    return True
                self._dragging = key
                if key in ("time_scale_log2", "pitch_scale_log2"):
                    self._update_log_slider(key, lx, rect, meta[0], meta[1])
                else:
                    self._update_slider(key, lx, rect, meta[0], meta[1])
                return True
            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            if self._dragging:
                self._dragging = None
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEMOTION:
            if self._dragging:
                if not event.buttons[0]:
                    self._dragging = None
                    return True
                mx, _ = event.pos
                lx = mx - pr.x
                rect, meta = self._item_map[self._dragging]
                if self._dragging in ("time_scale_log2", "pitch_scale_log2"):
                    self._update_log_slider(self._dragging, lx, rect, meta[0], meta[1])
                else:
                    self._update_slider(self._dragging, lx, rect, meta[0], meta[1])
                return True
            mx, my = event.pos
            return pr.collidepoint(mx, my)

        if event.type == MOUSEWHEEL:
            mx, my = pygame.mouse.get_pos()
            if not pr.collidepoint(mx, my):
                return False
            lx = mx - pr.x
            ly = my - pr.y + self._panel_scroll_y
            for key in ("time_scale_log2", "pitch_scale_log2"):
                if key in self._item_map:
                    rect, meta = self._item_map[key]
                    if rect.collidepoint(lx, ly):
                        step = 0.25 * (1 if event.y > 0 else -1)
                        cur = getattr(self.config, key)
                        setattr(self.config, key, round(
                            max(meta[0], min(meta[1], cur + step)), 3))
                        return True
            return self._handle_panel_wheel(event)

        return False

    def _update_log_slider(self, key: str, lx: int,
                           rect: pygame.Rect,
                           l2min: float, l2max: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        raw = l2min + frac * (l2max - l2min)
        for snap in self._snap_log2_values(l2min, l2max):
            if abs(raw - snap) < 0.10:
                raw = float(snap)
                break
        setattr(self.config, key, round(raw, 3))

    def _update_slider(self, key: str, lx: int,
                       rect: pygame.Rect,
                       vmin: float, vmax: float) -> None:
        frac = max(0.0, min(1.0, (lx - rect.x) / max(rect.w, 1)))
        val = round(vmin + frac * (vmax - vmin), 2)
        if self.viewport_widget.apply_slider_value(
            key, val, self.config.viewport_boundary
        ):
            return

    def render_dropdown_overlay(self) -> pygame.Surface | None:
        if not self._active_dropdown:
            return None
        opts = self._dropdown_opts
        if not opts:
            return None
        self._ensure_font()
        font = self.font
        pr = self.panel_rect
        item_h = self.ROW_H
        ow = self._dropdown_rect.w
        oh = len(opts) * item_h
        overlay = pygame.Surface((ow, oh), pygame.SRCALPHA)
        overlay.fill((40, 40, 55, 240))
        self._dropdown_item_rects = []
        for i, label in enumerate(opts):
            iy = i * item_h
            ir_screen = pygame.Rect(pr.x + self._dropdown_rect.x,
                                    pr.y + self._dropdown_rect.y + iy
                                    - self._panel_scroll_y,
                                    ow, item_h)
            self._dropdown_item_rects.append(ir_screen)
            pygame.draw.rect(overlay, (60, 60, 80), (0, iy, ow, item_h), 1)
            txt = font.render(label, True, (220, 220, 220))
            overlay.blit(txt, (4, iy + 3))
        return overlay


# ---------------------------------------------------------------------------
# Synthesis panel — synthesis products list + controls
# ---------------------------------------------------------------------------

_SYNTH_SOURCE_TYPES = ["cqt", "filterbank", "mixed"]
_SYNTH_SOURCE_LABELS = {"cqt": "CQT Viewport", "filterbank": "Filterbank",
                         "mixed": "Mixed (band iCQT)"}
_STATUS_COLORS = {
    "queued": (120, 120, 140),
    "running": (80, 180, 255),
    "done": (80, 220, 100),
    "error": (255, 80, 80),
}

# Backing data channel → synthesis role routing
ROUTE_SOURCES = ["Ch1", "Ch2", "Ch3", "Ch4", "Alpha"]
ROUTE_SOURCE_TARGETS = {"Ch1": 0, "Ch2": 1, "Ch3": 2, "Ch4": 3, "Alpha": 4}
ROUTE_ROLES = ["magnitude", "phase", "mask"]
ROUTE_ROLE_LABELS = {"magnitude": "Mag", "phase": "Phase", "mask": "Mask"}
ROUTE_AUDIO_CHANNELS = ["left", "right"]
ROUTE_AUDIO_CH_LABELS = {"left": "L", "right": "R"}
MONO_MIX_MODES = ["Average", "L Only", "R Only", "Mid", "Side"]


@dataclass
class ChannelRouting:
    """Maps backing data channels (Ch1-Ch4, Alpha) to synthesis roles.

    Audio is always stored as L+R internally.  Mono signals are
    derived from L+R via *mono_mix_mode* (index into MONO_MIX_MODES).
    """
    left_mag: str = "Ch1"
    left_phase: str = "Ch2"
    left_mask: str = "Alpha"
    right_mag: str = "Ch3"
    right_phase: str = "Ch4"
    right_mask: str = "Alpha"
    mono_mix_mode: int = 0  # index into MONO_MIX_MODES

    def get(self, audio_ch: str, role: str) -> str:
        """Return the backing data channel key for given audio_ch and role."""
        return getattr(self, f"{audio_ch}_{role}", "Ch1")

    def set(self, audio_ch: str, role: str, source: str) -> None:
        setattr(self, f"{audio_ch}_{role}", source)

    def resolve_field(self, source: str,
                      field_sources: list,
                      field_configs: list) -> str | None:
        """Return the raw_arrays field name assigned to a backing channel.

        Scans *field_configs* for the first field whose *target* matches
        the numeric target of *source* (e.g. Ch1→0).  Returns the
        corresponding :class:`FieldSource` name, or *None*.
        """
        tgt = ROUTE_SOURCE_TARGETS.get(source)
        if tgt is None:
            return None
        for fs, cfg in zip(field_sources, field_configs):
            if cfg.target == tgt and fs.available:
                return fs.name
        return None


class SynthesisPanel(Panel):
    """Async synthesis job queue panel.

    Holds a list of :class:`SynthJob` entries.  Jobs are executed on a
    background thread; completed jobs can be played back instantly.
    """

    ROW_H = 22
    BTN_W = 40
    PAD = 6
    _SYNTH_MODE_KEYS = ["icqt", "fb", "hybrid", "fb_tf", "wavelet", "transplant", "hybrid_cwt"]
    _SYNTH_MODE_OPTIONS = [
        "iCQT (full CQT)",
        "Filterbank (full FB)",
        "Hybrid (FB low / iCQT high)",
        "FB from TF (viewport)",
        "Wavelet reconstruction",
        "TF Transplant (viewport)",
        "Hybrid CWT (CWT low / iCQT high)",
    ]

    def __init__(self, *, side: str = "right") -> None:
        super().__init__(title="Synthesis", side=side)
        self.jobs: list[SynthJob] = []
        self.job_list = ScrollableItemList("Synthesis Jobs", max_visible=10)
        self._next_id: int = 1
        self._worker_thread: threading.Thread | None = None
        self._lock = threading.Lock()
        self.synth_mode_idx: int = 0  # index into _SYNTH_MODE_KEYS
        self.channel_routing = ChannelRouting()
        self.use_adjusted: bool = False   # apply viewer norm/gamma/scale to synth data
        # Callbacks set by the viewer
        self.on_play: Any = None          # (SynthJob) -> None
        self.on_stop: Any = None          # () -> None
        self.on_synth_icqt: Any = None    # () -> None
        self.on_synth_fb: Any = None      # () -> None
        self.on_synth_hybrid: Any = None  # () -> None
        self.on_synth_fb_tf: Any = None   # () -> None
        self.on_synth_wavelet: Any = None # () -> None
        self.on_synth_transplant: Any = None  # () -> None
        self.on_synth_hybrid_cwt: Any = None  # () -> None
        self._playing_job_id: int | None = None
        # Per-row button rects (surface-local)
        self._play_rects: dict[int, pygame.Rect] = {}
        self._del_rects: dict[int, pygame.Rect] = {}
        # Controls state — bound to viewer attrs via get/set callbacks
        self._get_phase_mode: Any = lambda: "original"
        self._set_phase_mode: Any = lambda v: None
        self._get_normalize: Any = lambda: True
        self._set_normalize: Any = lambda v: None
        self._get_fb_n_bands: Any = lambda: 16
        self._set_fb_n_bands: Any = lambda v: None
        self._has_audio: Any = lambda: False
        self._has_synth: Any = lambda: False
        self._has_wavelet: Any = lambda: False
        # Transplant destination frequency (Hz)
        self.transplant_dst_f0: float = 200.0
        self.transplant_dst_f1: float = 800.0
        # Dropdown UI state
        self._active_dropdown: str | None = None
        self._dropdown_opts: list[str] = []
        self._dropdown_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._dropdown_item_rects: list[pygame.Rect] = []
        # Button rects for controls
        self._ctrl_rects: dict[str, pygame.Rect] = {}


    # -- job management ----------------------------------------------------

    def submit(self, job: SynthJob) -> None:
        job.job_id = self._next_id
        self._next_id += 1
        job.submitted_at = time.time()
        with self._lock:
            self.jobs.append(job)
        self._ensure_worker()

    def _ensure_worker(self) -> None:
        if self._worker_thread is not None and self._worker_thread.is_alive():
            return
        self._worker_thread = threading.Thread(
            target=self._worker_loop, daemon=True)
        self._worker_thread.start()

    def _worker_loop(self) -> None:
        while True:
            job: SynthJob | None = None
            with self._lock:
                for j in self.jobs:
                    if j.status == "queued":
                        j.status = "running"
                        job = j
                        break
            if job is None:
                return  # nothing left — thread exits
            try:
                self._execute(job)
                job.status = "done"
                job.completed_at = time.time()
            except Exception as exc:
                job.status = "error"
                job.error_msg = str(exc)
                job.completed_at = time.time()

    @staticmethod
    def _apply_field_adjustment(arr: np.ndarray,
                                cfg: "FieldConfig",
                                gd: "GlobalDefaults | None") -> np.ndarray:
        """Apply norm → gamma → scale to *arr* on CPU, mirroring the shader.

        Uses per-field config; falls back to *gd* when ``cfg.use_global``
        is set.  Returns a new array — never mutates the input.
        """
        norm_mode = gd.norm_mode if (cfg.use_global and gd) else cfg.norm_mode
        gamma = gd.gamma if (cfg.use_global and gd) else cfg.gamma
        scale = gd.scale if (cfg.use_global and gd) else cfg.scale
        return _apply_curve(arr, norm_mode, gamma, scale)

    @staticmethod
    def _resolve_routing(p: dict) -> dict[str, np.ndarray]:
        """Build a *routed_arrays* dict from channel routing + field mappings.

        Returns a dict with keys like ``"magnitude_left"``,
        ``"phase_left"``, ``"mask_left"``, etc., mapping to the
        native-dtype raw arrays from the backing data channels the user
        selected in the routing panel.

        When ``p["use_adjusted"]`` is truthy, applies the per-field
        norm/gamma/scale pipeline (mirroring the GPU shader) to each
        array before returning it.

        Falls back to the default CQT fields when no routing is provided.

        The optional ``p["field_resolver"]`` callable ``(str) -> ndarray | None``
        is used to look up *any* field name — including derived fields
        (``mag_left``, ``mag_right``, …) and filterbank grids
        (``fb_mag_left``, …) that are not directly stored in
        ``p["raw_arrays"]``.
        """
        raw: dict[str, np.ndarray] = p["raw_arrays"]
        resolver = p.get("field_resolver")  # callable(str) -> ndarray|None
        routing: ChannelRouting | None = p.get("routing")
        field_sources: list | None = p.get("field_sources")
        field_configs: list | None = p.get("field_configs")
        use_adjusted: bool = bool(p.get("use_adjusted", False))
        global_defaults: GlobalDefaults | None = p.get("global_defaults")

        def _lookup(fname: str) -> np.ndarray | None:
            """Try the resolver first, then fall back to raw dict."""
            if resolver is not None:
                arr = resolver(fname)
                if arr is not None:
                    return arr
            return raw.get(fname)

        result: dict[str, np.ndarray] = {}

        if routing is None or field_sources is None or field_configs is None:
            # Legacy fallback — use the hardcoded CQT complex fields
            for side in ("left", "right"):
                mag = _lookup(f"mag_{side}")
                if mag is None:
                    mag = _lookup(f"real_{side}")
                pha = _lookup(f"phase_{side}")
                if pha is None:
                    pha = _lookup(f"imag_{side}")
                result[f"magnitude_{side}"] = mag
                result[f"phase_{side}"] = pha
            return result

        for audio_ch in ROUTE_AUDIO_CHANNELS:
            for role in ROUTE_ROLES:
                src_key = routing.get(audio_ch, role)
                fname = routing.resolve_field(
                    src_key, field_sources, field_configs)
                if fname is not None:
                    arr = _lookup(fname)
                    if arr is not None:
                        if use_adjusted:
                            tgt = ROUTE_SOURCE_TARGETS.get(src_key)
                            for fs, fc in zip(field_sources, field_configs):
                                if fc.target == tgt and fs.available and fs.name == fname:
                                    arr = SynthesisPanel._apply_field_adjustment(
                                        arr, fc, global_defaults)
                                    break
                        result[f"{role}_{audio_ch}"] = arr
                    else:
                        result[f"{role}_{audio_ch}"] = None  # type: ignore[assignment]
                else:
                    result[f"{role}_{audio_ch}"] = None  # type: ignore[assignment]
        return result

    def _execute(self, job: SynthJob) -> None:
        p = job.params
        synth: ViewportSynthPlayer = p["synth"]
        if job.source_type == "cqt":
            routed = self._resolve_routing(p)
            result = synth.synthesise_to_array(
                p["raw_arrays"], p["freqs"], p["times"],
                p["view_x0"], p["view_x1"],
                p["view_y0"], p["view_y1"],
                p["n_frames"], p["n_bins"],
                p["t_start"], p["t_dur"], p["sr"],
                p["is_stereo"], p.get("normalize", True),
                phase_mode=p.get("phase_mode", "original"),
                routed_arrays=routed)
            if result is None:
                raise ValueError("Empty viewport")
            stereo, dur, vt0, vt1 = result
            job.result_stereo = stereo
            job.duration = dur
            job.view_t0 = vt0
            job.view_t1 = vt1
        elif job.source_type == "mixed":
            cqt = p["cqt"]
            freqs = p["freqs"]
            n_total = p["n_total_bins"]
            band_bin_map = p["band_bin_map"]
            band_mask = p.get("band_mask")
            sr = p["sr"]
            sig = synth.recombine_bands_icqt(
                cqt, freqs, n_total, band_bin_map, band_mask)
            # Normalise to int16 stereo
            peak = max(np.abs(sig).max(), 1e-12)
            sig = sig / peak * 0.8
            i16 = (sig * 32767).clip(-32768, 32767).astype(np.int16)
            stereo = np.column_stack([i16, i16])
            dur = len(sig) / sr
            job.result_stereo = stereo
            job.duration = dur
        elif job.source_type == "filterbank":
            fb: FilterBankDecomposition = p["filterbank"]
            band_mask = p.get("band_mask")
            sr = p["sr"]
            sig = fb.reconstruct(band_mask).astype(np.float64)
            peak = max(np.abs(sig).max(), 1e-12)
            sig = sig / peak * 0.8
            i16 = (sig * 32767).clip(-32768, 32767).astype(np.int16)
            stereo = np.column_stack([i16, i16])
            dur = len(sig) / sr
            job.result_stereo = stereo
            job.duration = dur
        elif job.source_type == "fb_audio":
            result = synth.synthesise_filterbank_from_audio(
                p["audio_path"], p["sr"],
                p["t0"], p["t1"],
                p["f_lo"], p["f_hi"],
                n_bands=p.get("n_bands", 16),
                is_stereo=p.get("is_stereo", True),
                normalize=p.get("normalize", True))
            if result is None:
                raise ValueError("Empty viewport or no audio")
            stereo, dur, vt0, vt1 = result
            job.result_stereo = stereo
            job.duration = dur
            job.view_t0 = vt0
            job.view_t1 = vt1
        elif job.source_type == "fb_tf":
            self._execute_fb_tf(job, synth, p)
        elif job.source_type == "wavelet":
            self._execute_wavelet(job, p)
        elif job.source_type == "hybrid":
            self._execute_hybrid(job, synth, p)
        elif job.source_type == "hybrid_cwt":
            self._execute_hybrid_cwt(job, synth, p)
        elif job.source_type == "transplant":
            self._execute_transplant(job, p)

    def _execute_fb_tf(self, job: SynthJob,
                       synth: "ViewportSynthPlayer",
                       p: dict) -> None:
        """FB-from-TF synthesis: interpret TF viewport data as band
        envelopes and reconstruct via additive synthesis.

        Each frequency row in the viewport is treated as one band.
        The routed magnitude data supplies per-band amplitude envelopes.

        Phase behaviour follows ``phase_mode`` (same options as iCQT):

        * ``"zero_phase"`` — pure envelope summation, no carrier or
          phase modulation.  This is the default.
        * ``"original"`` — use routed phase data directly as
          instantaneous phase (can be CQT phase, filterbank phase,
          or any data channel the user routes to the phase slot).
        * ``"griffin_lim"`` — derive phase via Griffin-Lim iteration
          over a per-band STFT round-trip.
        """
        sr: int = p["sr"]
        freqs: np.ndarray = p["freqs"]
        times: np.ndarray = p["times"]
        x0, x1 = int(p["view_x0"]), int(p["view_x1"])
        y0, y1 = int(p["view_y0"]), int(p["view_y1"])
        is_stereo: bool = p.get("is_stereo", True)
        normalize: bool = p.get("normalize", True)
        phase_mode: str = p.get("phase_mode", "zero_phase")

        routed = self._resolve_routing(p)

        n_frames = x1 - x0
        n_bins = y1 - y0
        if n_frames <= 0 or n_bins <= 0:
            raise ValueError("Empty viewport")

        view_freqs = freqs[y0:y1]
        view_times = times[x0:x1]
        dur = float(view_times[-1] - view_times[0]) if len(view_times) > 1 else 0.0
        vt0 = float(view_times[0])
        vt1 = float(view_times[-1])
        n_samples = int(round(dur * sr)) if dur > 0 else n_frames * synth.hop_length
        if n_samples <= 0:
            raise ValueError("Zero-length output")

        def _channel_from_routed(routed_d: dict, ch: str) -> np.ndarray:
            mag_arr = routed_d.get(f"magnitude_{ch}")
            pha_arr = routed_d.get(f"phase_{ch}")
            # Build envelope grid  (n_bins, n_frames)
            if mag_arr is not None:
                env = np.abs(np.asarray(mag_arr[y0:y1, x0:x1],
                                        dtype=np.float64))
            else:
                env = np.ones((n_bins, n_frames), dtype=np.float64)
            if pha_arr is not None and phase_mode == "original":
                pha = np.asarray(pha_arr[y0:y1, x0:x1], dtype=np.float64)
            else:
                pha = None

            output = np.zeros(n_samples, dtype=np.float64)
            frame_t = np.linspace(0.0, 1.0, n_frames)
            sample_t = np.linspace(0.0, 1.0, n_samples)
            t = np.arange(n_samples, dtype=np.float64) / sr

            if phase_mode == "zero_phase":
                # Pure envelope summation — no carrier, no phase
                for bi in range(n_bins):
                    amp = np.interp(sample_t, frame_t, env[bi])
                    output += amp
            elif phase_mode == "freq_carrier":
                # Free-running cosine carrier at each band centre freq
                for bi in range(n_bins):
                    fc = float(view_freqs[bi])
                    amp = np.interp(sample_t, frame_t, env[bi])
                    output += amp * np.cos(2.0 * np.pi * fc * t)
            elif phase_mode == "original" and pha is not None:
                # Use routed phase data as instantaneous phase
                for bi in range(n_bins):
                    amp = np.interp(sample_t, frame_t, env[bi])
                    inst_phase = np.interp(sample_t, frame_t, pha[bi])
                    output += amp * np.cos(inst_phase)
            elif phase_mode == "griffin_lim":
                # Griffin-Lim: iteratively estimate phase from magnitude.
                # Build a complex spectrogram-like matrix from the band
                # envelopes, run Griffin-Lim round-trips through per-bin
                # iFFT/FFT, then sum the resulting band signals.
                n_gl_iters = 20
                rng = np.random.default_rng(42)
                # Random initial phase per (bin, frame)
                est_phase = 2.0 * np.pi * rng.random((n_bins, n_frames))
                hop = max(1, n_samples // n_frames)
                for _it in range(n_gl_iters):
                    # Synthesise with current phase estimate
                    sig = np.zeros(n_samples, dtype=np.float64)
                    for bi in range(n_bins):
                        fc = float(view_freqs[bi])
                        amp = np.interp(sample_t, frame_t, env[bi])
                        ph = np.interp(sample_t, frame_t, est_phase[bi])
                        sig += amp * np.cos(2.0 * np.pi * fc * t + ph)
                    # Re-analyse: extract instantaneous phase at each
                    # band centre via windowed DFT
                    for bi in range(n_bins):
                        fc = float(view_freqs[bi])
                        for fi in range(n_frames):
                            centre = int(fi * hop)
                            half_w = hop
                            s0 = max(0, centre - half_w)
                            s1 = min(n_samples, centre + half_w)
                            seg = sig[s0:s1]
                            if len(seg) == 0:
                                continue
                            tt = np.arange(len(seg), dtype=np.float64) / sr
                            ref = np.exp(-2j * np.pi * fc * tt)
                            est_phase[bi, fi] = np.angle(np.sum(seg * ref))
                # Final synthesis with converged phases
                for bi in range(n_bins):
                    fc = float(view_freqs[bi])
                    amp = np.interp(sample_t, frame_t, env[bi])
                    ph = np.interp(sample_t, frame_t, est_phase[bi])
                    output += amp * np.cos(2.0 * np.pi * fc * t + ph)
            else:
                # Fallback: if "original" selected but no phase data
                # routed, degrade gracefully to zero-phase
                for bi in range(n_bins):
                    amp = np.interp(sample_t, frame_t, env[bi])
                    output += amp
            return output

        sig_l = _channel_from_routed(routed, "left")
        if is_stereo:
            sig_r = _channel_from_routed(routed, "right")
        else:
            sig_r = sig_l

        # Fade edges
        fade = min(256, n_samples // 4)
        if fade > 1:
            ramp = np.linspace(0.0, 1.0, fade)
            sig_l[:fade] *= ramp
            sig_l[-fade:] *= ramp[::-1]
            sig_r[:fade] *= ramp
            sig_r[-fade:] *= ramp[::-1]

        if normalize:
            peak = max(np.abs(sig_l).max(), np.abs(sig_r).max(), 1e-12)
            sig_l = sig_l / peak * 0.8
            sig_r = sig_r / peak * 0.8

        i16_l = (sig_l * 32767).clip(-32768, 32767).astype(np.int16)
        i16_r = (sig_r * 32767).clip(-32768, 32767).astype(np.int16)
        stereo = np.column_stack([i16_l, i16_r])
        job.result_stereo = stereo
        job.duration = dur
        job.view_t0 = vt0
        job.view_t1 = vt1

    @staticmethod
    def _execute_wavelet(job: SynthJob, p: dict) -> None:
        """Wavelet reconstruction: inverse DWT or iCWT of viewport coefficients.

        Auto-detects DWT vs CWT from ``wv_meta["type"]``.
        """
        wv_meta: dict = p.get("wv_meta", {})
        sr: int = p["sr"]
        t0: float = p["t0"]
        t1: float = p["t1"]
        normalize: bool = p.get("normalize", True)
        sig = _reconstruct_wavelet_viewport(
            sr=sr,
            t0=t0,
            t1=t1,
            wv_meta=wv_meta,
            wv_coeffs=p.get("wv_coeffs"),
            W_complex=p.get("wv_W"),
            wv_freqs=p.get("wv_freqs"),
        )

        # Fade edges
        n_samples = len(sig)
        fade = min(256, n_samples // 4)
        if fade > 1:
            ramp = np.linspace(0.0, 1.0, fade)
            sig[:fade] *= ramp
            sig[-fade:] *= ramp[::-1]

        if normalize:
            peak = max(np.abs(sig).max(), 1e-12)
            sig = sig / peak * 0.8

        dur = float(t1 - t0)
        i16 = (sig * 32767).clip(-32768, 32767).astype(np.int16)
        stereo = np.column_stack([i16, i16])
        job.result_stereo = stereo
        job.duration = dur
        job.view_t0 = t0
        job.view_t1 = t1

    def _execute_hybrid(self, job: SynthJob, synth: "ViewportSynthPlayer",
                        p: dict) -> None:
        """Hybrid synthesis: FB below crossover + iCQT above, with
        complementary Linkwitz-Riley filtering at the boundary.
        Uses crossover.lr_decompose for perfect reconstruction.
        """
        import torch
        from crossover import lr_decompose, lr_reconstruct

        sr = p["sr"]
        cross_hz = float(p["cross_hz"])
        is_stereo: bool = p.get("is_stereo", True)
        normalize: bool = p.get("normalize", True)

        # --- iCQT portion (full viewport, will be high-passed) ---
        routed = self._resolve_routing(p)
        icqt_result = synth.synthesise_to_array(
            p["raw_arrays"], p["freqs"], p["times"],
            p["view_x0"], p["view_x1"],
            p["view_y0"], p["view_y1"],
            p["n_frames"], p["n_bins"],
            p["t_start"], p["t_dur"], sr,
            is_stereo, False,
            phase_mode=p.get("phase_mode", "original"),
            routed_arrays=routed)
        if icqt_result is None:
            raise ValueError("Empty viewport")
        icqt_stereo_i16, dur, vt0, vt1 = icqt_result
        icqt_f = icqt_stereo_i16.astype(np.float64) / 32767.0

        # --- FB portion (from audio, will be low-passed) ---
        fb_result = synth.synthesise_filterbank_from_audio(
            p["audio_path"], sr, vt0, vt1,
            float(p["f_lo"]), cross_hz,
            n_bands=p.get("n_bands", 16),
            is_stereo=is_stereo,
            normalize=False)
        if fb_result is None:
            job.result_stereo = icqt_stereo_i16
            job.duration = dur
            job.view_t0 = vt0
            job.view_t1 = vt1
            return

        fb_stereo_i16, _, _, _ = fb_result
        fb_f = fb_stereo_i16.astype(np.float64) / 32767.0

        # Match lengths
        n = min(len(icqt_f), len(fb_f))
        icqt_f = icqt_f[:n]
        fb_f = fb_f[:n]

        # --- Crossover filtering via crossover.py (perfect reconstruction) ---
        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        for ch in range(icqt_f.shape[1]):
            # Split iCQT into [low, high] bands at crossover
            icqt_bands = lr_decompose(
                torch.as_tensor(icqt_f[:, ch], device=device, dtype=torch.float64),
                [cross_hz], sr, order=8)
            # Keep only the high band from iCQT
            icqt_high = icqt_bands[..., 1, :].cpu().numpy()

            # Split FB into [low, high] bands at crossover
            fb_bands = lr_decompose(
                torch.as_tensor(fb_f[:, ch], device=device, dtype=torch.float64),
                [cross_hz], sr, order=8)
            # Keep only the low band from FB
            fb_low = fb_bands[..., 0, :].cpu().numpy()

            icqt_f[:n, ch] = icqt_high[:n]
            fb_f[:n, ch] = fb_low[:n]

        mixed = icqt_f + fb_f

        if normalize:
            peak = max(np.abs(mixed).max(), 1e-12)
            mixed = mixed / peak * 0.8
        else:
            mixed = np.clip(mixed, -1.0, 1.0)
        stereo = (mixed * 32767).clip(-32768, 32767).astype(np.int16)
        job.result_stereo = stereo
        job.duration = dur
        job.view_t0 = vt0
        job.view_t1 = vt1

    def _execute_hybrid_cwt(self, job: SynthJob,
                            synth: "ViewportSynthPlayer",
                            p: dict) -> None:
        """Hybrid CWT synthesis: CWT below crossover + iCQT above,
        with complementary Linkwitz-Riley filtering at the boundary.
        Uses crossover.lr_decompose for perfect reconstruction.
        """
        import torch
        from crossover import lr_decompose

        sr = p["sr"]
        cross_hz = float(p["cross_hz"])
        is_stereo: bool = p.get("is_stereo", True)
        normalize: bool = p.get("normalize", True)

        # --- iCQT portion (full viewport, will be high-passed) ---
        routed = self._resolve_routing(p)
        icqt_result = synth.synthesise_to_array(
            p["raw_arrays"], p["freqs"], p["times"],
            p["view_x0"], p["view_x1"],
            p["view_y0"], p["view_y1"],
            p["n_frames"], p["n_bins"],
            p["t_start"], p["t_dur"], sr,
            is_stereo, False,
            phase_mode=p.get("phase_mode", "original"),
            routed_arrays=routed)
        if icqt_result is None:
            raise ValueError("Empty viewport")
        icqt_stereo_i16, dur, vt0, vt1 = icqt_result
        icqt_f = icqt_stereo_i16.astype(np.float64) / 32767.0

        # --- CWT portion (from stored scalogram, will be low-passed) ---
        W_complex: np.ndarray | None = p.get("wv_W")
        wv_freqs: np.ndarray | None = p.get("wv_freqs")
        wv_meta: dict = p.get("wv_meta", {})
        if W_complex is None or wv_freqs is None:
            job.result_stereo = icqt_stereo_i16
            job.duration = dur
            job.view_t0 = vt0
            job.view_t1 = vt1
            return

        target_len = len(icqt_f)
        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        cwt_sig = _reconstruct_wavelet_viewport(
            sr=sr,
            t0=vt0,
            t1=vt1,
            wv_meta=wv_meta,
            W_complex=W_complex,
            wv_freqs=wv_freqs,
            target_len=target_len,
        )

        # Make mono CWT into stereo shape
        cwt_f = np.column_stack([cwt_sig, cwt_sig])

        # Match lengths
        n = min(len(icqt_f), len(cwt_f))
        icqt_f = icqt_f[:n]
        cwt_f = cwt_f[:n]

        # --- Crossover filtering via crossover.py (perfect reconstruction) ---
        for ch in range(icqt_f.shape[1]):
            icqt_bands = lr_decompose(
                torch.as_tensor(icqt_f[:, ch], device=device, dtype=torch.float64),
                [cross_hz], sr, order=8)
            icqt_f[:n, ch] = icqt_bands[..., 1, :].cpu().numpy()[:n]

            cwt_bands = lr_decompose(
                torch.as_tensor(cwt_f[:, ch], device=device, dtype=torch.float64),
                [cross_hz], sr, order=8)
            cwt_f[:n, ch] = cwt_bands[..., 0, :].cpu().numpy()[:n]

        mixed = icqt_f + cwt_f
        if normalize:
            peak = max(np.abs(mixed).max(), 1e-12)
            mixed = mixed / peak * 0.8
        else:
            mixed = np.clip(mixed, -1.0, 1.0)
        stereo = (mixed * 32767).clip(-32768, 32767).astype(np.int16)
        job.result_stereo = stereo
        job.duration = dur
        job.view_t0 = vt0
        job.view_t1 = vt1

    def _execute_transplant(self, job: SynthJob, p: dict) -> None:
        """TF transplant synthesis: move a viewport TF region to a new
        frequency range using the auto-dispatched STFT/CWT engine.

        The source region is the current viewport rectangle.  The
        destination frequency range is specified as ``dst_f0``/``dst_f1``
        in the job params.  Time span is preserved.
        """
        import torch
        from tf_surgery import (
            TFRegion, affine_translate, transplant, working_range,
        )

        sr = p["sr"]
        freqs = p["freqs"]
        duration = p["duration"]
        normalize = p.get("normalize", True)

        # Source region from viewport
        src_t0 = p["src_t0"]
        src_t1 = p["src_t1"]
        src_f0 = p["src_f0"]
        src_f1 = p["src_f1"]

        # Destination frequency range
        dst_f0 = p["dst_f0"]
        dst_f1 = p["dst_f1"]

        # Clamp to working range
        wr = working_range(sr, duration)
        src_f0 = max(src_f0, wr.f_min)
        src_f1 = min(src_f1, wr.f_max)
        dst_f0 = max(dst_f0, wr.f_min)
        dst_f1 = min(dst_f1, wr.f_max)

        if src_f1 <= src_f0 or dst_f1 <= dst_f0:
            raise ValueError("Degenerate frequency range after clamping "
                             f"to working range [{wr.f_min:.2f}, {wr.f_max:.1f}] Hz")

        src = TFRegion(t0=src_t0, t1=src_t1, f0=src_f0, f1=src_f1)

        # Build affine: pure frequency translation in normalised coords
        # df_norm = (dst_centre - src_centre) / src_span → normalised shift
        src_fc = (src_f0 + src_f1) / 2
        dst_fc = (dst_f0 + dst_f1) / 2
        src_span = src_f1 - src_f0
        df_norm = (dst_fc - src_fc) / src_span if src_span > 0 else 0.0
        affine = affine_translate(dt=0.0, df=df_norm)

        # Load audio and convert to torch
        audio_path = p.get("audio_path")
        if audio_path:
            _sr, data = _load_audio_float(audio_path)
            sig = torch.from_numpy(data)
        else:
            raise ValueError("Transplant requires an audio file path")

        result = transplant(sig, sr, src, affine)

        out = result.signal.numpy()
        if normalize:
            peak = max(np.abs(out).max(), 1e-12)
            out = out / peak * 0.8
        else:
            out = np.clip(out, -1.0, 1.0)

        i16 = (out * 32767).clip(-32768, 32767).astype(np.int16)
        stereo = np.column_stack([i16, i16])

        job.result_stereo = stereo
        job.duration = duration
        job.view_t0 = src_t0
        job.view_t1 = src_t1
        job.transplant_result = result  # stash for uncertainty display

    def remove_job(self, job_id: int) -> None:
        with self._lock:
            self.jobs = [j for j in self.jobs if j.job_id != job_id]

    # -- list sync ---------------------------------------------------------

    def _sync_list(self) -> None:
        items: list[ListItem] = []
        with self._lock:
            for j in self.jobs:
                tag = j.status
                color_key = {"done": "Ch2", "running": "Ch3",
                             "error": "Ch1", "queued": "none"}.get(j.status, "none")
                items.append(ListItem(
                    key=str(j.job_id),
                    display_name=j.label,
                    tag=tag,
                    tag_color_key=color_key,
                ))
        self.job_list.items = items

    # -- render ------------------------------------------------------------

    def _render_dropdown_btn(self, surf: pygame.Surface, font: Any,
                             y: int, w: int, key: str, prefix: str,
                             options: list[str], sel_idx: int) -> int:
        lbl = font.render(prefix, True, (160, 160, 160))
        surf.blit(lbl, (self.PAD, y + 2))
        btn_x = 80
        btn_w = w - btn_x - self.PAD
        btn_rect = pygame.Rect(btn_x, y, btn_w, self.ROW_H)
        bg = (80, 80, 120) if self._active_dropdown == key else (60, 60, 80)
        pygame.draw.rect(surf, bg, btn_rect)
        pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
        txt = font.render(options[sel_idx] if 0 <= sel_idx < len(options)
                          else "?", True, (220, 220, 220))
        surf.blit(txt, (btn_x + 4, y + 3))
        self._ctrl_rects[key] = btn_rect
        return y + self.ROW_H + 2

    def _render_toggle_btn(self, surf: pygame.Surface, font: Any,
                           y: int, w: int, key: str, label: str,
                           state: bool) -> int:
        btn_rect = pygame.Rect(self.PAD, y, w - 2 * self.PAD, self.ROW_H)
        bg = (50, 100, 60) if state else (60, 60, 80)
        pygame.draw.rect(surf, bg, btn_rect)
        pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
        mark = "\u2713 " if state else "  "
        txt = font.render(mark + label, True, (220, 220, 220))
        surf.blit(txt, (self.PAD + 4, y + 3))
        self._ctrl_rects[key] = btn_rect
        return y + self.ROW_H + 2

    def _render_action_btn(self, surf: pygame.Surface, font: Any,
                           x: int, y: int, bw: int, key: str,
                           label: str, enabled: bool,
                           color: tuple[int, int, int] = (60, 80, 160)) -> int:
        btn_rect = pygame.Rect(x, y, bw, self.ROW_H)
        bg = color if enabled else (45, 45, 55)
        pygame.draw.rect(surf, bg, btn_rect)
        pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
        tc = (220, 220, 220) if enabled else (90, 90, 100)
        txt = font.render(label, True, tc)
        surf.blit(txt, (x + 4, y + 3))
        self._ctrl_rects[key] = btn_rect
        return x + bw + 4

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._sync_list()
        self._play_rects.clear()
        self._del_rects.clear()
        self._ctrl_rects.clear()

        # --- Controls section ---
        cur_phase = self._get_phase_mode()
        phase_idx = (self._PHASE_KEYS.index(cur_phase)
                     if cur_phase in self._PHASE_KEYS else 0)
        cur_bands = self._get_fb_n_bands()
        bands_idx = (self._FB_BAND_VALUES.index(cur_bands)
                     if cur_bands in self._FB_BAND_VALUES else 2)

        est_h = 800
        surf = pygame.Surface((w, est_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))
        y = self.PAD

        # Section: iCQT phase mode
        y = self._render_dropdown_btn(surf, font, y, w, "phase_mode",
                                      "Phase:", self._PHASE_OPTIONS, phase_idx)

        # Section: Normalize toggle
        y = self._render_toggle_btn(surf, font, y, w, "normalize",
                                    "Normalize Loudness",
                                    self._get_normalize())

        # Section: Use viewer adjustments toggle
        y = self._render_toggle_btn(surf, font, y, w, "use_adjusted",
                                    "Apply Viewer Adjustments",
                                    self.use_adjusted)

        # Section: Synth mode dropdown
        y = self._render_dropdown_btn(surf, font, y, w, "synth_mode",
                                      "Synth:", self._SYNTH_MODE_OPTIONS,
                                      self.synth_mode_idx)

        # Section: Transplant destination (only when transplant mode is active)
        cur_smode = self._SYNTH_MODE_KEYS[self.synth_mode_idx]
        if cur_smode == "transplant":
            hdr = font.render("── Transplant Dst ──", True, (140, 180, 220))
            surf.blit(hdr, (self.PAD, y + 2))
            y += self.ROW_H

            # Dst F0
            f0_lbl = font.render(f"Lo: {self.transplant_dst_f0:.1f} Hz",
                                 True, (200, 200, 200))
            surf.blit(f0_lbl, (self.PAD, y + 2))
            minus_rect = pygame.Rect(w - self.PAD - 2 * self.BTN_W - 4, y,
                                     self.BTN_W, self.ROW_H)
            plus_rect = pygame.Rect(w - self.PAD - self.BTN_W, y,
                                    self.BTN_W, self.ROW_H)
            for r, txt in [(minus_rect, "−"), (plus_rect, "+")]:
                pygame.draw.rect(surf, (60, 60, 80), r)
                pygame.draw.rect(surf, (100, 100, 120), r, 1)
                t = font.render(txt, True, (220, 220, 220))
                surf.blit(t, (r.x + r.w // 2 - t.get_width() // 2,
                              r.y + 3))
            self._ctrl_rects["txp_f0_minus"] = minus_rect
            self._ctrl_rects["txp_f0_plus"] = plus_rect
            y += self.ROW_H + 2

            # Dst F1
            f1_lbl = font.render(f"Hi: {self.transplant_dst_f1:.1f} Hz",
                                 True, (200, 200, 200))
            surf.blit(f1_lbl, (self.PAD, y + 2))
            minus_rect = pygame.Rect(w - self.PAD - 2 * self.BTN_W - 4, y,
                                     self.BTN_W, self.ROW_H)
            plus_rect = pygame.Rect(w - self.PAD - self.BTN_W, y,
                                    self.BTN_W, self.ROW_H)
            for r, txt in [(minus_rect, "−"), (plus_rect, "+")]:
                pygame.draw.rect(surf, (60, 60, 80), r)
                pygame.draw.rect(surf, (100, 100, 120), r, 1)
                t = font.render(txt, True, (220, 220, 220))
                surf.blit(t, (r.x + r.w // 2 - t.get_width() // 2,
                              r.y + 3))
            self._ctrl_rects["txp_f1_minus"] = minus_rect
            self._ctrl_rects["txp_f1_plus"] = plus_rect
            y += self.ROW_H + 2

        # Section: Synthesize button
        has_synth = self._has_synth()
        has_audio = self._has_audio()
        has_wavelet = self._has_wavelet()
        cur_smode = self._SYNTH_MODE_KEYS[self.synth_mode_idx]
        can_synth = has_synth and (
            cur_smode in ("icqt", "fb_tf")
            or (cur_smode in ("fb", "hybrid", "transplant") and has_audio)
            or (cur_smode == "wavelet" and has_wavelet)
            or (cur_smode == "hybrid_cwt" and has_wavelet and has_audio)
        )
        btn_w = w - 2 * self.PAD
        self._render_action_btn(surf, font, self.PAD, y, btn_w,
                                "synth_go", "Synthesize", can_synth,
                                color=(50, 80, 140))
        y += self.ROW_H + 4

        # Section: Filterbank bands
        y = self._render_dropdown_btn(surf, font, y, w, "fb_n_bands",
                                      "FB Bands:", self._FB_BAND_OPTIONS, bands_idx)

        # Section: Channel Routing
        pygame.draw.line(surf, (60, 60, 70), (self.PAD, y),
                         (w - self.PAD, y))
        y += 2
        hdr = font.render("\u2500\u2500 Channel Routing \u2500\u2500",
                          True, (180, 180, 180))
        surf.blit(hdr, (self.PAD, y + 2))
        y += self.ROW_H + 2

        routing = self.channel_routing
        n_src = len(ROUTE_SOURCES)
        lbl_w = 60  # width for role label
        avail_w = w - self.PAD - lbl_w - self.PAD
        col_w = max(36, avail_w // n_src)  # auto-size for 5 buttons
        for audio_ch in ROUTE_AUDIO_CHANNELS:
            ch_label = ROUTE_AUDIO_CH_LABELS[audio_ch]
            ch_hdr = font.render(f"{ch_label}:", True, (140, 180, 220))
            surf.blit(ch_hdr, (self.PAD, y + 2))
            y += self.ROW_H
            for role in ROUTE_ROLES:
                role_lbl = ROUTE_ROLE_LABELS[role]
                rl = font.render(role_lbl, True, (140, 140, 150))
                surf.blit(rl, (self.PAD + 8, y + 3))
                bx = self.PAD + lbl_w
                cur_src = routing.get(audio_ch, role)
                for src in ROUTE_SOURCES:
                    btn_key = f"rt_{audio_ch}_{role}_{src}"
                    active = (cur_src == src)
                    # Tint button with the channel's hue colour
                    tint = _TGT_COLORS.get(src, (80, 80, 80))
                    if active:
                        bg = tint
                    else:
                        bg = (tint[0] // 4, tint[1] // 4, tint[2] // 4)
                    br = pygame.Rect(bx, y, col_w - 2, self.ROW_H)
                    pygame.draw.rect(surf, bg, br)
                    border = tint if not active else (220, 220, 220)
                    pygame.draw.rect(surf, border, br, 1)
                    tc = (255, 255, 255) if active else tint
                    st = font.render(src, True, tc)
                    surf.blit(st, (bx + col_w // 2 - st.get_width() // 2,
                                   y + 3))
                    self._ctrl_rects[btn_key] = br
                    bx += col_w
                y += self.ROW_H + 2

        # Mono mix mode selector
        y = self._render_dropdown_btn(surf, font, y, w, "mono_mix",
                                      "Mono Mix:", MONO_MIX_MODES,
                                      routing.mono_mix_mode)

        # Separator
        pygame.draw.line(surf, (60, 60, 70), (self.PAD, y),
                         (w - self.PAD, y))
        y += 4

        ctrl_h = y  # height consumed by the controls section

        # Job list rendering
        y_after_list = self.job_list.render(surf, font, 0, ctrl_h, w)
        y_cur = ctrl_h + y_after_list

        # Action buttons for selected job
        sel_job = self._selected_job()
        if sel_job is not None:
            pad = self.PAD
            bx = pad
            if sel_job.status == "done":
                is_playing = (self._playing_job_id == sel_job.job_id)
                play_label = "Stop" if is_playing else "Play"
                play_color = (200, 80, 80) if is_playing else (60, 160, 80)
                pr = pygame.Rect(bx, y_cur, self.BTN_W, self.ROW_H)
                pygame.draw.rect(surf, play_color, pr)
                pygame.draw.rect(surf, (200, 200, 200), pr, 1)
                lbl = font.render(play_label, True, (255, 255, 255))
                surf.blit(lbl, (bx + 4, y_cur + 3))
                self._play_rects[sel_job.job_id] = pr
                bx += self.BTN_W + 4
            if sel_job.duration > 0:
                dur_txt = f"{sel_job.duration:.2f}s"
                dtl = font.render(dur_txt, True, (160, 160, 160))
                surf.blit(dtl, (bx, y_cur + 3))
                bx += dtl.get_width() + 8
            if sel_job.status == "error":
                etl = font.render(sel_job.error_msg[:30], True, (255, 80, 80))
                surf.blit(etl, (bx, y_cur + 3))
            del_w = 26
            del_x = w - pad - del_w
            dr = pygame.Rect(del_x, y_cur, del_w, self.ROW_H)
            pygame.draw.rect(surf, (120, 40, 40), dr)
            pygame.draw.rect(surf, (200, 200, 200), dr, 1)
            xl = font.render("X", True, (255, 255, 255))
            surf.blit(xl, (del_x + 7, y_cur + 3))
            self._del_rects[sel_job.job_id] = dr
            y_cur += self.ROW_H + 4

        # Crop the oversized surface to actual content
        final_h = max(y_cur + self.PAD, ctrl_h + 30)
        final_surf = pygame.Surface((w, final_h), pygame.SRCALPHA)
        final_surf.blit(surf, (0, 0))
        return final_surf

    def _selected_job(self) -> SynthJob | None:
        idx = self.job_list.selected_idx
        with self._lock:
            if 0 <= idx < len(self.jobs):
                return self.jobs[idx]
        return None

    # -- events ------------------------------------------------------------

    _PHASE_KEYS = ["original", "griffin_lim", "zero_phase", "freq_carrier"]
    _PHASE_OPTIONS = ["Original Phase", "Griffin-Lim", "Zero Phase", "Freq Carrier"]
    _FB_BAND_VALUES = [4, 8, 16, 32, 64]
    _FB_BAND_OPTIONS = ["4", "8", "16", "32", "64"]

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False
        pr = self.panel_rect

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos

            # Dropdown overlay gets first priority (screen coords)
            if self._active_dropdown:
                for i, ir in enumerate(self._dropdown_item_rects):
                    if ir.collidepoint(mx, my):
                        self._select_dropdown(i)
                        return True
                self._active_dropdown = None
                return True

            if not pr.collidepoint(mx, my):
                return False
            lx, ly = mx - pr.x, my - pr.y
            ly += self._panel_scroll_y

            # Controls
            for key, rect in self._ctrl_rects.items():
                if rect.collidepoint(lx, ly):
                    if key == "phase_mode":
                        self._open_dropdown("phase_mode",
                                            self._PHASE_OPTIONS,
                                            pygame.Rect(rect.x,
                                                        rect.y + rect.h,
                                                        rect.w, 0))
                    elif key == "normalize":
                        self._set_normalize(not self._get_normalize())
                    elif key == "use_adjusted":
                        self.use_adjusted = not self.use_adjusted
                    elif key == "synth_mode":
                        self._open_dropdown("synth_mode",
                                            self._SYNTH_MODE_OPTIONS,
                                            pygame.Rect(rect.x,
                                                        rect.y + rect.h,
                                                        rect.w, 0))
                    elif key == "synth_go":
                        smode = self._SYNTH_MODE_KEYS[self.synth_mode_idx]
                        if smode == "icqt" and self._has_synth() and self.on_synth_icqt:
                            self.on_synth_icqt()
                        elif smode == "fb" and self._has_synth() and self._has_audio() and self.on_synth_fb:
                            self.on_synth_fb()
                        elif smode == "hybrid" and self._has_synth() and self._has_audio() and self.on_synth_hybrid:
                            self.on_synth_hybrid()
                        elif smode == "fb_tf" and self._has_synth() and self.on_synth_fb_tf:
                            self.on_synth_fb_tf()
                        elif smode == "wavelet" and self._has_wavelet() and self.on_synth_wavelet:
                            self.on_synth_wavelet()
                        elif smode == "transplant" and self._has_synth() and self._has_audio() and self.on_synth_transplant:
                            self.on_synth_transplant()
                        elif smode == "hybrid_cwt" and self._has_synth() and self._has_wavelet() and self.on_synth_hybrid_cwt:
                            self.on_synth_hybrid_cwt()
                    elif key == "fb_n_bands":
                        self._open_dropdown("fb_n_bands",
                                            self._FB_BAND_OPTIONS,
                                            pygame.Rect(rect.x,
                                                        rect.y + rect.h,
                                                        rect.w, 0))
                    elif key.startswith("txp_f"):
                        # Transplant destination freq ±
                        step = 10.0
                        if key == "txp_f0_minus":
                            self.transplant_dst_f0 = max(1.0, self.transplant_dst_f0 - step)
                        elif key == "txp_f0_plus":
                            self.transplant_dst_f0 = min(self.transplant_dst_f1 - 1.0,
                                                         self.transplant_dst_f0 + step)
                        elif key == "txp_f1_minus":
                            self.transplant_dst_f1 = max(self.transplant_dst_f0 + 1.0,
                                                         self.transplant_dst_f1 - step)
                        elif key == "txp_f1_plus":
                            self.transplant_dst_f1 += step
                    elif key == "mono_mix":
                        self._open_dropdown("mono_mix",
                                            MONO_MIX_MODES,
                                            pygame.Rect(rect.x,
                                                        rect.y + rect.h,
                                                        rect.w, 0))
                    elif key.startswith("rt_"):
                        # rt_{audio_ch}_{role}_{source}
                        parts = key.split("_", 3)
                        if len(parts) == 4:
                            _, audio_ch, role, source = parts
                            self.channel_routing.set(audio_ch, role, source)

                    return True

            # Job action buttons
            for jid, rect in self._play_rects.items():
                if rect.collidepoint(lx, ly):
                    self._on_play_click(jid)
                    return True
            for jid, rect in self._del_rects.items():
                if rect.collidepoint(lx, ly):
                    self.remove_job(jid)
                    return True

            hit = self.job_list.handle_click(lx, ly)
            if hit is not None:
                return True
            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEMOTION:
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEWHEEL:
            return self._handle_panel_wheel(event)

        return False

    def _open_dropdown(self, key: str, options: list[str],
                       anchor: pygame.Rect) -> None:
        self._active_dropdown = key
        self._dropdown_opts = options
        self._dropdown_rect = anchor

    def _select_dropdown(self, idx: int) -> None:
        key = self._active_dropdown
        self._active_dropdown = None
        if key == "phase_mode" and 0 <= idx < len(self._PHASE_KEYS):
            self._set_phase_mode(self._PHASE_KEYS[idx])
        elif key == "synth_mode" and 0 <= idx < len(self._SYNTH_MODE_KEYS):
            self.synth_mode_idx = idx
        elif key == "fb_n_bands" and 0 <= idx < len(self._FB_BAND_VALUES):
            self._set_fb_n_bands(self._FB_BAND_VALUES[idx])
        elif key == "mono_mix" and 0 <= idx < len(MONO_MIX_MODES):
            self.channel_routing.mono_mix_mode = idx


    def render_dropdown_overlay(self) -> pygame.Surface | None:
        if not self._active_dropdown:
            return None
        opts = self._dropdown_opts
        if not opts:
            return None
        self._ensure_font()
        font = self.font
        pr = self.panel_rect
        item_h = self.ROW_H
        ow = self._dropdown_rect.w
        oh = len(opts) * item_h
        overlay = pygame.Surface((ow, oh), pygame.SRCALPHA)
        overlay.fill((40, 40, 55, 240))
        self._dropdown_item_rects = []
        for i, label in enumerate(opts):
            iy = i * item_h
            # Screen-space rect for hit-testing in handle_event
            ir_screen = pygame.Rect(pr.x + self._dropdown_rect.x,
                                    pr.y + self._dropdown_rect.y + iy
                                    - self._panel_scroll_y,
                                    ow, item_h)
            self._dropdown_item_rects.append(ir_screen)
            pygame.draw.rect(overlay, (60, 60, 80), (0, iy, ow, item_h), 1)
            txt = font.render(label, True, (220, 220, 220))
            overlay.blit(txt, (4, iy + 3))
        return overlay

    def _on_play_click(self, job_id: int) -> None:
        if self._playing_job_id == job_id:
            # Stop
            self._playing_job_id = None
            if self.on_stop:
                self.on_stop()
            return
        with self._lock:
            job = next((j for j in self.jobs if j.job_id == job_id), None)
        if job is None or job.result_stereo is None:
            return
        self._playing_job_id = job_id
        if self.on_play:
            self.on_play(job)


# ---------------------------------------------------------------------------
# Image input panel — load images and convert to TF / TSC / FB
# ---------------------------------------------------------------------------

_IMG_CONVERT_MODES = ["TF", "TSC", "FB"]
_IMG_CONVERT_LABELS = {
    "TF": "Time-Frequency",
    "TSC": "Time-Scale Coefficients",
    "FB": "Filterbank (TF)",
}
_IMG_INTERP_MODES = ["bilinear", "bicubic", "nearest", "lanczos"]
_IMG_EXTENSIONS = {".png", ".jpg", ".jpeg", ".bmp", ".tiff", ".tif", ".webp"}


class ImageInputPanel(Panel):
    """Panel for loading image files, converting them to TF representations.

    Images can be converted to:
    * TF — mapped directly to time-frequency magnitude/phase arrays
    * TSC — treated as time-scale coefficient arrays
    * FB — mapped to filterbank envelope arrays

    Configurable: frequency range, time range, interpolation, target
    dimensions (bins × frames).
    """

    PANEL_W = 280
    ROW_H = 22
    PAD = 6

    def __init__(self, *, side: str = "left",
                 image_dir: str = "") -> None:
        super().__init__(title="Image Input", side=side)
        self.image_dir: str = image_dir or os.path.join(
            os.path.dirname(os.path.abspath(__file__)), "input_images")
        os.makedirs(self.image_dir, exist_ok=True)

        # Image file list
        self.image_list = ScrollableItemList("Image Files", max_visible=8)
        self._image_paths: list[str] = []
        self._refresh_images()

        # Conversion settings
        self.convert_mode_idx: int = 0   # index into _IMG_CONVERT_MODES
        self.interp_idx: int = 0         # index into _IMG_INTERP_MODES
        self.target_bins: int = 1200     # frequency bins
        self.target_frames: int = 1000   # time frames
        self.freq_min: float = 16.35     # Hz (C0)
        self.freq_max: float = 19912.13  # Hz (~D#9)
        self.time_start: float = 0.0     # seconds

        # Result data (populated after conversion)
        self._converted_data: np.ndarray | None = None
        self._converted_mode: str | None = None

        # UI state
        self._ctrl_rects: dict[str, pygame.Rect] = {}
        self._active_dropdown: str | None = None
        self._dropdown_opts: list[str] = []
        self._dropdown_rect: pygame.Rect = pygame.Rect(0, 0, 0, 0)
        self._dropdown_item_rects: list[pygame.Rect] = []
        self._dragging: str | None = None
        self._item_map: dict[str, tuple[pygame.Rect, Any]] = {}
        self._status_msg: str = ""

        # Callback: (data, mode, freq_range, time_range) -> None
        self.on_converted: Any = None

    # -- scanning -----------------------------------------------------------

    def _refresh_images(self) -> None:
        self._image_paths = []
        items: list[ListItem] = []
        if os.path.isdir(self.image_dir):
            for fn in sorted(os.listdir(self.image_dir)):
                ext = os.path.splitext(fn)[1].lower()
                if ext in _IMG_EXTENSIONS:
                    self._image_paths.append(
                        os.path.join(self.image_dir, fn))
                    items.append(ListItem(
                        key=fn, display_name=fn,
                        tag=ext, tag_color_key="none"))
        self.image_list.items = items

    # -- conversion ---------------------------------------------------------

    def _load_image_as_array(self, path: str) -> np.ndarray:
        """Load image file as float array, shape (H, W) or (H, W, C)."""
        from PIL import Image
        img = Image.open(path)
        arr = np.asarray(img)
        return arr

    def _interpolate_2d(self, data: np.ndarray,
                        out_h: int, out_w: int) -> np.ndarray:
        """Resize 2D array to (out_h, out_w) using selected interpolation."""
        from scipy.ndimage import zoom
        mode = _IMG_INTERP_MODES[self.interp_idx]
        order = {"nearest": 0, "bilinear": 1, "bicubic": 3,
                 "lanczos": 5}.get(mode, 1)
        h, w = data.shape[:2]
        if h == 0 or w == 0:
            return np.zeros((out_h, out_w), dtype=data.dtype)
        factor_h = out_h / h
        factor_w = out_w / w
        if data.ndim == 2:
            return zoom(data, (factor_h, factor_w), order=order)
        # Multi-channel: zoom spatial dims only
        return zoom(data, (factor_h, factor_w, 1), order=order)

    def convert_selected(self) -> None:
        """Convert the currently selected image to the chosen format."""
        idx = self.image_list.selected_idx
        if idx < 0 or idx >= len(self._image_paths):
            self._status_msg = "No image selected"
            return
        path = self._image_paths[idx]
        mode = _IMG_CONVERT_MODES[self.convert_mode_idx]
        try:
            raw = self._load_image_as_array(path)
        except Exception as exc:
            self._status_msg = f"Load error: {exc}"
            return

        # Convert to grayscale intensity if multi-channel
        if raw.ndim == 3:
            if raw.shape[2] == 4:
                # RGBA — use alpha-premultiplied luminance
                rgb = raw[:, :, :3].astype(np.float64)
                alpha = raw[:, :, 3:4].astype(np.float64) / 255.0
                gray = (0.2126 * rgb[:, :, 0] + 0.7152 * rgb[:, :, 1]
                        + 0.0722 * rgb[:, :, 2]) * alpha[:, :, 0]
            else:
                gray = (0.2126 * raw[:, :, 0].astype(np.float64)
                        + 0.7152 * raw[:, :, 1].astype(np.float64)
                        + 0.0722 * raw[:, :, 2].astype(np.float64))
        else:
            gray = raw.astype(np.float64)

        # Normalise to 0–1
        vmin, vmax = gray.min(), gray.max()
        if vmax > vmin:
            gray = (gray - vmin) / (vmax - vmin)
        else:
            gray = np.zeros_like(gray)

        # Resize to target dimensions: (bins, frames)
        resized = self._interpolate_2d(
            gray, self.target_bins, self.target_frames)

        self._converted_data = resized
        self._converted_mode = mode
        self._status_msg = (f"Converted: {resized.shape[0]}×{resized.shape[1]}"
                            f" ({mode})")

        if self.on_converted:
            freq_range = (self.freq_min, self.freq_max)
            time_range = (self.time_start,
                          self.time_start + self.time_duration)
            self.on_converted(resized, mode, freq_range, time_range)

    # -- render -------------------------------------------------------------

    def render(self) -> pygame.Surface | None:
        if not self.visible:
            return None
        self._ensure_font()
        font = self.font
        w = self.PANEL_W
        self._ctrl_rects.clear()
        self._item_map.clear()
        self._refresh_images()

        est_h = 700
        surf = pygame.Surface((w, est_h), pygame.SRCALPHA)
        surf.fill((30, 30, 30, 210))
        y = self.PAD

        # Section: Image file list
        data_h = self.image_list.render(surf, font, 0, y, w)
        y += data_h

        # Separator
        pygame.draw.line(surf, (60, 60, 70), (self.PAD, y),
                         (w - self.PAD, y))
        y += 4

        # Section: Convert mode dropdown
        lbl = font.render("Output:", True, (160, 160, 160))
        surf.blit(lbl, (self.PAD, y + 2))
        btn_x = 80
        btn_w = w - btn_x - self.PAD
        btn_rect = pygame.Rect(btn_x, y, btn_w, self.ROW_H)
        bg = (80, 80, 120) if self._active_dropdown == "conv_mode" \
            else (60, 60, 80)
        pygame.draw.rect(surf, bg, btn_rect)
        pygame.draw.rect(surf, (100, 100, 120), btn_rect, 1)
        ct = font.render(
            _IMG_CONVERT_LABELS[_IMG_CONVERT_MODES[self.convert_mode_idx]],
            True, (220, 220, 220))
        surf.blit(ct, (btn_x + 4, y + 3))
        self._ctrl_rects["conv_mode"] = btn_rect
        y += self.ROW_H + 2

        # Section: Interpolation dropdown
        lbl2 = font.render("Interp:", True, (160, 160, 160))
        surf.blit(lbl2, (self.PAD, y + 2))
        btn_rect2 = pygame.Rect(btn_x, y, btn_w, self.ROW_H)
        bg2 = (80, 80, 120) if self._active_dropdown == "interp" \
            else (60, 60, 80)
        pygame.draw.rect(surf, bg2, btn_rect2)
        pygame.draw.rect(surf, (100, 100, 120), btn_rect2, 1)
        it = font.render(_IMG_INTERP_MODES[self.interp_idx],
                         True, (220, 220, 220))
        surf.blit(it, (btn_x + 4, y + 3))
        self._ctrl_rects["interp"] = btn_rect2
        y += self.ROW_H + 2

        # Section: Sliders for bins, frames, freq, time
        slider_defs = [
            ("bins", "Bins:", self.target_bins, 64, 4800),
            ("frames", "Frames:", self.target_frames, 100, 10000),
            ("freq_min", "Freq Lo:", self.freq_min, 1.0, 20000.0),
            ("freq_max", "Freq Hi:", self.freq_max, 10.0, 22050.0),
        ]
        for key, label, val, vmin, vmax in slider_defs:
            sl = font.render(label, True, (140, 140, 150))
            surf.blit(sl, (self.PAD, y + 3))
            # Value
            if isinstance(val, int):
                vt = font.render(str(val), True, (200, 200, 200))
            else:
                vt = font.render(f"{val:.1f}", True, (200, 200, 200))
            surf.blit(vt, (self.PAD + 72, y + 3))

            # +/- buttons
            minus_r = pygame.Rect(w - self.PAD - 44, y, 20, self.ROW_H)
            plus_r = pygame.Rect(w - self.PAD - 22, y, 20, self.ROW_H)
            pygame.draw.rect(surf, (50, 50, 65), minus_r)
            pygame.draw.rect(surf, (80, 80, 100), minus_r, 1)
            m_lbl = font.render("\u2212", True, (180, 180, 180))
            surf.blit(m_lbl, (minus_r.x + 5, y + 3))
            pygame.draw.rect(surf, (50, 50, 65), plus_r)
            pygame.draw.rect(surf, (80, 80, 100), plus_r, 1)
            p_lbl = font.render("+", True, (180, 180, 180))
            surf.blit(p_lbl, (plus_r.x + 5, y + 3))
            self._ctrl_rects[f"{key}_minus"] = minus_r
            self._ctrl_rects[f"{key}_plus"] = plus_r
            y += self.ROW_H + 2

        # Convert button
        y += 2
        conv_btn = pygame.Rect(self.PAD, y, w - 2 * self.PAD, self.ROW_H)
        pygame.draw.rect(surf, (50, 80, 140), conv_btn)
        pygame.draw.rect(surf, (100, 100, 120), conv_btn, 1)
        cl = font.render("Convert Image", True, (220, 220, 220))
        surf.blit(cl, (w // 2 - cl.get_width() // 2, y + 3))
        self._ctrl_rects["convert_go"] = conv_btn
        y += self.ROW_H + 4

        # Status line
        if self._status_msg:
            st = font.render(self._status_msg[:40], True, (160, 160, 160))
            surf.blit(st, (self.PAD, y + 2))
            y += self.ROW_H + 2

        # Crop
        final_h = max(y + self.PAD, 100)
        final_surf = pygame.Surface((w, final_h), pygame.SRCALPHA)
        final_surf.blit(surf, (0, 0))
        return final_surf

    # -- events -------------------------------------------------------------

    def handle_event(self, event: pygame.event.Event) -> bool:
        if not self.visible:
            return False
        pr = self.panel_rect

        if event.type == MOUSEBUTTONDOWN and event.button == 1:
            mx, my = event.pos

            # Dropdown overlay first
            if self._active_dropdown:
                for i, ir in enumerate(self._dropdown_item_rects):
                    if ir.collidepoint(mx, my):
                        self._select_dropdown(i)
                        return True
                self._active_dropdown = None
                return True

            if not pr.collidepoint(mx, my):
                return False
            lx, ly = mx - pr.x, my - pr.y
            ly += self._panel_scroll_y

            # Image list click
            hit = self.image_list.handle_click(lx, ly)
            if hit is not None:
                return True

            # Controls
            for key, rect in self._ctrl_rects.items():
                if rect.collidepoint(lx, ly):
                    if key == "conv_mode":
                        self._open_dropdown(
                            "conv_mode",
                            [_IMG_CONVERT_LABELS[m]
                             for m in _IMG_CONVERT_MODES],
                            rect)
                    elif key == "interp":
                        self._open_dropdown("interp",
                                            _IMG_INTERP_MODES, rect)
                    elif key == "convert_go":
                        self.convert_selected()
                    elif key.endswith("_minus") or key.endswith("_plus"):
                        self._nudge_slider(key)
                    return True

            return True

        if event.type == MOUSEBUTTONUP and event.button == 1:
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEMOTION:
            mx, my = event.pos
            if pr.collidepoint(mx, my):
                return True

        if event.type == MOUSEWHEEL:
            return self._handle_panel_wheel(event)

        return False

    def _open_dropdown(self, key: str, options: list[str],
                       anchor: pygame.Rect) -> None:
        self._active_dropdown = key
        self._dropdown_opts = options
        self._dropdown_rect = anchor

    def _select_dropdown(self, idx: int) -> None:
        key = self._active_dropdown
        self._active_dropdown = None
        if key == "conv_mode" and 0 <= idx < len(_IMG_CONVERT_MODES):
            self.convert_mode_idx = idx
        elif key == "interp" and 0 <= idx < len(_IMG_INTERP_MODES):
            self.interp_idx = idx

    def _nudge_slider(self, btn_key: str) -> None:
        """Handle +/- button clicks for value sliders."""
        base = btn_key.rsplit("_", 1)[0]
        direction = 1 if btn_key.endswith("_plus") else -1
        if base == "bins":
            step = 100 * direction
            self.target_bins = max(64, min(4800,
                                           self.target_bins + step))
        elif base == "frames":
            step = 100 * direction
            self.target_frames = max(100, min(10000,
                                              self.target_frames + step))
        elif base == "freq_min":
            step = 10.0 * direction
            self.freq_min = max(1.0, min(self.freq_max - 10,
                                         self.freq_min + step))
        elif base == "freq_max":
            step = 100.0 * direction
            self.freq_max = max(self.freq_min + 10,
                                min(22050.0, self.freq_max + step))


    def render_dropdown_overlay(self) -> pygame.Surface | None:
        if not self._active_dropdown:
            return None
        opts = self._dropdown_opts
        if not opts:
            return None
        self._ensure_font()
        font = self.font
        pr = self.panel_rect
        item_h = self.ROW_H
        ow = self._dropdown_rect.w
        oh = len(opts) * item_h
        overlay = pygame.Surface((ow, oh), pygame.SRCALPHA)
        overlay.fill((40, 40, 55, 240))
        self._dropdown_item_rects = []
        for i, label in enumerate(opts):
            iy = i * item_h
            rect = pygame.Rect(
                pr.x + self._dropdown_rect.x,
                pr.y + self._dropdown_rect.y + self._dropdown_rect.h + iy
                - self._panel_scroll_y,
                ow, item_h)
            self._dropdown_item_rects.append(rect)
            txt = font.render(label, True, (220, 220, 220))
            overlay.blit(txt, (4, iy + 3))
            if i < len(opts) - 1:
                pygame.draw.line(overlay, (60, 60, 70),
                                 (0, iy + item_h - 1),
                                 (ow, iy + item_h - 1))
        pygame.draw.rect(overlay, (100, 100, 130),
                         pygame.Rect(0, 0, ow, oh), 1)
        return overlay


